// Selecting a town pins coordinates and pre-fills zone + rainfall (still editable).
function selectTown(name){
  if(name === "Other"){
    state.town = "Other";
    // A custom point has no baked climate: fall back to the bundled normal for
    // irrigation, and skip temperature suitability (no monthly temps to test against).
    state.climateEto = null; state.climateRain = null;
    state.climateTmax = null; state.climateTmin = null; state.climateTminext = null;
    state.climateLabel = "bundled Perth fallback";
  } else {
    const t = TOWNS.find(x => x.n === name);
    if(t){
      state.town = t.n; state.lat = t.lat; state.lon = t.lon; state.climateZone = t.z;
      const c = CLIMATE_DB[t.n];
      if(c){
        state.climateEto = c.eto; state.climateRain = c.rain;
        state.climateTmax = c.tmax; state.climateTmin = c.tmin; state.climateTminext = c.tminext;
        state.climateLabel = t.n + " - SILO 2005-2024";
        // Actual SILO 2005-2024 annual rainfall — replaces the town-list estimate.
        state.annualRainfall = Math.round(c.rain.reduce((a,b) => a + b, 0));
      } else {
        state.annualRainfall = t.r;   // fallback estimate only if no baked climate exists
      }
    }
  }
  state.checkedCrops = null; state.plan = null; renderApp();
}


const MONTHS=["jan","feb","mar","apr","may","jun","jul","aug","sep","oct","nov","dec"];
const MONTH_INITIALS=["J","F","M","A","M","J","J","A","S","O","N","D"];
const MONTH_NAMES=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
// Escape a name for safe interpolation inside single-quoted JS strings within
// double-quoted inline HTML event handlers (single source of truth - use everywhere).
function escJs(s){return String(s).replace(/\\/g,"\\\\").replace(/\x27/g,"\\\x27").replace(/"/g,"&quot;")}
// Broadcast/drill-sown crops shown as row-metres rather than plant counts.
// Single source of truth for plantCount / plantsToHa / plantUnit.
const BROADCAST_CROPS = new Set(["Wheat (Whole)","Barley (Pearl)","Rye (Grain)","Oats (Rolled)","Spelt",
  "Triticale","Rice (White)","Rice (Brown)","Rice (Wild)","Sorghum","Millet","Buckwheat",
  "Quinoa","Amaranth (Grain)","Teff","Fonio","African Rice","Corn (Sweet)","Sago",
  "Linseed / Flaxseed","Sesame Seed","Chia Seed","Hemp Seed","Sunflower Seed",
  "Onion (Spring)"]);
// ── 12-group dietary taxonomy (grain+tubers merged into 'starches') ──────────
// Internal keys (replaces the old 6-group veg/fruit/starchy/protein/dairy/oils).
const FG_KEYS=["darkgreen","redorange","othervet","starches","fruit",
               "legumes","nutsseeds","eggs","meat","dairy","herbs","discretionary"];
// Groups with a household quantity floor (actually fed). herbs/discretionary = no floor.
const FLOOR_KEYS=["darkgreen","redorange","othervet","starches","fruit",
                  "legumes","nutsseeds","eggs","meat","dairy"];
// Plant-fresh groups that need monthly fresh-supply coverage. Mirrors the original
// veg+fruit-only rule: the perishable groups. Storable staples (grain, tubers, legumes,
// nuts & seeds) are exempt; herbs are fresh-harvest so included.
const PLANT_FRESH_KEYS=["darkgreen","redorange","othervet","fruit","herbs"];
function zeroFG(){ const o={}; FG_KEYS.forEach(k=>o[k]=0); return o; }
// Canonical display metadata for the 13 groups: [key]: {label, short, tag, color}.
// Single source of truth for NRV bars, diet legend, monthly grid, plan summary tables.
const FG_DISPLAY = {
  darkgreen:    {label:"Dark Green Veg", short:"Greens",  tag:"tag-darkgreen", color:"#2E5E26"},
  redorange:    {label:"Red/Orange Veg", short:"Red/Org", tag:"tag-redorange", color:"#D2832E"},
  othervet:     {label:"Other Veg",      short:"Veg",     tag:"tag-veg",     color:"#6E8C3E"},
  starches:     {label:"Starches",       short:"Starch",  tag:"tag-starch",  color:"#A98C38"},
  fruit:        {label:"Fruit",          short:"Fruit",   tag:"tag-fruit",   color:"#7A4FA8"},
  legumes:      {label:"Legumes",        short:"Legumes", tag:"tag-protein", color:"#8A6A3A"},
  nutsseeds:    {label:"Nuts & Seeds",   short:"Nuts",    tag:"tag-protein", color:"#9A5A3A"},
  eggs:         {label:"Eggs",           short:"Eggs",    tag:"tag-protein", color:"#C8A030"},
  meat:         {label:"Meat",           short:"Meat",    tag:"tag-protein", color:"#8A3A3A"},
  dairy:        {label:"Dairy",          short:"Dairy",   tag:"tag-dairy",   color:"#6A7A8A"},
  herbs:        {label:"Herbs",          short:"Herb",    tag:"tag-herbs",   color:"#5E8C5E"},
  discretionary:{label:"Discretionary",  short:"Disc",    tag:"tag-disc",    color:"#9A9A9A"},
};
// Floored groups only, for display rows that should skip herbs/discretionary unless present.
const FG_DISPLAY_ROWS = FLOOR_KEYS.map(k => [FG_DISPLAY[k].label, k, FG_DISPLAY[k].tag]);
// Bar colours per internal food-group key (shared by Step 4 and Step 5 charts).
const FG_BAR = (function(){const o={};FG_KEYS.forEach(k=>o[k]=FG_DISPLAY[k].color);return o;})();

// ── Umbrella display layer (ADG-5) ───────────────────────────────────────────
// Maps the five umbrella groups to a label + base hue, and gives each member
// sub-group a SHADE of that hue so stacked bars read as one umbrella at a glance
// while the sub-group segments stay distinguishable. Order within `members`
// = light → dark stacking order. Single source of truth for the Step 4 donut,
// the Step 5 coverage rail, and the manual-adjust rail.
const UMBRELLA_DISPLAY = [
  { id:"vegetables", label:"Vegetables", base:"#4E7A34",
    members:[
      { key:"darkgreen", label:"Dark Green", shade:"#2E5E26" },
      { key:"redorange", label:"Red/Orange", shade:"#6E9B3A" },
      { key:"othervet",  label:"Other Veg",  shade:"#9DBE63" },
    ] },
  { id:"fruit", label:"Fruit", base:"#7A4FA8",
    members:[
      { key:"fruit", label:"Fruit", shade:"#7A4FA8" },
    ] },
  { id:"starches", label:"Starches", base:"#B08A2E",
    members:[
      { key:"starches", label:"Tubers & Grain", shade:"#A98C38" },
    ] },
  { id:"protein", label:"Protein", base:"#9A4A3A",
    members:[
      { key:"legumes",   label:"Legumes", shade:"#B5824A" },
      { key:"nutsseeds", label:"Nuts & Seeds", shade:"#9A5A3A" },
      { key:"eggs",      label:"Eggs",    shade:"#C8A030" },
      { key:"meat",      label:"Meat",    shade:"#7A2E2E" },
    ] },
  { id:"dairy", label:"Dairy", base:"#6A7A8A",
    members:[
      { key:"dairy", label:"Dairy", shade:"#6A7A8A" },
    ] },
];
// sub-group key → its umbrella display entry (for quick lookup).
const UMB_OF_KEY = (function(){
  const o = {};
  UMBRELLA_DISPLAY.forEach(u => u.members.forEach(m => { o[m.key] = u; }));
  return o;
})();
// sub-group key → its shade colour.
const SHADE_OF_KEY = (function(){
  const o = {};
  UMBRELLA_DISPLAY.forEach(u => u.members.forEach(m => { o[m.key] = m.shade; }));
  return o;
})();
// Compute an umbrella's combined target / achieved by summing its member sub-keys.
function umbrellaSum(map){
  return UMBRELLA_DISPLAY.map(u => ({
    umb: u,
    members: u.members.map(m => ({ ...m, val: map[m.key] || 0 })),
    total: u.members.reduce((s,m) => s + (map[m.key] || 0), 0),
  }));
}
// Per-crop IN-SEASON daily-rate cap, in serves per person, applied while a crop is
// supplying (harvest + storage window). null = no cap. Set per group to limit how much
// any single crop can dominate its active season — forcing more crops in for diversity.
// Trialled on fruit; add other keys here to extend.
const FG_INSEASON_CAP_PER_PERSON = {
  // (no caps active — fruit trial removed)
};
// Per-crop ceiling as a FRACTION of the group's annual target (v26's diversity mechanism).
// Caps how much any single crop can contribute to a food group, forcing the allocator to
// recruit multiple crops. e.g. 0.20 → no crop fills >20% of the group → at least ~5 crops.
// Applies to fresh groups (the veg sub-groups, fruit, herbs); storables are exempt so they
// can still consolidate to efficient sources. null/absent = no fraction cap for that key.
const FG_FRACTION_CAP = {
  darkgreen: 0.20, redorange: 0.20, othervet: 0.20,
  fruit: 0.20, herbs: 0.20,
};
// Soft diversity bonus: gently rewards adding a NEW crop to a group, fading as the group
// already has several crops (self-limiting — nudges toward variety without forcing an
// impractical count). 0 = off. Applied to allocation sizing, never overrides gap-fill.
// `strength` = how much the first crop's allocation is trimmed (so the group recruits more);
// `fade` = decay per crop already chosen (lower fade = effect dies faster).
// Per-group overrides allowed; `default` applies to any fresh group not listed.
const DIVERSITY_BONUS = {
  default: { strength: 0.35, fade: 0.55 },
  fruit:   { strength: 0.6,  fade: 0.75 },   // fruit: push harder — more variety preferred
};
function diversityCfg(key){ return DIVERSITY_BONUS[key] || DIVERSITY_BONUS.default; }
// Diminishing returns on a single crop: the marginal value of supplying a month decays as
// that month fills up, following a concave curve value = remaining^curve. Higher `curve`
// = steeper drop-off = additional supply to an already-stocked month is worth little, so a
// NEW crop (bringing fresh coverage) out-scores piling more onto an existing one. This makes
// variety win on merit without any hard cap. Per-group; `default` applies if a group isn't listed.
const DIMINISHING = {
  default: { curve: 1.0 },   // 1.0 ≈ current mild behaviour
  fruit:   { curve: 1.3 },   // fruit: mildly diminishing → spreads without slivering
};
function diminishingCfg(key){ return DIMINISHING[key] || DIMINISHING.default; }
// Split the legacy ADG 6-value serves ({veg,fruit,starchy,protein,dairy,oils}) across 13 keys,
// preserving total serving quantity. Ratios are sensible defaults (refine later if desired).
function splitADG(a){
  const veg=a.veg||0, fruit=a.fruit||0, starchy=a.starchy||0, protein=a.protein||0, dairy=a.dairy||0;
  return {
    darkgreen:   veg/3,
    redorange:   veg/3,
    othervet:    veg/3,
    starches:    starchy,
    fruit:       fruit,
    legumes:     protein*0.3,
    nutsseeds:   protein*0.2,
    eggs:        protein*0.1,
    meat:        protein*0.4,
    dairy:       dairy,
    herbs:       0,
    discretionary: 0,
  };
}
const FERTILITY_MULT={low:0.55,medium:0.75,high:0.95};

// Water-efficiency steer strength by context (0 = off). Scarcer water / an explicit water
// objective get a firmer tilt than metered "limited" supply. It scales the fresh gap-fill
// score and the starch land-efficiency key by ±W around neutral (thrifty crop +W, thirsty −W).
// A thirsty crop that UNIQUELY fills a seasonal gap still wins; between crops covering similar
// months, the water-thrifty one wins. Tune against the rendered plan.
const WATER_STEER_LIMITED   = 0.3;  // Balanced + metered scheme/bore water
const WATER_STEER_RAINFED   = 0.5;  // Balanced + rainfed (no external supply — scarcest)
const WATER_STEER_OBJECTIVE = 0.6;  // explicit "Minimise irrigation" objective
const STORABILITY_RANK={"Long Storage":5,"Medium Storage":4,"Year-round Proc.":3,"Short Storage":2,"Fresh Only":1};
// Food-group display tag classes, keyed by the crops.json food_group strings (13-group taxonomy).
const FG_TAG={"Dark Green Vegetables":"tag-darkgreen","Red/Orange Vegetables":"tag-redorange","Other Vegetables":"tag-veg","Tubers":"tag-starch","Fruit":"tag-fruit","Grain (Cereal) Foods":"tag-starch","Legumes":"tag-protein","Nuts & Seeds":"tag-protein","Nuts":"tag-protein","Seeds":"tag-protein","Eggs":"tag-protein","Meat":"tag-protein","Dairy":"tag-dairy","Herbs":"tag-herbs","Discretionary":"tag-disc"};
const FG_SHORT={"Dark Green Vegetables":"Greens","Red/Orange Vegetables":"Red/Org","Other Vegetables":"Veg","Tubers":"Tubers","Fruit":"Fruit","Grain (Cereal) Foods":"Grain","Legumes":"Legumes","Nuts & Seeds":"Nuts","Nuts":"Nuts","Seeds":"Seeds","Eggs":"Eggs","Meat":"Meat","Dairy":"Dairy","Herbs":"Herb","Discretionary":"Disc"};
// Floored groups iterated in greedy phase-1, as crops.json food_group strings (order = allocation priority).
const FG_GROUPS=["Dark Green Vegetables","Red/Orange Vegetables","Other Vegetables","Fruit","Tubers","Nuts","Seeds","Legumes","Eggs","Dairy","Meat"];
// food_group string → internal key (13-group). Keep in sync with fgToKey().
const FG_KEY={"Dark Green Vegetables":"darkgreen","Red/Orange Vegetables":"redorange","Other Vegetables":"othervet","Tubers":"starches","Fruit":"fruit","Grain (Cereal) Foods":"starches","Legumes":"legumes","Nuts & Seeds":"nutsseeds","Nuts":"nutsseeds","Seeds":"nutsseeds","Eggs":"eggs","Meat":"meat","Dairy":"dairy","Herbs":"herbs","Discretionary":"discretionary"};
// ── Umbrella food groups (ADG-5 allocation model) ────────────────────────────
// Phase 1 allocates against FIVE umbrella floors, not the 13 sub-groups, EXCEPT
// vegetables which keep their three sub-floors (user wants the veg sub-groups
// present in roughly equal thirds). Display, tags, NRV bars and the monthly grid
// stay keyed by the real sub-group (a chickpea still shows "Legumes") — only the
// allocation loop's targets/sufficiency are merged. members = the internal sub-keys
// summed for this umbrella's target & coverage. The three veg umbrellas each own a
// single sub-key, so they behave exactly as before (independent hard floors).
const UMBRELLA_GROUPS = [
  { id:"darkgreen", members:["darkgreen"],                       fresh:true  },
  { id:"redorange", members:["redorange"],                       fresh:true  },
  { id:"othervet",  members:["othervet"],                        fresh:true  },
  { id:"fruit",     members:["fruit"],                           fresh:true  },
  { id:"starches",  members:["starches"],                        fresh:false },
  { id:"protein",   members:["legumes","nutsseeds","eggs","meat"], fresh:false },
  { id:"dairy",     members:["dairy"],                           fresh:false },
];
// Internal sub-key → umbrella id (for crediting allocations & livestock to the
// umbrella whose target/coverage they advance).
const KEY_TO_UMBRELLA = (function(){
  const o = {};
  UMBRELLA_GROUPS.forEach(u => u.members.forEach(k => { o[k] = u.id; }));
  return o;
})();
const SOIL_PH={sand_low:5.5,sand_medium:6.0,sand_high:6.5,loam_low:5.8,loam_medium:6.5,loam_high:7.0,clay_low:6.0,clay_medium:6.8,clay_high:7.5};

// ── Preparation requirements lookup ──────────────────────────────────────────
const PREP_LOOKUP = {
  "Grain":       "Thresh/hull then mill or roll; ~4–8 hrs/100kg",
  "Starch":      "Process into starch (dry, grind); ~6–10 hrs/100kg",
  "Nut":         "Shell removal; ~2–4 hrs/10kg raw",
  "Pressed Oil": "Cold-press after harvest; ~3–5 hrs/100kg fruit",
  "Cassava":     "Peel & cook (toxic raw); 30–60 min/kg",
  "Olive (Table)":"Brine cure 3–8 weeks; active: ~2 hrs/10kg",
  "Olive (Oil)": "Press within 24h; ~3 hrs/100kg fruit",
  "Wattle Seed (Native)":"Roast, then grind; ~2–3 hrs/kg",
  "Lupin":       "Soak 12–24h, boil 1–2h to remove alkaloids",
  "Taro":        "Peel & cook (irritant raw); ~30 min/kg",
  "Arrowroot":   "Peel, grate, strain for starch; ~3 hrs/kg",
  "Bamboo":      "Boil 20–30 min to remove bitter compounds",
  "Chestnut":    "Score, roast or boil 30 min; shell",
  "White Oak":   "Leach tannins 1–3h; dry & mill to flour",
  "Burr Oak":    "Leach tannins 1–3h; dry & mill to flour",
  "Holm Oak":    "Minimal leaching; roast & mill to flour",
  "Sago":        "Wash pith, drain, dry; ~8 hrs/100kg starch",
  "Quandong (Native)":"Dry or stew; pip removal; ~30 min/kg",
  "Bunya Pine":  "Boil or roast 30–40 min; shell",
};
function getPrep(crop){
  if(PREP_LOOKUP[crop.name]) return PREP_LOOKUP[crop.name];
  const ep = crop.edible_part||"";
  if(ep==="Root"||ep==="Tuber"||ep==="Corm"||ep==="Rhizome") return "Wash & cook; ~15–30 min/kg";
  if(ep==="Leaf"||ep==="Shoot"||ep==="Floret"||ep==="Bud"||ep==="Stalk"||ep==="Calyx") return "Wash; fresh or cook";
  if(ep==="Fruit"||ep==="Berry"||ep==="Pod") return "Wash; ready fresh";
  if(ep==="Fruiting Body") return "Brush clean; fresh or dry";
  if(ep==="Bulb/Clove"||ep==="Bulb") return "Peel outer skin";
  if(ep==="Seed"||ep==="Pod/Seed") return "Dry & shell; cook legumes 1–2h";
  return "Wash; ready to use";
}
function getCropPlantType(crop){
  if(!crop.perennial){
    const s=getCropSeason(crop);
    if(s==="cool") return "Cool season annual";
    if(s==="warm") return "Warm season annual";
    return "Annual";
  }
  const h=crop.h_max||0;
  const ep=crop.edible_part||"";
  if(ep==="Fruiting Body") return "Cultivated fungus";
  if(h>=25) return "Canopy tree (≥25m)";
  if(h>=10) return "Sub-canopy tree (10–24m)";
  if(h>=4)  return "Small tree (4–9m)";
  if(h>=2)  return "Shrub (2–4m)";
  const n=crop.name.toLowerCase();
  if(n.includes("grape")||n.includes("kiwi")||n.includes("choko")||n.includes("passion")||
     n.includes("rambutan")||n.includes("vanilla")||n.includes("vine"))
    return "Climbing perennial";
  return "Perennial herb/groundcover";
}
function getSoilSuitability(crop,soil){
  if(soil==="wide") return "Ideal";  // variable soil: crop can be sited on its preferred texture
  if((crop.text_opt||[]).includes(soil)) return "Ideal";
  if((crop.text_tol||[]).includes(soil)||(crop.text_tol||[]).includes("wide")) return "Suitable";
  return "Unsuitable";
}
function getDroughtTolerance(crop){
  const r=crop.rain_min||0;
  if(r<=350) return "High (drought tolerant)";
  if(r<=700) return "Medium";
  if(r<=1200) return "Low (needs regular water)";
  return "Very low (water demanding)";
}
function getIrrigationNeeded(crop,rainfall){
  const rmin=crop.rain_min||0;
  if(rainfall>=rmin) return "Unlikely";
  return rainfall<rmin*0.7 ? "Essential" : "Likely";
}

