  breastfeeding:  {kcal:2500,protein:67,fat:83,fiber:30,ca:1000,fe:9, mg:330,k:3200,zn:12,vitA:1100,vitC:80,vitE:11,b1:1.4,b2:1.6,b3:17,b6:2.0,b12:2.8,folate:500},
