const NUTRIENT_LABELS = {
  kcal:"Energy",protein:"Protein",fat:"Fat",carbs:"Carbs",fiber:"Fibre",
  ca:"Calcium",fe:"Iron",mg:"Magnesium",p:"Phosphorus",k:"Potassium",
  zn:"Zinc",cu:"Copper",mn:"Manganese",se:"Selenium",
  vitA:"Vit A",vitC:"Vit C",vitE:"Vit E",
  b1:"Vit B1",b2:"Vit B2",b3:"Vit B3 (Niacin)",b6:"Vit B6",b12:"Vit B12",folate:"Folate"
};
const NUTRIENT_UNITS = {
  kcal:"kcal",protein:"g",fat:"g",carbs:"g",fiber:"g",
  ca:"mg",fe:"mg",mg:"mg",p:"mg",k:"mg",
  zn:"mg",cu:"mg",mn:"mg",se:"µg",
  vitA:"µg",vitC:"mg",vitE:"mg",
  b1:"mg",b2:"mg",b3:"mg",b6:"mg",b12:"µg",folate:"µg"
};

// Sum household NRVs across all members
function householdNRV(household){
  const totals = {};
  household.forEach(m => {
    const nrv = NRV[m.type] || NRV.man_19_50;
    Object.entries(nrv).forEach(([k,v]) => totals[k] = (totals[k]||0) + v);
  });
  return totals;
}

// Calculate annual nutritional yield from the plan
function nutritionalYield(plan, fertility, confidence){
  const totals = {};
  plan.selected.forEach(({crop, allocHa}) => {
    if(!crop.nut) return;
    const adjYield = subsistYield(crop, fertility, confidence); // t/ha
    const annualKg = allocHa * adjYield * 1000; // kg/yr
    // Nutrition values are per 100g, so multiply by (kg * 10)
    Object.entries(crop.nut).forEach(([nutrient, valuePer100g]) => {
      const annualAmount = annualKg * 10 * valuePer100g;
      totals[nutrient] = (totals[nutrient]||0) + annualAmount;
    });
  });
  // ── Add livestock nutrient contributions ─────────────────────────────────
  // Use plan.lsSelected (algorithm + adjust overrides) not state.livestock directly
  const lsEntries = plan.lsSelected || [];
  lsEntries.forEach(({ls, count}) => {
    lsNutContributions(ls).forEach(c => {
      const annualG = count * c.qty_per_animal_yr;
      Object.entries(c.nut).forEach(([nutrient, per100g]) => {
        totals[nutrient] = (totals[nutrient]||0) + annualG * per100g / 100;
      });
    });
  });
  return totals;
}


// ── Nutrient-dense crop suggestions to fill plan gaps ─────────────────────
function suggestNutrientSupplements(plan, st){
  const yieldNut = nutritionalYield(plan, st.fertility, st.confidence);
  const dailyNRV = householdNRV(st.household);
  const annualNRV = {};
  Object.entries(dailyNRV).forEach(([k,v]) => annualNRV[k] = v * 365);

  // Identify gaps (below 100% of NRV). Skip B12 — not achievable from plants.
  const SKIP_NUTRIENTS = new Set(["b12"]);
  const gaps = [];
  Object.entries(annualNRV).forEach(([k, need]) => {
    if(SKIP_NUTRIENTS.has(k)) return;
    const produced = yieldNut[k] || 0;
    if(need > 0 && produced < need){
      gaps.push({nutrient:k, need, produced, gap: need - produced, pct: produced/need});
    }
  });
  gaps.sort((a,b) => a.pct - b.pct);

  if(!gaps.length) return {suggestions:[], reason:"no_gaps", gapCount:0, gapNames:[], annualLeft:0, perennialLeft:0};

  const coolLeft = Math.max(0, st.annualHa - (plan.usedCoolHa||0));
  const warmLeft = Math.max(0, st.annualHa - (plan.usedWarmHa||0));
  const annualLeft = Math.max(coolLeft, warmLeft);
  const perennialLeft = Math.max(0, st.perennialHa - plan.usedPerennialHa);
  const labourLeft = Math.max(0, st.hoursPerWeek * 52 * 1.15 - plan.usedLabour);
  const gapNames = gaps.slice(0,4).map(g => NUTRIENT_LABELS[g.nutrient]);

  if(annualLeft < 0.005 && perennialLeft < 0.005){
    return {suggestions:[], reason:"no_space", gapCount:gaps.length, gapNames, annualLeft, perennialLeft};
  }

  // Pool of candidate crops: suitable, has nutrition data, not in plan, not herbs
  const inPlan = new Set(plan.selected.map(s => s.crop.name));
  const pool = CROP_DATA.filter(c => {
    if(!c.nut) return false;
    if(inPlan.has(c.name)) return false;
    if(HERB_EXCLUSIONS.has(c.name)) return false;
    if(!isSuitable(c)) return false;
    if(cropPriorityTier(c) === 0) return false;
    return subsistYield(c, st.fertility, st.confidence) > 0;
  });

  const suggestions = [];
  let usedAnnualLocal = 0, usedPerennialLocal = 0, usedLabourLocal = 0;
  const handled = new Set();

  // For each gap (worst first), find the best crop to address it.
  // Iterate scored candidates until one fits the available space + labour;
  // if the densest crop is annual but only perennial space is free, this
  // lets us still pick a slightly-less-dense perennial alternative.
  for(const g of gaps){
    if(suggestions.length >= 5) break;
    if(handled.has(g.nutrient)) continue;

    const scored = pool
      .filter(c => !suggestions.some(s => s.crop.name === c.name))
      .map(c => {
        const adjY = subsistYield(c, st.fertility, st.confidence);
        const per100g = c.nut[g.nutrient] || 0;
        const nutPerHa = adjY * 10000 * per100g;
        return {crop:c, adjY, nutPerHa, per100g};
      })
      .filter(x => x.nutPerHa > 0)
      .sort((a,b) => b.nutPerHa - a.nutPerHa);

    if(!scored.length){
      handled.add(g.nutrient);
      continue;
    }

    let placed = false;
    for(const cand of scored){
      const isAnnual = !cand.crop.perennial;
      const availForCrop = isAnnual
        ? (annualLeft - usedAnnualLocal)
        : (perennialLeft - usedPerennialLocal);
      if(availForCrop < 0.005) continue;

      // Suggested area: enough to fill 60% of gap, capped at 40% of remaining space
      let suggestedHa = (g.gap * 0.6) / cand.nutPerHa;
      suggestedHa = Math.min(suggestedHa, availForCrop * 0.4);
      if(suggestedHa < 0.002) continue;

      const lph = cropLabour(cand.crop, st.labourSystem === "mech");
      const labour = lph * suggestedHa;
      if(usedLabourLocal + labour > labourLeft) continue;

      // What does this allocation deliver across all open gaps?
      // Show each contribution as a fraction of the household's annual NRV
      // (total need), which is easier to interpret than fraction-of-gap.
      // E.g. "20% of Iron" means "supplies one-fifth of daily iron need."
      const reasons = [];
      gaps.forEach(otherG => {
        const per100g = cand.crop.nut[otherG.nutrient];
        if(!per100g) return;
        const delivered = suggestedHa * cand.adjY * 10000 * per100g;
        const pctOfNeed = Math.round(Math.min(999, delivered / otherG.need * 100));
        if(pctOfNeed >= 5){
          reasons.push(`${pctOfNeed}% of ${NUTRIENT_LABELS[otherG.nutrient]}`);
          handled.add(otherG.nutrient);
        }
      });

      suggestions.push({crop: cand.crop, suggestedHa, labour, reasons: reasons.slice(0, 4), adjYield: cand.adjY});
      if(isAnnual) usedAnnualLocal += suggestedHa;
      else usedPerennialLocal += suggestedHa;
      usedLabourLocal += labour;
      placed = true;
      break;
    }

    if(!placed) handled.add(g.nutrient);
  }

  return {suggestions, reason:"have_suggestions", gapCount:gaps.length, gapNames, annualLeft, perennialLeft};
}

function addSupplementsToPlan(cropNames){
  if(!Array.isArray(cropNames)) return;
  ensureCheckedCrops();
  cropNames.forEach(n => state.checkedCrops.add(n));
  state.plan = null;
  renderApp();
}

// ── Crop priority tier — Ideal / Suitable / Unsuitable ─────────────────────
// Tier 2 (Ideal):      passes the hard gate AND optimal soil AND optimal temperature
// Tier 1 (Suitable):   passes the hard gate (climate zone, tolerated soil, rainfall,
//                      frost survival, absolute tmin–tmax growing range)
// Tier 0 (Unsuitable): fails the hard gate (isSuitable)
// Rainfall lives entirely in the hard gate (isSuitable) — softened when irrigation is on.
// "wide" soil counts as optimal (crop can be sited on its preferred texture patch).
function soilIsOptimal(crop){
  const userTex = state.soilTexture;
  if(userTex === "wide") return true;                       // variable soil -> preferred patch
  const opt = crop.text_opt || [];
  return opt.includes(userTex) || opt.includes("wide");
}
function tempIsOptimal(crop){
  const tmaxA = state.climateTmax, tminA = state.climateTmin;
  if(!tmaxA || !tminA) return true;                          // no location temps -> don't block ideal
  const lo = crop.temp_opt_min, hi = crop.temp_opt_max;
  if(lo == null || hi == null) return false;                 // no optimal band -> can't be temp-ideal
  const meanT = tmaxA.map((tx,i) => (tx + tminA[i]) / 2);
  if(crop.perennial){
    const pk = Math.max(...meanT);                           // warmest-month mean
    return pk >= lo && pk <= hi;
  } else {                                                   // annual: a frost-safe month in the band
    const extA = state.climateTminext;
    for(let i=0;i<12;i++){
      const frostOk = (crop.ktmp == null) || (!extA) || (extA[i] >= crop.ktmp);
      if(frostOk && meanT[i] >= lo && meanT[i] <= hi) return true;
    }
    return false;
  }
}
function cropPriorityTier(crop){
  if(!isSuitable(crop)) return 0;
  return (soilIsOptimal(crop) && tempIsOptimal(crop)) ? 2 : 1;
}


// Map food_group string to achieved key
function fgToKey(fg){
  if(!fg) return null;
  const f = fg.toLowerCase();
  // Specific veg sub-groups MUST be checked before the generic "vegetable" → othervet.
  if(f.includes('dark green')) return 'darkgreen';
  if(f.includes('red/orange') || f.includes('red-orange') || f.includes('red orange')) return 'redorange';
  if(f.includes('tuber')) return 'starches';
  // Grain before nuts/seeds (no overlap, but explicit) and before generic veg.
  if(f.includes('grain') || f.includes('cereal')) return 'starches';
  if(f.includes('legume')) return 'legumes';
  if(f.includes('nut') || f.includes('seed')) return 'nutsseeds';
  if(f.includes('egg')) return 'eggs';
  if(f.includes('meat')) return 'meat';
  if(f.includes('dairy')) return 'dairy';
  if(f.includes('herb')) return 'herbs';
  if(f.includes('discretionary')) return 'discretionary';
  if(f.includes('fruit')) return 'fruit';
  // Generic vegetable falls through to "other vegetables".
  if(f.includes('vegetable')) return 'othervet';
  return null;
}


// ── Livestock helpers ─────────────────────────────────────────────────────
// Serves per day from one output of one animal species
// Classify an annual crop as "cool" (May–Oct harvest), "warm" (Nov–Apr), or "dual"
function getCropSeason(crop){
  if(crop.perennial) return null;
  // WARM = Jan–Apr (true summer harvest); COOL = May–Dec.
  // Cool-season Perth crops (wheat, potato, brassicas) peak Oct–Dec, so those
  // months sit in COOL. Harvest-only scoring (P=2, S=1); ties default to cool.
  const COOL = new Set(["may","jun","jul","aug","sep","oct","nov","dec"]);
  const WARM = new Set(["jan","feb","mar","apr"]);
  let cs = 0, ws = 0;
  Object.entries(crop.months||{}).forEach(([m,v]) => {
    const w = v==="P" ? 2 : v==="S" ? 1 : 0;
    if(COOL.has(m)) cs += w;
    if(WARM.has(m)) ws += w;
  });
  return ws > cs ? "warm" : "cool"; // default to cool if equal or no data
}

// Serves per day for the MAIN food-group contribution of one livestock species × count.
// Flat crops.json shape: qty_per_animal_yr already in grams (or mL). serve_g converts to serves.
// Byproducts (tallow/lard, food_group:null) contribute fat to NRV only — never serves.
function lsServesPerDay(ls, count){
  if(!count || count <= 0) return 0;
  if(!ls || !ls.qty_per_animal_yr || !ls.food_group) return 0;
  const totalGPerYr = count * ls.qty_per_animal_yr;   // already g or mL
  return (totalGPerYr / (ls.serve_g || 100)) / 365;
}

// Every nutrient-bearing contribution (main food group + byproducts) for NRV accumulation.
// Each entry: { nut, qty_per_animal_yr } — annual grams per animal.
function lsNutContributions(ls){
  const out = [];
  if(ls.nut && ls.qty_per_animal_yr) out.push({ nut: ls.nut, qty_per_animal_yr: ls.qty_per_animal_yr });
  (ls.byproducts||[]).forEach(bp => {
    if(bp.nut && bp.qty_per_animal_yr) out.push({ nut: bp.nut, qty_per_animal_yr: bp.qty_per_animal_yr });
  });
  return out;
}

// Total livestock food-group serves/day, keyed by the 13-group taxonomy.
function calcLivestockAchieved(lsArr){
  const result = zeroFG();
  const entries = lsArr || LIVESTOCK_DATA.filter(ls => (state.livestock||{})[ls.name] > 0).map(ls => ({ls, count:(state.livestock||{})[ls.name]}));
  entries.forEach(({ls, count}) => {
    const spd = lsServesPerDay(ls, count);
    const key = fgToKey(ls.food_group);
    if(key && result[key] !== undefined) result[key] += spd;
  });
  return result;
}

// Total pasture/water space used by current livestock (in ha)
function calcLivestockSpaceHa(){
  const lv = state.livestock || {};
  let total = 0;
  LIVESTOCK_DATA.forEach(ls => {
    const count = lv[ls.name] || 0;
    if(!count) return;
    total += ls.space_m2_per_animal * count;
  });
  return total / 10000;
}

// Adjust livestock count; step by ls.step (min 0)
function adjustLivestock(name, delta){
  if(!state.livestock) state.livestock = {};
  const ls = LIVESTOCK_DATA.find(l => l.name === name);
  if(!ls) return;
  const cur = state.livestock[name] || 0;
  const next = Math.max(0, cur + delta * ls.step);
  state.livestock[name] = next;
  state.plan = null;
  renderApp();
}

function editLivestockCount(name, rawVal){
  if(!state.livestock) state.livestock = {};
  const n = Math.max(0, parseInt(rawVal) || 0);
  state.livestock[name] = n;
  state.plan = null;
  renderApp();
}

function removeLivestockFromPlan(name){
  if(!state.livestock) state.livestock = {};
  state.livestock[name] = 0;
  state.plan = null;
  renderApp();
}

function toggleLivestock(name, checked){
  if(!state.checkedLivestock) state.checkedLivestock = new Set();
  if(checked) state.checkedLivestock.add(name);
  else state.checkedLivestock.delete(name);
  state.plan = null;
  renderApp();
}

// Human-readable output summary for one livestock entry
function lsOutputSummary(ls, count){
  if(!count) return "—";
  const spd = lsServesPerDay(ls, count);
  const label = spd >= 1 ? spd.toFixed(1) : spd.toFixed(2);
  return `${label} srv/day ${ls.edible_part || ls.name}`;
}

// CSS tag class for a livestock food group (display only). Byproducts (food_group:null) → oils tag.
function lsGroupTagClass(fg, style){
  // style: "tag" (plan summary) | "ls" (plan list) | "sel" (selection panel)
  if(fg === "Dairy")          return style === "ls" ? "dairy-tag" : "tag-dairy";
  if(fg === "Discretionary")  return style === "ls" ? "disc-tag" : "";
  if(!fg)                     return style === "ls" ? "oils-tag" : "tag-oils"; // byproduct fat
  return style === "ls" ? "" : "tag-protein";
}
// List of {label, food_group, qty_per_animal_yr, unit, serve_g, nut} contributions for display.
function lsDisplayOutputs(ls){
  const list = [{ label: ls.edible_part || ls.name, food_group: ls.food_group,
                  qty_per_animal_yr: ls.qty_per_animal_yr, unit: ls.unit, serve_g: ls.serve_g, nut: ls.nut }];
  (ls.byproducts||[]).forEach(bp => list.push({ label: bp.edible_part, food_group: bp.food_group,
                  qty_per_animal_yr: bp.qty_per_animal_yr, unit: bp.unit, serve_g: bp.serve_g, nut: bp.nut }));
  return list;
}


// Returns effective annual/perennial ha budgets, respecting landFixed setting.
// When fluid (landFixed===false), both pools share the combined total.
function effectiveLandBudgets(s){
  if(s.landFixed === false){
    const total = (s.annualHa||0) + (s.perennialHa||0);
    return {annualHa: total, perennialHa: total};
  }
  return {annualHa: s.annualHa||0, perennialHa: s.perennialHa||0};
}

function generatePlan(s){
  const annualBudget = s.hoursPerWeek * 52;
  const labourCap = annualBudget * 1.15;
  const isMech = s.labourSystem === "mech";
  const targets = calcTotals(s.household);
  const maxYield = s.objectives?.maximiseYield === "on";

  // Build candidate pool with tier + objective score
  const candidates = CROP_DATA
    .filter(c => isSuitable(c) && s.checkedCrops && s.checkedCrops.has(c.name) && !HERB_EXCLUSIONS.has(c.name))
    .map(c => ({
      crop: c,
      tier: cropPriorityTier(c),
      score: cropScore(c, s.fertility, s.confidence, s.climateZone, s.objectives),
      adjYield: subsistYield(c, s.fertility, s.confidence),
    }))
    .filter(x => x.tier > 0)
    .sort((a, b) => b.tier - a.tier || b.score - a.score);

  const eb = effectiveLandBudgets(s);
  let usedCoolHa=0, usedWarmHa=0, usedPerennialHa=0, usedLabour=0, usedSurfaceWaterHa=0;
  // Option B: with the irrigation dam on, the dam is sized AFTER allocation to fit the
  // aquatic crops the planner picks on merit, so surface area is not a binding budget here.
  const swBudget = s.irrigationDam ? 1e7 : (s.surfaceWaterHa || 0);
  // Per-layer tracking — perennial layers stack on the same plot
  let usedCanopyHa = 0, usedTreesHa = 0, usedPerennialPlantsHa = 0;
  const usedAnnualHa = () => usedCoolHa + usedWarmHa; // total across both seasons
  const perennialFootprint = () => Math.max(usedCanopyHa, usedTreesHa, usedPerennialPlantsHa);
  const achieved=zeroFG();
  const monthCoverage={}; MONTHS.forEach(m => monthCoverage[m]=zeroFG());
  const selected=[];
  const lsSelected = [];
  let usedPastureHa = 0;

  // Build livestock candidates from checkedLivestock
  const checkedLs = s.checkedLivestock || new Set();
  const lsCandidates = [];
  LIVESTOCK_DATA.forEach(ls => {
    if(!checkedLs.has(ls.name)) return;
    const key = fgToKey(ls.food_group);
    if(!key) return;
    const servesPerStep = lsServesPerDay(ls, ls.step);
    const labourPerStep = (ls.labour_hrs_per_animal || 0) * ls.step;
    const spaceHaPerStep = ls.space_m2_per_animal * ls.step / 10000;
    lsCandidates.push({ls, key, servesPerStep, labourPerStep, spaceHaPerStep,
      usedCount: 0,
      score: labourPerStep > 0 ? (servesPerStep * 365) / labourPerStep : servesPerStep * 999
    });
  });

  // Honeybees: always add if checked (discretionary, negligible space)
  if(checkedLs.has("Honeybee Colony")){
    const bee = LIVESTOCK_DATA.find(l => l.name === "Honeybee Colony");
    if(bee){ usedLabour += (bee.labour_hrs_per_animal||0) * bee.step;
      usedPastureHa += bee.space_m2_per_animal * bee.step / 10000;
      lsSelected.push({ls: bee, count: bee.step}); }
  }

  function addLivestockAllocation(lsCand, count){
    if(count <= 0) return;
    lsCand.usedCount += count;
    usedLabour += (lsCand.ls.labour_hrs_per_animal||0) * count;
    if(isAquaticLivestock(lsCand.ls)){
      usedSurfaceWaterHa += lsCand.ls.space_m2_per_animal * count / 10000;
    } else {
      usedPastureHa += lsCand.ls.space_m2_per_animal * count / 10000;
    }
    const spd = lsServesPerDay(lsCand.ls, count);
    const k2 = fgToKey(lsCand.ls.food_group);
    if(k2 && achieved[k2] !== undefined){
      achieved[k2] += spd;
      MONTHS.forEach(m => { if(monthCoverage[m][k2] !== undefined) monthCoverage[m][k2] += spd; });
    }
    const ex = lsSelected.find(e => e.ls.name === lsCand.ls.name);
    if(ex) ex.count += count; else lsSelected.push({ls: lsCand.ls, count});
  }

  function cropEfficiency(crop){
    const adjY = subsistYield(crop, s.fertility, s.confidence);
    const srvPerHa = adjY * 1e6 / (crop.serve_g || 75);
    const lph = cropLabour(crop, isMech);
    return lph > 0 ? srvPerHa / lph : srvPerHa * 99;
  }

  function addAllocation(crop, allocHa, key, pool){
    const lph = cropLabour(crop, isMech);
    const actualLabour = lph * allocHa;
    const adjY = subsistYield(crop, s.fertility, s.confidence);
    const annualKg = allocHa * adjY * 1000;
    const totalServesYr = annualKg * 1000 / (crop.serve_g || 75);
    // Every crop feeds the household only during the months it can actually supply:
    // its harvest window plus its real cool-store bridge (cropSupplyMonths). Annual
    // sufficiency credit is the in-season daily rate weighted by the fraction of the
    // year it supplies — so a 3-month fresh crop counts ~3/12, while a long-storing
    // staple (cool_store ≥ ~1yr) covers all 12 months and earns full credit. This drives
    // other crops to be recruited for the uncovered months → seasonal diversity.
    const sup = cropSupplyMonths(crop);
    const supplyMonths = sup.coveredCount > 0 ? sup.coveredCount : 12;
    const inSeasonRate = totalServesYr / (supplyMonths * 30);   // serves/day while supplying
    const actualServes = inSeasonRate * (supplyMonths / 12);    // year-round average contribution
    achieved[key] += actualServes;
    MONTHS.forEach((m, i) => {
      const w = sup.months[i];
      if(w > 0) monthCoverage[m][key] += inSeasonRate * w;
    });
    usedLabour += actualLabour;
    // Land-pool tracking — caller passes pool ("surface" = water-grown allocation)
    if(pool === "surface"){
      usedSurfaceWaterHa += allocHa;
    } else if(crop.perennial){
      usedPerennialHa += allocHa;
      const layer = cropLayer(crop);
      if(layer === "canopy") usedCanopyHa += allocHa;
      else if(layer === "trees") usedTreesHa += allocHa;
      else usedPerennialPlantsHa += allocHa;
    } else {
      const season = getCropSeason(crop);
      if(season === "warm") usedWarmHa += allocHa;
      else usedCoolHa += allocHa; // cool (default)
    }
    // Byproduct: also credit secondary organ serves to their food group
    if(crop.byproducts && crop.byproducts.length){
      crop.byproducts.forEach(bp => {
        const bpYieldTha = adjY * (bp.yield_fraction || 0);
        const bpServesYr = allocHa * bpYieldTha * 1e6 / (bp.serve_g || crop.serve_g || 75);
        const bpKey = fgToKey(bp.food_group);
        if(bpKey && achieved[bpKey] !== undefined){
          achieved[bpKey] += bpServesYr / 365;
          // Also spread into monthly coverage
          const bpMonths = bp.months || crop.months;
          let bpW = 0;
          MONTHS.forEach(m => { if(bpMonths[m]==='P') bpW+=1; else if(bpMonths[m]==='S') bpW+=0.5; });
          if(bpW > 0){
            const bpBase = bpServesYr / bpW / 30;
            MONTHS.forEach(m => {
              const v = bpMonths[m];
              const w = v==='P'?1:v==='S'?0.5:0;
              if(w > 0 && monthCoverage[m][bpKey] !== undefined) monthCoverage[m][bpKey] += bpBase * w;
            });
          }
        }
      });
    }
    const existing = selected.find(e => e.crop.name === crop.name);
    if(existing){
      existing.allocHa += allocHa;
      existing.serves += actualServes;
      existing.labour += actualLabour;
    } else {
      selected.push({crop, allocHa, serves: actualServes, labour: actualLabour, tier: cropPriorityTier(crop)});
    }
  }

  // Pick the space pool a crop draws from, given the LAND space available to it.
  // pure aquatic -> surface water; "both" -> land if any, else spill to surface;
  // land-only -> land. Returns {available, pool} (pool: "land" | "surface").
  function cropPoolAvail(crop, landAvail){
    const hab = cropHabitat(crop);
    if(hab === "land") return {available: landAvail, pool: "land"};
    const swAvail = swBudget - usedSurfaceWaterHa;
    if(hab === "aquatic") return {available: swAvail, pool: "surface"};
    // "both": default to land, spill into surface water only when land is full
    return landAvail > 0.0005 ? {available: landAvail, pool: "land"}
                              : {available: swAvail, pool: "surface"};
  }

  // ── PHASE 1: fill each food group to 100% sufficiency ────────────────────
  // Determine planning mode (single-select objective)
  const objMode = Object.keys(s.objectives||{}).find(k => s.objectives[k] === "on") || "balanced";

  // Pre-compute mode-specific score for every candidate
  // This is the PRIMARY sort key within a tier (replaces/extends cropScore)
  candidates.forEach(cand => {
    const adjY = cand.adjYield; // already computed
    const sg = cand.crop.serve_g || 75;
    if(objMode === "minimiseLabour"){
      const lh = cand.crop.labour_hand || 1;
      cand.modeScore = adjY * 1e6 / sg / lh;        // serves per labour-hr
    } else if(objMode === "minimiseSpace"){
      cand.modeScore = adjY * 1e6 / sg / 10000;     // serves per m2
    } else if(objMode === "minimiseWater"){
      const irr = cropAnnualIrrigationPerHa(cand.crop);
      cand.modeScore = (adjY * 1e6 / sg) / Math.max(irr, 1000);  // serves per irrigation litre (floor → rain-fed favoured)
    } else if(objMode === "maximiseYield"){
      cand.modeScore = adjY;                          // raw yield t/ha
    } else {
      cand.modeScore = cand.score;                    // balanced: cropScore 0-300
    }
  });

  // ── Water-efficiency steer ───────────────────────────────────────────────
  // Active in Balanced (strength by water scarcity) and in the explicit Minimise-irrigation
  // objective (which also sets modeScore = serves/litre for the protein/other groups, while
  // the tilt below covers fresh & starch). waterEff: 1 = thriftiest, 0 = thirstiest.
  let waterSteerW = 0;
  if(objMode === "minimiseWater")             waterSteerW = WATER_STEER_OBJECTIVE;
  else if(objMode === "balanced"){
    if(s.waterSource === "rainfed")           waterSteerW = WATER_STEER_RAINFED;
    else if(s.waterSource === "limited")      waterSteerW = WATER_STEER_LIMITED;
  }
  const waterSteerOn = waterSteerW > 0;
  if(waterSteerOn){
    let lo = Infinity, hi = -Infinity;
    candidates.forEach(c => {
      const wi = cropWaterIntensity(c.crop);
      c.wIntensity = (wi != null && wi > 0) ? wi : null;
      if(c.wIntensity != null){ const L = Math.log(c.wIntensity); if(L < lo) lo = L; if(L > hi) hi = L; }
    });
    const span = (hi > lo) ? (hi - lo) : 1;
    candidates.forEach(c => {
      // log-scaled so the heavy tail (thirsty grains/perennials) doesn't compress the rest;
      // unknown or zero-irrigation (rain-fed) → thriftiest.
      c.waterEff = (c.wIntensity == null) ? 1
        : 1 - Math.min(1, Math.max(0, (Math.log(c.wIntensity) - lo) / span));
    });
  }

  // ── Iterate the FIVE umbrella groups (veg split into its 3 sub-floors). ──
  // Each umbrella has a summed target across its member sub-keys; sufficiency and
  // monthly coverage are evaluated on the umbrella TOTAL, so any mix of members can
  // satisfy it (e.g. protein filled by whatever scores best — no per-sub-group floor).
  // Crops/livestock still credit their own real sub-key in achieved[]/monthCoverage[],
  // keeping the 13-group display intact.
  UMBRELLA_GROUPS.forEach(umb => {
    const members = umb.members;
    const key = umb.id;                       // umbrella id (also a display key for single-member umbrellas)
    // Summed target across the umbrella's member sub-keys.
    const targetServes = members.reduce((s, k) => s + (targets[k] || 0), 0);
    if(targetServes <= 0) return;
    // Umbrella-total achieved serves / monthly coverage (sum over member sub-keys).
    const umbServes   = () => members.reduce((s, k) => s + (achieved[k] || 0), 0);
    const umbMonthCov = (m) => members.reduce((s, k) => s + (monthCoverage[m][k] || 0), 0);
    const isFresh = umb.fresh;
    // Starches & fresh groups get month-by-month gap scoring so the allocator chains the
    // most land-efficient crop available each month (tubers dominate their windows; grain
    // fills residual gaps; fresh groups chain for seasonal variety).
    const gapScored = isFresh || key === 'starches';
    // Crop candidates whose sub-key belongs to THIS umbrella (protein = legumes∪nuts∪eggs∪meat).
    const memberSet = new Set(members);
    const fgCandidates = candidates.filter(x => memberSet.has(FG_KEY[effectiveFoodGroup(x.crop)]));
    // Livestock competing within this umbrella (e.g. dairy animals, meat/egg birds).
    const lsFgCands = lsCandidates.filter(lc => memberSet.has(lc.key));
    // No livestock per-species cap — a single species may meet the full umbrella target.
    const lsCapFrac = 1.0;
    const usedNames = new Set(selected.filter(s => memberSet.has(FG_KEY[effectiveFoodGroup(s.crop)])).map(s => s.crop.name));
    const lsBlocked = new Set();  // livestock species excluded mid-umbrella (e.g. red meat at ADG ceiling)

    // Iterate; stop when target met AND (for fresh/gap-scored) worst month is covered.
    let iter = 0;
    while(iter++ < 40){
      const achievedNow = umbServes();
      const sufficient = achievedNow >= targetServes - 0.1;
      const overPlanted = achievedNow >= targetServes * 1.3;  // hard cap at 130% annual
      let worstMonthCov = 1.0, peakMonthCov = 0;
      if(gapScored){
        MONTHS.forEach(m => {
          const cov = umbMonthCov(m) / targetServes;
          if(cov < worstMonthCov) worstMonthCov = cov;
          if(cov > peakMonthCov) peakMonthCov = cov;
        });
      }
      const seasonallyEven = !gapScored || worstMonthCov >= 0.5;
      const gluttingHard = gapScored && peakMonthCov > 2.0;  // peak > 200% = stop
      if(sufficient && (seasonallyEven || objMode === "minimiseSpace")) break;
      // Annual overplant cap: only stop early if there's no meaningful seasonal gap left.
      // A glutted summer shouldn't block recruiting winter crops for an empty month — so
      // while worstMonthCov is low, keep going even past the annual 130% mark.
      const hasMonthGap = gapScored && worstMonthCov < 0.5;
      if((overPlanted || gluttingHard) && !hasMonthGap) break;  // hard caps

      // ── Best crop candidate ────────────────────────────────────────────────
      // 3-key comparator: tier (hard gate) → primary key → secondary key
      // Primary/secondary keys depend on planning mode:
      //   balanced:       gap-fill → cropScore
      //   minimiseLabour: modeScore (serves/labour-hr) → gap-fill
      //   minimiseSpace:  modeScore (serves/m2)        → gap-fill
      //   maximiseYield:  modeScore (yield t/ha)       → gap-fill
      let best = null;
      let bestTier = -1, bestPrimary = -Infinity, bestSecondary = -Infinity, bestGapMode = false;

      for(const cand of fgCandidates){
        if(usedNames.has(cand.crop.name)) continue;
        // Water-efficiency tilt (Balanced + limited water): >1 for thrifty, <1 for thirsty.
        const wf = waterSteerOn ? (1 + waterSteerW * (2 * (cand.waterEff ?? 0.5) - 1)) : 1;
        let gapFillScore = 0, glutPenalty = 0;
        if(gapScored){
          // Use the crop's full supply window (harvest months + cool-store bridge), so a
          // crop that stores into an empty month is credited for filling it. Empty months
          // (coverage well below target) are weighted heavily so a crop that uniquely
          // covers a gap wins even if its other months overlap a glut. Coverage is the
          // UMBRELLA total (sum over member sub-keys), so e.g. a legume and a nut both
          // count toward the protein umbrella's monthly fill.
          const supC = cropSupplyMonths(cand.crop);
          const dcurve = diminishingCfg(key).curve;
          MONTHS.forEach((m, mi) => {
            const w = supC.months[mi];
            if(w <= 0.001) return;
            const cov = umbMonthCov(m) / targetServes;
            if(cov < 1.0){
              // Diminishing marginal value: worth of supplying this month = remaining^curve.
              // Steeper curve → near-full months give almost no credit, so a crop only scores
              // for genuinely thin months. Variety wins because a NEW crop covering an emptier
              // slice out-scores piling onto an already-stocked month of an existing crop.
              const remaining = 1.0 - cov;
              gapFillScore += Math.pow(remaining, dcurve) * w;
            } else {
              glutPenalty += (cov - 1.0) * w * 0.5;  // softer glut penalty
            }
          });
          // Only skip a candidate when sufficient AND it adds essentially no gap coverage.
          if(sufficient && gapFillScore <= 0.05) continue;
        }
        const netGap = gapFillScore * wf - glutPenalty;

        // Assign primary and secondary keys by mode
        // For fresh crops: gap-fill is always primary (seasonal variety preserved)
        let primary, secondary;
        if(key === 'starches'){
          // Land efficiency drives starch selection: the most serves-per-m² crop wins each
          // pick. The loop continues while months remain uncovered (gapScored), so after the
          // best tuber fills its window, the next-most-efficient crop fills the gap months —
          // grain only wins residual months no efficient tuber covers. Gap-fill is the
          // tiebreaker so among similar-efficiency crops the one covering empty months wins.
          primary   = (cand.adjYield * 1e6 / (cand.crop.serve_g || 75) / 10000) * wf;  // serves per m² (water-tilted)
          secondary = netGap;
        } else if(key === 'protein'){
          // Protein umbrella: best-fit by efficiency (the chosen mode's modeScore), with
          // gap-fill spread as the tiebreaker so the diminishing-sizing + nudge can recruit a
          // mix (legume + nut + egg/meat) rather than dumping the whole target on one source.
          primary   = cand.modeScore;
          secondary = netGap;
        } else if(isFresh || objMode === "balanced"){
          primary   = netGap;
          secondary = cand.modeScore;
        } else {
          primary   = cand.modeScore;
          secondary = netGap;
        }

        // Tier is normally a hard gate (prefer staple/reliable crops first). But for a
        // gap-scored group with a real seasonal gap, a crop that fills an empty month should
        // win even if it's a lower tier — otherwise high-tier crops glut one season and
        // the gap never gets filled. So when filling a gap, tier becomes a tiebreaker.
        const gapMode = gapScored && worstMonthCov < 0.5 && gapFillScore > 0.05;
        const effTier = gapMode ? 0 : cand.tier;
        const cmpBestTier = gapMode ? (bestGapMode ? 0 : -1) : bestTier;

        const tierWins  = effTier > cmpBestTier;
        const tierTies  = effTier === cmpBestTier;
        const primWins  = tierTies && primary > bestPrimary + 1e-6;
        const primTies  = tierTies && Math.abs(primary - bestPrimary) <= 1e-6;
        const secWins   = primTies && secondary > bestSecondary + 1e-6;

        if(tierWins || primWins || secWins){
          best = cand;
          bestTier = cand.tier; bestPrimary = primary; bestSecondary = secondary;
          bestGapMode = gapMode;
        }
      }

      // ── Best livestock candidate (protein/dairy groups) ────────────────────
      let bestLs = null, bestLsEff = -Infinity;
      if(!isFresh){
        const labL = labourCap - usedLabour;
        const pasL = (s.landFixed === false)
          ? (s.annualHa||0) + (s.perennialHa||0) + (s.pastureHa||0) - perennialFootprint() - Math.max(usedCoolHa, usedWarmHa) - usedPastureHa
          : (s.pastureHa||0) - usedPastureHa;
        const swL  = swBudget - usedSurfaceWaterHa;
        for(const lc of lsFgCands){
          if(lsBlocked.has(lc.ls.name)) continue;
          if(lc.labourPerStep > labL + 0.1) continue;
          const poolLeft = isAquaticLivestock(lc.ls) ? swL : pasL;
          if(lc.spaceHaPerStep > poolLeft + 0.0001) continue;
          if(lsServesPerDay(lc.ls, lc.usedCount) >= targetServes * lsCapFrac) continue;
          // ADG red-meat ceiling: skip a red-meat species once the household's aggregate
          // red-meat serves/day have reached ~1/person/day. Forces the protein umbrella to
          // recruit poultry/fish/eggs/nuts/legumes for the remaining ~half (the nudge then
          // spreads that non-red-meat half across multiple sources).
          if(isRedMeatLivestock(lc.ls)){
            const cap = RED_MEAT_SERVES_PER_PERSON_DAY * ((s.household||[]).length || 1);
            const usedRed = lsFgCands.reduce((a,c)=> a + (isRedMeatLivestock(c.ls) ? lsServesPerDay(c.ls, c.usedCount) : 0), 0);
            if(usedRed >= cap - 1e-6) continue;
          }
          if(lc.score > bestLsEff){ bestLsEff = lc.score; bestLs = lc; }
        }
      }

      // ── Compare efficiency; allocate winner ────────────────────────────────
      const bestCropEff = best ? cropEfficiency(best.crop) : -Infinity;
      const lsWins = bestLs && (!best || bestLsEff > bestCropEff);

      if(lsWins){
        const labL2 = labourCap - usedLabour;
        const pasL2 = isAquaticLivestock(bestLs.ls)
          ? swBudget - usedSurfaceWaterHa
          : (s.landFixed === false)
            ? (s.annualHa||0) + (s.perennialHa||0) + (s.pastureHa||0) - perennialFootprint() - Math.max(usedCoolHa, usedWarmHa) - usedPastureHa
            : (s.pastureHa||0) - usedPastureHa;
        const maxByLab = bestLs.labourPerStep > 0 ? Math.floor(labL2 / bestLs.labourPerStep) : 99;
        const maxByPas = bestLs.spaceHaPerStep > 0 ? Math.floor((pasL2+0.0001) / bestLs.spaceHaPerStep) : 99;
        const capServes = targetServes * lsCapFrac - lsServesPerDay(bestLs.ls, bestLs.usedCount);
        let maxByCap = bestLs.servesPerStep > 0 ? Math.ceil(capServes / bestLs.servesPerStep) : 1;
        // ADG red-meat ceiling clamp: limit steps so the household's aggregate red-meat
        // serves/day stay at or below ~1/person/day.
        if(isRedMeatLivestock(bestLs.ls) && bestLs.servesPerStep > 0){
          const cap = RED_MEAT_SERVES_PER_PERSON_DAY * ((s.household||[]).length || 1);
          const usedRed = lsFgCands.reduce((a,c)=> a + (isRedMeatLivestock(c.ls) ? lsServesPerDay(c.ls, c.usedCount) : 0), 0);
          const redHeadroom = Math.max(0, cap - usedRed);
          maxByCap = Math.min(maxByCap, Math.floor(redHeadroom / bestLs.servesPerStep + 1e-6));
        }
        const gapSteps = bestLs.servesPerStep > 0 ? Math.max(1, Math.ceil((targetServes - umbServes()) / bestLs.servesPerStep)) : 1;
        const nSteps = Math.min(gapSteps, maxByCap, maxByLab, maxByPas, 5);
        if(nSteps <= 0){
          // If a red-meat species can't take even one step because it's at the ADG ceiling,
          // exclude it and re-evaluate so crops/poultry/fish fill the remaining protein
          // (rather than abandoning the umbrella). Otherwise the winner is genuinely blocked
          // by land/labour/cap and we stop.
          if(isRedMeatLivestock(bestLs.ls)){ lsBlocked.add(bestLs.ls.name); continue; }
          break;
        }
        addLivestockAllocation(bestLs, nSteps * bestLs.ls.step);
      } else if(best){
        usedNames.add(best.crop.name);
        const remaining = targetServes - umbServes();
        const sup = cropSupplyMonths(best.crop);
        const covFrac = Math.min(1, (sup.coveredCount||0) / 12);
        if(covFrac <= 0) continue;
        let wantServes = sufficient ? remaining * 0.10 : Math.min(remaining, targetServes * covFrac);
        // Diminishing-returns sizing (gap-scored groups): size the crop to the value its
        // months can STILL absorb, not its full in-season share. Average remaining coverage
        // across its supply window (concave via curve) scales the allocation down once those
        // months are already stocked — so each added crop is smaller and the next gets room.
        // Applies to starches AND protein (both gap-scored umbrellas) so a single efficient
        // source can't grab the whole target before the nudge recruits a second crop.
        if(gapScored && !sufficient){
          const dcurve = diminishingCfg(key).curve;
          let remSum = 0, wSum = 0;
          MONTHS.forEach((m, mi) => {
            const w = sup.months[mi];
            if(w <= 0.001) return;
            const cov = umbMonthCov(m) / targetServes;
            remSum += Math.pow(Math.max(0, 1 - cov), dcurve) * w;
            wSum += w;
          });
          const marginal = wSum > 0 ? remSum / wSum : 1;
          wantServes *= marginal;
          // Practical floor: once a group is well-covered, a new crop whose marginal value is
          // tiny isn't worth a token sliver of a tree. Below ~12% of a normal in-season share,
          // stop adding crops to this group rather than producing 1-m² allocations.
          const minMeaningful = targetServes * covFrac * 0.04;
          if(wantServes < minMeaningful) break;
          if(wantServes <= 0.01) continue;
        }
        // Soft diversity nudge: trim the first crop or two so the umbrella recruits another,
        // fading as crops accumulate (self-limiting — by the 3rd+ crop the factor is ~1, so it
        // never forces an impractical count). Fires on the fresh veg/fruit umbrellas AND on the
        // merged STARCHES and PROTEIN umbrellas (so a mix — e.g. legume + nut — is recruited
        // rather than one efficient source dominating). DAIRY is intentionally excluded: one
        // efficient dairy source realistically covers the whole group.
        const nudgeApplies = isFresh || key === 'protein' || key === 'starches';
        if(nudgeApplies && !sufficient){
          const dcfg = diversityCfg(key);
          if(dcfg.strength > 0){
            const priorCrops = Math.max(0, usedNames.size - 1);  // crops already in this umbrella
            const trim = dcfg.strength * Math.pow(dcfg.fade, priorCrops);
            wantServes *= (1 - trim);
          }
        }
        // Per-group in-season cap: limit this crop's serves/day WHILE SUPPLYING to
        // capPerPerson × household. In annual-average terms that's the cap × covFrac
        // (rate × fraction-of-year). Forces more crops in rather than one dominating its season.
        const capPP = FG_INSEASON_CAP_PER_PERSON[key];
        if(capPP != null){
          const hh = (s.household || []).length || 1;
          const maxWant = capPP * hh * covFrac;
          if(wantServes > maxWant) wantServes = maxWant;
        }
        if(wantServes <= 0.01) continue;
        const areaNeeded = areaForServes(best.crop, wantServes, s.fertility, s.confidence);
        if(!areaNeeded || areaNeeded <= 0) continue;
        const isAnnual2 = !best.crop.perennial;
        const season2p1 = isAnnual2 ? getCropSeason(best.crop) : null;
        let available;
        if(s.landFixed === false){
          const totalL = (s.annualHa||0) + (s.perennialHa||0) + (s.pastureHa||0) - usedPastureHa;
          if(isAnnual2){
            // Annuals use the combined pool minus physical perennial footprint and their seasonal usage
            available = totalL - perennialFootprint() - (season2p1==="warm" ? usedWarmHa : usedCoolHa);
          } else {
            // Each perennial layer only competes with itself — stacking is allowed
            const lay1 = cropLayer(best.crop);
            const lu1  = lay1==="canopy" ? usedCanopyHa : lay1==="trees" ? usedTreesHa : usedPerennialPlantsHa;
            available  = totalL - Math.max(usedCoolHa, usedWarmHa) - lu1;
          }
        } else if(isAnnual2){
          available = season2p1==="warm" ? s.annualHa - usedWarmHa : s.annualHa - usedCoolHa;
        } else {
          // Fixed mode: each layer competes only with itself, not with other layers
          const lay1 = cropLayer(best.crop);
          const lu1  = lay1==="canopy" ? usedCanopyHa : lay1==="trees" ? usedTreesHa : usedPerennialPlantsHa;
          available  = (s.perennialHa||0) - lu1;
        }
        const _pa1 = cropPoolAvail(best.crop, available);
        available = _pa1.available;
        const allocPool1 = _pa1.pool;
        if(available <= 0.0005) continue;
        let allocHa = Math.min(areaNeeded, available);
        const lph = cropLabour(best.crop, isMech);
        const labourLeft = labourCap - usedLabour;
        if(lph * allocHa > labourLeft){ allocHa = lph > 0 ? labourLeft / lph : 0; if(allocHa <= 0.0005) continue; }
        // Credit the crop's OWN sub-group key (e.g. a walnut → "nutsseeds"), so achieved[]
        // and monthCoverage[] stay keyed by the real 13-group taxonomy (display intact).
        // The umbrella's summed target/coverage is what the loop above tracks.
        const creditKey = FG_KEY[effectiveFoodGroup(best.crop)] || key;
        addAllocation(best.crop, allocHa, creditKey, allocPool1);
      } else { break; }
    }
  });

  // Phase 1.5 result — hoisted so plan return can always access it
  let p15NutsCovered = [];
  let p15GapNamesAll = [];

  // ── PHASE 1.5: Nutrient gap filling ──────────────────────────────────────
  // After food-group serves are met, allocate remaining land to close NRV gaps
  // to ~85% of each daily NRV target. Two implementations, selected by P15_GAPFILL:
  //   "lp"     — joint LP (lpSolveBigM): closes all remaining gaps together with
  //              least extra land; naturally exploits multi-nutrient crops.
  //   "greedy" — dormant fallback: the original per-nutrient density heuristic.
  const P15_GAPFILL = "lp";   // flip to "greedy" to revert to the heuristic
  if(s.household && s.household.length > 0){
    const P15_THRESHOLD = 0.85;
    const P15_MAX_CROPS = 6;
    // Nutrients we don't try to fill via crops (either fine by default, or not trackable)
    const P15_SKIP = new Set(["fat","carbs","p","na","cu","mn"]);

    // Build running daily nutrient accumulator from current plan
    const nutAccum = {};
    selected.forEach(({crop, allocHa}) => {
      if(!crop.nut) return;
      const adjY = subsistYield(crop, s.fertility, s.confidence);
      const annualKgPerHa = adjY * 1000;
      Object.entries(crop.nut).forEach(([k, per100g]) => {
        nutAccum[k] = (nutAccum[k]||0) + allocHa * annualKgPerHa * 1000 * per100g / 100 / 365;
      });
    });
    lsSelected.forEach(({ls, count}) => {
      lsNutContributions(ls).forEach(c => {
        const annualG = count * c.qty_per_animal_yr;
        Object.entries(c.nut).forEach(([k, per100g]) => {
          nutAccum[k] = (nutAccum[k]||0) + annualG * per100g / 100 / 365;
        });
      });
    });

    // Get household daily NRV targets
    const nrvDaily = householdNRV(s.household);

    // Find nutrients below threshold, worst first
    const p15Gaps = Object.entries(nrvDaily)
      .filter(([k, need]) => !P15_SKIP.has(k) && need > 0 && (nutAccum[k]||0) < need * P15_THRESHOLD)
      .sort((a,b) => (nutAccum[a[0]]||0)/a[1] - (nutAccum[b[0]]||0)/b[1]);
    // Record which gap nutrients were found (regardless of whether space allowed action)
    p15GapNamesAll = p15Gaps.slice(0, 6).map(([k]) => NUTRIENT_LABELS[k]).filter(Boolean);

    if(p15Gaps.length > 0){
      // Pool: ALL suitable checked crops with nut data — including those already in
      // the Phase 1 plan. Phase 1.5 can top up an existing crop if it's the best
      // source for a gap nutrient; that's often better than forcing a suboptimal new crop.
      const p15Pool = candidates.filter(c =>
        c.crop.nut && !HERB_EXCLUSIONS.has(c.crop.name)
      );
      // ── LP gap-filler (active default): "simplex-quality" — close all remaining
      //    NRV gaps jointly with least extra land, via the lpSolveBigM engine. ──
      if(P15_GAPFILL === "lp"){
        // Remaining gaps with a positive shortfall (worst-first order preserved).
        const lpGaps = p15Gaps
          .map(([k, need]) => ({ k, need, remaining: need * P15_THRESHOLD - (nutAccum[k] || 0) }))
          .filter(g => g.remaining > 1e-9);
        // Land crops only — pure-aquatic crops draw on the surface-water pool
        // (handled in Phase 1); modelling that pool here is out of scope for v1.
        const lpPool = p15Pool.filter(c =>
          cropHabitat(c.crop) !== "aquatic" && lpGaps.some(g => (c.crop.nut[g.k] || 0) > 0));

        if(lpGaps.length && lpPool.length){
          const nC = lpPool.length, nG = lpGaps.length, nVars = nC + nG;
          const M_SLACK = 1e6, EPS_LAB = 1e-3;
          // daily nutrient units delivered per ha of a candidate (cf. nutAccum build above)
          const dailyNutPerHa = (cand, k) => {
            const per100g = cand.crop.nut[k] || 0;
            return per100g ? cand.adjYield * 1000 * 1000 * per100g / 100 / 365 : 0;
          };
          const classOf = cand => cand.crop.perennial ? cropLayer(cand.crop)
                                                       : "annual-" + getCropSeason(cand.crop);
          // Objective: min Σ x_i·(1+ε·labour) + M·Σ slack — least extra land/labour,
          // big penalty for leaving a gap open (unreachable gaps stay open, not infeasible).
          const cObj = new Array(nVars).fill(0);
          lpPool.forEach((cand, i) => { cObj[i] = 1 + EPS_LAB * cropLabour(cand.crop, isMech); });
          for(let g = 0; g < nG; g++) cObj[nC + g] = M_SLACK;

          const A = [], ops = [], bb = [];
          // Gap rows (normalised by shortfall → O(1) coefficients):
          //   Σ x_i·(dailyNut/remaining) + slack_g ≥ 1
          lpGaps.forEach((g, gi) => {
            const row = new Array(nVars).fill(0);
            lpPool.forEach((cand, i) => { row[i] = dailyNutPerHa(cand, g.k) / g.remaining; });
            row[nC + gi] = 1;
            A.push(row); ops.push(">="); bb.push(1);
          });
          // Land-budget rows = leftover after Phase 1 (clamped ≥0 → always feasible):
          if(s.landFixed === false){
            const remTotal = Math.max(0,
              (s.annualHa || 0) + (s.perennialHa || 0) + (s.pastureHa || 0) - usedPastureHa
              - Math.max(usedCoolHa, usedWarmHa) - perennialFootprint());
            const row = new Array(nVars).fill(0);
            lpPool.forEach((_c, i) => { row[i] = 1; });
            A.push(row); ops.push("<="); bb.push(remTotal);
          } else {
            const caps = {
              "annual-cool": Math.max(0, (s.annualHa || 0) - usedCoolHa),
              "annual-warm": Math.max(0, (s.annualHa || 0) - usedWarmHa),
              canopy: Math.max(0, (s.perennialHa || 0) - usedCanopyHa),
              trees:  Math.max(0, (s.perennialHa || 0) - usedTreesHa),
              plants: Math.max(0, (s.perennialHa || 0) - usedPerennialPlantsHa),
            };
            Object.entries(caps).forEach(([cls, cap]) => {
              const row = new Array(nVars).fill(0); let any = false;
              lpPool.forEach((cand, i) => { if(classOf(cand) === cls){ row[i] = 1; any = true; } });
              if(any){ A.push(row); ops.push("<="); bb.push(cap); }
            });
          }
          // Labour row
          const labRow = new Array(nVars).fill(0);
          lpPool.forEach((cand, i) => { labRow[i] = cropLabour(cand.crop, isMech); });
          A.push(labRow); ops.push("<="); bb.push(Math.max(0, labourCap - usedLabour));

          let lp = null;
          try { lp = lpSolveBigM({ c: cObj, A, ops, b: bb }); } catch(e){ lp = null; }
          if(lp && lp.status === "optimal"){
            lpPool.forEach((cand, i) => {
              const ha = lp.x[i] || 0;
              if(ha < 0.002) return;
              const cls = classOf(cand);
              const landAvail =
                cls === "annual-cool" ? Math.max(0, (s.annualHa || 0) - usedCoolHa) :
                cls === "annual-warm" ? Math.max(0, (s.annualHa || 0) - usedWarmHa) :
                cls === "canopy"      ? Math.max(0, (s.perennialHa || 0) - usedCanopyHa) :
                cls === "trees"       ? Math.max(0, (s.perennialHa || 0) - usedTreesHa) :
                                        Math.max(0, (s.perennialHa || 0) - usedPerennialPlantsHa);
              const _pa = cropPoolAvail(cand.crop, landAvail);
              const applyHa = Math.min(ha, _pa.available);
              if(applyHa < 0.002) return;
              const fgKey = FG_KEY[effectiveFoodGroup(cand.crop)] || "othervet";
              addAllocation(cand.crop, applyHa, fgKey, _pa.pool);
              const addedAnnKg = applyHa * cand.adjYield * 1000;
              Object.entries(cand.crop.nut).forEach(([k, per100g]) => {
                nutAccum[k] = (nutAccum[k] || 0) + addedAnnKg * 1000 * per100g / 100 / 365;
              });
            });
          }
          const lpHandled = new Set();
          lpGaps.forEach(g => { if((nutAccum[g.k] || 0) >= g.need * P15_THRESHOLD) lpHandled.add(g.k); });
          p15NutsCovered = [...lpHandled]
            .filter(k => !["fat","carbs","p","na","cu","mn"].includes(k))
            .map(k => NUTRIENT_LABELS[k]).filter(Boolean);
        } else {
          p15NutsCovered = [];
        }
      }

      // ── Original greedy per-nutrient gap-fill — kept verbatim as a dormant,
      //    revertible fallback; runs only when P15_GAPFILL === "greedy". ──
      if(P15_GAPFILL === "greedy"){
      // Separate tracking for crops already used within Phase 1.5 (prevents the same
      // crop being picked for two different gap nutrients within the P15 budget).
      const p15AllocNames = new Set();
      const p15Handled = new Set();
      let p15Count = 0;
      for(const [gapKey, gapNeed] of p15Gaps){
        if(p15Count >= P15_MAX_CROPS) break;
        if(p15Handled.has(gapKey)) continue;
        if((nutAccum[gapKey]||0) >= gapNeed * P15_THRESHOLD) continue;

        // Score pool for this gap. Two factors:
        //   • nutPerHaYr  — nutrient delivered per hectare-year (land efficiency)
        //   • density      — nutrient per 100g of food (nutritional concentration)
        // Ranking on land-efficiency ALONE lets a high-tonnage, low-density crop (e.g.
        // beetroot at ~45 t/ha) win an energy/fat gap by sheer mass, producing absurd
        // 20-serve vegetable blocks. Blending in per-gram density steers calorie/fat/
        // zinc/iron gaps toward concentrated sources (nuts, seeds) — the realistic fix —
        // while still respecting land cost. The geometric-style blend (nutPerHaYr × √density)
        // keeps both forces in play rather than letting either dominate.
        const scored = p15Pool
          .filter(c => !p15AllocNames.has(c.crop.name) && (c.crop.nut[gapKey]||0) > 0)
          .map(c => {
            const density = c.crop.nut[gapKey] || 0;            // per 100g
            const nutPerHaYr = c.adjYield * 10000 * density;    // per ha-yr
            const score = nutPerHaYr * Math.sqrt(density);      // density-weighted
            return { cand:c, nutPerHaYr, density, score };
          })
          .filter(x => x.nutPerHaYr > 0)
          .sort((a,b) => b.score - a.score);

        if(!scored.length){ p15Handled.add(gapKey); continue; }

        const {cand: top, nutPerHaYr} = scored[0];
        const isAnn = !top.crop.perennial;
        const s15 = isAnn ? getCropSeason(top.crop) : null;
        const landAvail15 = s.landFixed === false
            ? (()=>{
                const totalL15 = (s.annualHa||0) + (s.perennialHa||0) + (s.pastureHa||0) - usedPastureHa;
                if(isAnn){
                  return totalL15 - perennialFootprint() - (s15==="warm" ? usedWarmHa : usedCoolHa);
                } else {
                  const lay15 = cropLayer(top.crop);
                  const lu15  = lay15==="canopy" ? usedCanopyHa : lay15==="trees" ? usedTreesHa : usedPerennialPlantsHa;
                  return totalL15 - Math.max(usedCoolHa, usedWarmHa) - lu15;
                }
              })()
            : isAnn
              ? (s15==="warm" ? s.annualHa - usedWarmHa : s.annualHa - usedCoolHa)
              : (()=>{
                  const lay15 = cropLayer(top.crop);
                  const lu15  = lay15==="canopy" ? usedCanopyHa : lay15==="trees" ? usedTreesHa : usedPerennialPlantsHa;
                  return (s.perennialHa||0) - lu15;
                })();
        const _pa15 = cropPoolAvail(top.crop, landAvail15);
        const spaceLeft = _pa15.available;
        const allocPool15 = _pa15.pool;
        if(spaceLeft < 0.005){ p15Handled.add(gapKey); continue; }

        const lph15 = cropLabour(top.crop, isMech);
        const labLeft15 = labourCap - usedLabour;
        if(lph15 > 0 && labLeft15 < 0.5){ p15Handled.add(gapKey); continue; }

        // Area needed to fill gap to threshold
        const gapDaily = gapNeed * P15_THRESHOLD - (nutAccum[gapKey]||0);
        let ha15 = nutPerHaYr > 0 ? (gapDaily * 365) / nutPerHaYr : 0;
        ha15 = Math.min(ha15, spaceLeft * 0.35); // cap at 35% of remaining space
        if(lph15 > 0) ha15 = Math.min(ha15, labLeft15 / lph15);
        if(ha15 < 0.002){ p15Handled.add(gapKey); continue; }

        const fgKey15 = FG_KEY[effectiveFoodGroup(top.crop)] || 'othervet';
        addAllocation(top.crop, ha15, fgKey15, allocPool15);
        p15AllocNames.add(top.crop.name);
        p15Count++;

        // Update nutAccum and mark any nutrients now covered
        const addedAnnKg = ha15 * top.adjYield * 1000;
        Object.entries(top.crop.nut).forEach(([k, per100g]) => {
          const dailyG = addedAnnKg * 1000 * per100g / 100 / 365;
          nutAccum[k] = (nutAccum[k]||0) + dailyG;
          if((nutAccum[k]||0) >= (nrvDaily[k]||0) * P15_THRESHOLD) p15Handled.add(k);
        });
        p15Handled.add(gapKey);
      }
      // Write results into hoisted variable for plan return
      p15NutsCovered = [...p15Handled]
        .filter(k => !["fat","carbs","p","na","cu","mn"].includes(k))
        .map(k => NUTRIENT_LABELS[k]).filter(Boolean);
      }  // end greedy fallback (P15_GAPFILL === "greedy")
    }
  }

  // (p15NutsCovered is set inside the Phase 1.5 block above)

  // ── PHASE 2: maximiseYield → fill ALL remaining land/labour ──────────────
  // Runs only for maximiseYield mode. Adds new crops AND tops up existing ones.
  if(objMode === "maximiseYield"){
    // Sort candidates by tier (suitability) then adjusted yield, highest first
    const yieldOrder = [...candidates].sort((a, b) =>
      b.tier - a.tier || b.adjYield - a.adjYield
    );
    // Livestock sorted by serves/day per step (most productive first)
    const lsYieldOrder = [...lsCandidates].sort((a, b) => b.servesPerStep - a.servesPerStep);

    let safety = 0;
    while(safety++ < 300){
      // Re-compute all remaining budgets each iteration
      const pf2        = perennialFootprint();
      const maxBed2    = Math.max(usedCoolHa, usedWarmHa);
      const totalL2    = (s.annualHa||0) + (s.perennialHa||0) + (s.pastureHa||0) - usedPastureHa;
      const coolLeft2     = s.landFixed === false ? totalL2 - pf2 - usedCoolHa     : eb.annualHa    - usedCoolHa;
      const warmLeft2     = s.landFixed === false ? totalL2 - pf2 - usedWarmHa     : eb.annualHa    - usedWarmHa;
      // Per-layer space remaining — each layer only competes with itself
      const perHa2        = s.perennialHa||0;
      const layerSpace2   = {
        canopy: s.landFixed === false ? totalL2 - maxBed2 - usedCanopyHa         : perHa2 - usedCanopyHa,
        trees:  s.landFixed === false ? totalL2 - maxBed2 - usedTreesHa          : perHa2 - usedTreesHa,
        plants: s.landFixed === false ? totalL2 - maxBed2 - usedPerennialPlantsHa: perHa2 - usedPerennialPlantsHa,
      };
      const anyPerennialLeft = Object.values(layerSpace2).some(v => v > 0.001);
      const labourLeft    = labourCap      - usedLabour;
      const pastureLeft   = s.landFixed === false ? totalL2 - pf2 - maxBed2 - usedPastureHa : (s.pastureHa||0) - usedPastureHa;
      const swLeft2       = swBudget - usedSurfaceWaterHa;

      if(coolLeft2 < 0.001 && warmLeft2 < 0.001 && !anyPerennialLeft && labourLeft < 1 && pastureLeft < 0.001) break;

      let allocated = false;

      // ── Try crops first (highest yield crop that still has space + labour) ──
      for(const cand of yieldOrder){
        const isAnnual = !cand.crop.perennial;
        const season2 = isAnnual ? getCropSeason(cand.crop) : null;
        let landSpace2;
        if(isAnnual){
          landSpace2 = season2==="cool" ? coolLeft2 : season2==="warm" ? warmLeft2 : Math.max(coolLeft2,warmLeft2);
        } else {
          const layP2 = cropLayer(cand.crop);
          landSpace2 = layerSpace2[layP2] || 0;
        }
        const _pa2 = cropPoolAvail(cand.crop, landSpace2);
        const spaceLeft = _pa2.available;
        const allocPool2 = _pa2.pool;
        if(spaceLeft < 0.001) continue;
        const lph = cropLabour(cand.crop, isMech);
        const maxByLabour = lph > 0 ? Math.min(spaceLeft, labourLeft / lph) : spaceLeft;
        // Allocate 25% of the remaining budget in each pass — fills budgets in ~4-5 passes
        const allocHa = Math.min(spaceLeft * 0.25, maxByLabour);
        if(allocHa < 0.0005) continue;
        const fg  = effectiveFoodGroup(cand.crop);
        const key = FG_KEY[fg];
        if(!key) continue;
        addAllocation(cand.crop, allocHa, key, allocPool2);
        allocated = true;
        break;  // one allocation per iteration so budgets are rechecked
      }

      // ── Then try livestock for remaining pasture / labour ──────────────────
      if(!allocated && pastureLeft > 0.001 && labourLeft > 1){
        for(const lc of lsYieldOrder){
          if(isAquaticLivestock(lc.ls)) continue;  // aquatic stock allocated in Phase 1 (surface-water budget)
          if(lc.spaceHaPerStep > pastureLeft + 0.0001) continue;
          if(lc.labourPerStep  > labourLeft  + 0.1)   continue;
          const maxByPasture = Math.floor((pastureLeft + 0.0001) / lc.spaceHaPerStep);
          const maxByLabour2 = lc.labourPerStep > 0
            ? Math.floor(labourLeft / lc.labourPerStep) : maxByPasture;
          const nSteps = Math.min(maxByPasture, maxByLabour2, 10);
          if(nSteps < 1) continue;
          addLivestockAllocation(lc, nSteps * lc.ls.step);
          allocated = true;
          break;
        }
      }

      if(!allocated) break;
    }
  }

  return {selected, lsSelected, achieved, targets, usedCoolHa, usedWarmHa, usedAnnualHa: usedCoolHa+usedWarmHa, usedPerennialHa: perennialFootprint(), usedPerennialHaSum: usedPerennialHa, layers: {canopy: usedCanopyHa, trees: usedTreesHa, plants: usedPerennialPlantsHa}, usedLabour, usedPastureHa, usedSurfaceWaterHa, annualBudget, monthCoverage, suitableCount: candidates.length, p15NutsCovered: p15NutsCovered||[], p15GapNamesAll: p15GapNamesAll||[]};
}

// ═══════════════════════════════════════════════════════════════════════════
// LINEAR PROGRAMME (LP) PLAN GENERATION — OPTION D
// ═══════════════════════════════════════════════════════════════════════════
// Formulates farm planning as a constrained optimisation problem and solves
// it with a Big-M simplex. Unlike the greedy generatePlan() above (which fills
// food-group serves first, then patches nutrient gaps), the LP considers all
// constraints and trade-offs jointly. Output is a true optimum (within the
// modelling assumptions): minimum land use that meets household NRVs.
//
// Decision variables:
//   x_i  ∈ [0,∞)  = hectares of crop i
//   y_j  ∈ [0,∞)  = head count of livestock species j (continuous in LP,
//                    rounded to species step after)
//   u_n  ∈ [0,∞)  = unmet fraction of NRV for nutrient n (slack — penalised)
//   v_g  ∈ [0,∞)  = unmet fraction of food-group g serves (slack — penalised)
//
// Hard constraints:
//   • cool-season annual area  Σ x_i ≤ annualHa
//   • warm-season annual area  Σ x_i ≤ annualHa
//   • each perennial layer     Σ x_i ≤ perennialHa  (canopy, trees, plants)
//   • labour                   Σ x_i × labour_i + Σ y_j × labour_j ≤ labourCap
//   • pasture                  Σ y_j × space_j ≤ pastureHa
//
// Soft constraints (with unmet slack):
//   • nutrient n   Σ x_i × yield_n_i/NRV_n + Σ y_j × yield_n_j/NRV_n + u_n ≥ 1
//   • food group g (same form with v_g)
//
// Objective: min Σ x_i × (1 + ε·labour) + Σ y_j × (pasture/ha) + Mnut·Σ u_n + Mfg·Σ v_g
//   — small resource cost, large penalty for unmet nutrition

// ── LP solver: Big M simplex ───────────────────────────────────────────────
// Solves: min c'x  s.t. Ax {op} b, x ≥ 0  where op ∈ {"<=", ">=", "="}
// Returns: { status: "optimal"|"infeasible"|"unbounded", x, objective }
function lpSolveBigM(problem){
  const EPS = 1e-9;
  const MAX_ITER = 6000;
  const M = 1e8;

  const cIn = [...problem.c];
  const A0 = problem.A.map(r => [...r]);
  const ops = [...problem.ops];
  const b0 = [...problem.b];
  const m = A0.length;
  const n = cIn.length;

  // Flip rows with negative RHS so b ≥ 0 (required for canonical simplex start)
  for(let i = 0; i < m; i++){
    if(b0[i] < 0){
      for(let j = 0; j < n; j++) A0[i][j] = -A0[i][j];
      b0[i] = -b0[i];
      ops[i] = ops[i] === "<=" ? ">=" : ops[i] === ">=" ? "<=" : "=";
    }
  }

  // Allocate slack/surplus/artificial columns
  const slack = new Array(m).fill(-1);
  const art   = new Array(m).fill(-1);
  let nExtra = 0;
  for(let i = 0; i < m; i++){
    if(ops[i] === "<="){ slack[i] = n + nExtra++; }
    else if(ops[i] === ">="){ slack[i] = n + nExtra++; art[i] = n + nExtra++; }
    else { art[i] = n + nExtra++; }
  }
  const N = n + nExtra;

  // Build augmented tableau A (m × N) and objective cAug (length N)
  const A = A0.map(r => {
    const row = new Array(N).fill(0);
    for(let j = 0; j < n; j++) row[j] = r[j];
    return row;
  });
  for(let i = 0; i < m; i++){
    if(ops[i] === "<="){ A[i][slack[i]] = 1; }
    else if(ops[i] === ">="){ A[i][slack[i]] = -1; A[i][art[i]] = 1; }
    else { A[i][art[i]] = 1; }
  }
  const cAug = new Array(N).fill(0);
  for(let j = 0; j < n; j++) cAug[j] = cIn[j];
  for(let i = 0; i < m; i++){ if(art[i] >= 0) cAug[art[i]] = M; }

  // Initial basis (slack for ≤, artificial otherwise)
  const basis = new Array(m);
  for(let i = 0; i < m; i++){
    basis[i] = ops[i] === "<=" ? slack[i] : art[i];
  }
  const b = [...b0];

  // Main loop
  for(let iter = 0; iter < MAX_ITER; iter++){
    // Reduced costs: rj = cj - Σ_i c_basis[i] × A[i][j]
    const reduced = new Array(N);
    for(let j = 0; j < N; j++){
      let zj = 0;
      for(let i = 0; i < m; i++) zj += cAug[basis[i]] * A[i][j];
      reduced[j] = cAug[j] - zj;
    }

    // Pick entering variable: most negative reduced cost (Bland's rule on ties)
    let pivCol = -1, mostNeg = -EPS;
    for(let j = 0; j < N; j++){
      if(reduced[j] < mostNeg){ mostNeg = reduced[j]; pivCol = j; }
    }
    if(pivCol < 0) break; // optimal

    // Min-ratio test
    let pivRow = -1, minRatio = Infinity;
    for(let i = 0; i < m; i++){
      if(A[i][pivCol] > EPS){
        const ratio = b[i] / A[i][pivCol];
        if(ratio < minRatio - EPS){ minRatio = ratio; pivRow = i; }
      }
    }
    if(pivRow < 0) return { status: "unbounded", x: new Array(n).fill(0), objective: -Infinity };

    // Pivot
    const piv = A[pivRow][pivCol];
    for(let j = 0; j < N; j++) A[pivRow][j] /= piv;
    b[pivRow] /= piv;
    for(let i = 0; i < m; i++){
      if(i === pivRow) continue;
      const f = A[i][pivCol];
      if(Math.abs(f) < EPS) continue;
      for(let j = 0; j < N; j++) A[i][j] -= f * A[pivRow][j];
      b[i] -= f * b[pivRow];
    }
    basis[pivRow] = pivCol;
  }

  // Infeasibility check: any artificial still basic with positive value?
  let infeasible = false;
  for(let i = 0; i < m; i++){
    if(art[i] >= 0 && basis[i] === art[i] && b[i] > 1e-5){ infeasible = true; break; }
  }

  // Extract original-variable values
  const x = new Array(n).fill(0);
  for(let i = 0; i < m; i++){
    if(basis[i] < n) x[basis[i]] = Math.max(0, b[i]);
  }

  let obj = 0;
  for(let j = 0; j < n; j++) obj += cIn[j] * x[j];

  return { status: infeasible ? "infeasible" : "optimal", x, objective: obj };
}


// ── Render helpers ─────────────────────────────────────────
function tag(fg){return`<span class="tag ${FG_TAG[fg]||"tag-disc"}">${FG_SHORT[fg]||fg}</span>`}
function showMonthDetail(m){
  state.selectedMonth = (state.selectedMonth === m) ? null : m;
  renderApp();
}

function monthBar(months){return`<div class="month-grid">${MONTHS.map(m=>`<div class="month-cell ${months[m]==="P"?"month-p":months[m]==="S"?"month-s":""}" title="${m.toUpperCase()}${months[m]?" "+months[m]:""}"></div>`).join("")}</div>`}
function pct(achieved,target){return target?Math.min(200,Math.round(achieved/target*100)):0}
function fmtHa(ha){return ha>=2?ha.toFixed(1)+" ha":Math.round(ha*10000)+" m²"}

// ── Reusable land-composition figure: one large bar = total land area,
//    filled by annual / perennial / pasture / pond, with vacant remainder.
//    Used when "Fixed land allocation" is OFF (fluid pool). ───────────────
const LAND_SEG_COLORS = {annual:"#8A6A2E", perennial:"#5C7A3A", pasture:"#8C4A2A", pond:"#4A7C8A", vacant:"#D8CEB2"};
const LAYER_COLORS_BAR = {canopy:"#3D5226", trees:"#5C7A3A", plants:"#8FAF60"};
function landUseBreakdown(s, p){
  const annual    = Math.max(p.usedCoolHa||0, p.usedWarmHa||0);
  const perennial = p.usedPerennialHa||0;
  const pasture   = p.usedPastureHa||0;
  const damOn     = s.irrigationDam;
  const pond      = damOn ? sizeDam(p).footprintHa : (p.usedSurfaceWaterHa||0);
  const total     = (s.annualHa||0)+(s.perennialHa||0)+(s.pastureHa||0)+(damOn ? 0 : (s.surfaceWaterHa||0));
  const usedSum   = annual+perennial+pasture+pond;
  const vacant    = Math.max(0, total - usedSum);
  return {annual, perennial, pasture, pond, vacant, total, usedSum};
}
const HATCH = "repeating-linear-gradient(45deg,#E4DBC4 0 5px,#D3C8AC 5px 10px)";
const HATCH_LIGHT = "repeating-linear-gradient(45deg,rgba(255,255,255,.18) 0 4px,rgba(0,0,0,.06) 4px 8px)";
function landCompositionFigure(s, p){
  const b = landUseBreakdown(s, p);
  const denom = Math.max(b.total, b.usedSum) > 0 ? Math.max(b.total, b.usedSum) : 1;
  const layers = p.layers || {canopy:0, trees:0, plants:0};
  const layerDefs = [
    {key:"canopy", label:"Canopy (≥25m)", color:LAYER_COLORS_BAR.canopy},
    {key:"trees",  label:"Trees (4–24m)", color:LAYER_COLORS_BAR.trees},
    {key:"plants", label:"Shrubs (<4m)",  color:LAYER_COLORS_BAR.plants},
  ];

  // Build perennial segment as a vertical stack of 3 rows (10px each = 30px total)
  // Each row fills left-portion proportional to that layer's ha / perennial footprint
  function perennialStackedSeg(perennialHa){
    if(perennialHa < 0.00005) return '';
    const fp = perennialHa; // footprint = max layer, used as denominator for row widths
    const rows = layerDefs.map(ld=>{
      const ha = layers[ld.key] || 0;
      const fillPct = fp > 0 ? Math.min(100, ha/fp*100).toFixed(2) : 0;
      const filledPart = ha > 0.00005
        ? `<div style="width:${fillPct}%;height:100%;background:${ld.color}"></div>`
        : '';
      const hatchPart = fillPct < 99.99
        ? `<div style="flex:1;height:100%;background:${ld.color};opacity:0.25;background-image:${HATCH_LIGHT}"></div>`
        : '';
      return `<div style="display:flex;width:100%;height:10px;overflow:hidden">${filledPart}${hatchPart}</div>`;
    }).join('');
    return `<div title="Perennial layers: ${fmtHa(perennialHa)}" style="width:${(perennialHa/denom*100).toFixed(2)}%;height:100%;display:flex;flex-direction:column;border-left:1px solid rgba(61,46,28,.25);overflow:hidden">${rows}</div>`;
  }

  const segs = [
    {label:"Annual beds", val:b.annual,    color:LAND_SEG_COLORS.annual},
    {label:"Perennial",   val:b.perennial, color:null, perennial:true},
    {label:"Pasture",     val:b.pasture,   color:LAND_SEG_COLORS.pasture},
    {label:s.irrigationDam?"Irrigation dam":"Pond / water",val:b.pond,      color:LAND_SEG_COLORS.pond},
    {label:"Vacant",      val:b.vacant,    color:LAND_SEG_COLORS.vacant, hatch:true},
  ];
  const barSegs = segs.filter(x=>x.val>0.00005).map((x,i)=>{
    if(x.perennial) return perennialStackedSeg(x.val);
    const w = x.val/denom*100;
    return `<div title="${x.label}: ${fmtHa(x.val)}" style="width:${w.toFixed(2)}%;background:${x.hatch?HATCH:x.color};${i>0?'border-left:1px solid rgba(61,46,28,.25)':''}"></div>`;
  }).join("");

  const ticks = Array.from({length:5},(_,i)=>{
    const v = denom*i/4;
    return `<span>${v>=1?v.toFixed(1):Math.round(v*10000)}</span>`;
  }).join("");

  const leftSegs  = segs.filter(x => !x.perennial);
  const perSeg     = segs.find(x => x.perennial);

  const mkRow = (x) => {
    const pctv = b.total>0 ? Math.round(x.val/b.total*100) : 0;
    const sw = `<span class="land-leg-sw" style="background:${x.hatch?HATCH:x.color}"></span>`;
    return `<div class="land-leg-row">${sw}<span class="land-leg-lbl">${x.label}</span><span class="land-leg-val">${fmtHa(x.val)}</span><span class="land-leg-pct">${pctv}%</span></div>`;
  };

  const leftHTML = leftSegs.map(mkRow).join('');

  let rightHTML = '';
  if(perSeg){
    const pctv = b.total>0 ? Math.round(perSeg.val/b.total*100) : 0;
    const sw = `<span class="land-leg-sw" style="background:${LAYER_COLORS_BAR.trees}"></span>`;
    rightHTML = `<div class="land-leg-row">${sw}<span class="land-leg-lbl">${perSeg.label}</span><span class="land-leg-val">${fmtHa(perSeg.val)}</span><span class="land-leg-pct">${pctv}%</span></div>`;
    if(perSeg.val > 0.00005){
      rightHTML += layerDefs.map(ld=>{
        const ha = layers[ld.key]||0;
        if(ha < 0.00005) return '';
        return `<div class="land-leg-sub"><span class="land-leg-sw" style="background:${ld.color}"></span><span class="land-leg-lbl">${ld.label}</span><span class="land-leg-val">${fmtHa(ha)}</span></div>`;
      }).join('');
    }
  }

  const legend = `<div class="land-leg-left">${leftHTML}</div><div class="land-leg-right">${rightHTML}</div>`;

  return `<div class="land-fig">
    <div class="land-fig-bar">${barSegs||'<div style="width:100%;background:'+HATCH+'"></div>'}</div>
    <div class="land-fig-axis">${ticks}</div>
    <div class="land-fig-axiscap">hectares allocated · total holding ${fmtHa(b.total)}${b.usedSum>b.total+0.0001?' · <span style=\"color:#9A3A2A\">over budget</span>':''}</div>
    <div class="land-fig-legend">${legend}</div>
  </div>`;
}
// Labour-by-task stacked bar — shared by Farm Plan overview and Manual adjustment.
// NRV coverage bars (reusable in Overview + Adjust). Returns inner HTML for a sci-fig.
function nrvFigure(s, p){
  const yieldNut = nutritionalYield(p, s.fertility, s.confidence);
  const dailyNRV = householdNRV(s.household);
  const order = ["kcal","protein","fat","fiber","ca","fe","mg","k","zn","vitA","vitC","vitE","b1","b2","b3","b6","folate"];
  const fmtN = v => v < 1000 ? v.toFixed(0) : v >= 1e6 ? (v/1e6).toFixed(1)+"M" : v >= 1e4 ? Math.round(v/1000)+"k" : Math.round(v).toLocaleString();
  const rows = order.map(n => {
    const produced = yieldNut[n] || 0;
    const needed = (dailyNRV[n] || 0) * 365;
    if(!needed) return "";
    const pct = Math.round(produced/needed*100);
    const cap = Math.min(100, pct);
    const barColor = pct >= 100 ? "var(--green)" : pct >= 70 ? "var(--clay)" : "var(--iron)";
    const label = NUTRIENT_LABELS[n] || n;
    const unit = NUTRIENT_UNITS[n] || "";
    const badge = pct >= 100 ? `<span class="adj-delta-good">✓</span>` : `<span style="color:${pct>=70?"var(--clay)":"var(--iron)"}">${pct}%</span>`;
    return `<div class="adj-nut-row">
      <div class="adj-nut-name">${label}</div>
      <div class="adj-nut-info">${fmtN(produced)} / ${fmtN(needed)} ${unit}</div>
      <div class="adj-nut-bar"><div class="adj-nut-fill" style="width:${cap}%;background:${barColor}"></div></div>
      <div class="adj-nut-pct">${badge}</div>
    </div>`;
  }).filter(r=>r).join("");
  return `<div class="adj-nut-list">${rows}</div>`;
}

function labourTaskFigure(s, p){
  let labAnnual=0, labPerennial=0;
  (p.selected||[]).forEach(x=>{ if(x.crop && x.crop.perennial) labPerennial += x.labour||0; else labAnnual += x.labour||0; });
  let labLivestock=0;
  (p.lsSelected||[]).forEach(e=>{ const c=e.count||0; labLivestock += ((e.ls&&e.ls.labour_hrs_per_animal)||0)*c; });
  const labTotal = labAnnual+labPerennial+labLivestock;
  const labBudget = s.hoursPerWeek*52;
  const segs = [
    {label:"Annual crop care", val:labAnnual, color:"#6E8C3E"},
    {label:"Perennial &amp; orchard care", val:labPerennial, color:"#B5762F"},
    {label:"Livestock husbandry", val:labLivestock, color:"#8C4A2A"},
  ].filter(x=>x.val>0.5);
  const labOver = labTotal > labBudget + 0.5;
  const scale = labOver ? labTotal : (labBudget>0 ? labBudget : (labTotal||1));
  let bar = segs.map(x=>`<div style="width:${x.val/scale*100}%;background:${x.color}" title="${x.label}: ${Math.round(x.val).toLocaleString()} h"></div>`).join("");
  const spare = labBudget - labTotal;
  if(!labOver && spare > 0.5) bar += `<div style="width:${spare/scale*100}%;background:${HATCH}" title="Spare capacity: ${Math.round(spare).toLocaleString()} h"></div>`;
  const legend = segs.map(x=>`<div class="land-leg-row"><span class="land-leg-sw" style="background:${x.color}"></span><span class="land-leg-lbl">${x.label}</span><span class="land-leg-val">${Math.round(x.val).toLocaleString()} h</span><span class="land-leg-pct">${labTotal>0?Math.round(x.val/labTotal*100):0}%</span></div>`).join("")
    + ((!labOver && spare>0.5)?`<div class="land-leg-row"><span class="land-leg-sw" style="background:${HATCH}"></span><span class="land-leg-lbl">Spare capacity</span><span class="land-leg-val">${Math.round(spare).toLocaleString()} h</span><span class="land-leg-pct">—</span></div>`:"");
  return `<div class="land-fig">
    <div class="land-fig-bar">${bar||'<div style="width:100%;background:'+HATCH+'"></div>'}</div>
    <div class="land-fig-axis"><span>0</span><span>${Math.round(scale).toLocaleString()} h</span></div>
    <div class="land-fig-axiscap">hours per year · budget ${labBudget.toLocaleString()} h${labOver?' · <span style="color:#9A3A2A">over budget</span>':''}</div>
    <div class="land-fig-legend">${legend}</div>
  </div>`;
}

// Compact two-row budget strip for Manual Adjustment (Direction A — Instrument Rail).
// Labour + Land condensed into single-line bars with inline legends.
function compactBudgetStrip(s, p){
  // Labour segments (mirror labourTaskFigure)
  let labAnnual=0, labPerennial=0;
  (p.selected||[]).forEach(x=>{ if(x.crop && x.crop.perennial) labPerennial += x.labour||0; else labAnnual += x.labour||0; });
  let labLivestock=0;
  (p.lsSelected||[]).forEach(e=>{ const c=e.count||0; labLivestock += ((e.ls&&e.ls.labour_hrs_per_animal)||0)*c; });
  const labTotal = labAnnual+labPerennial+labLivestock;
  const labBudget = s.hoursPerWeek*52;
  const labOver = labTotal > labBudget + 0.5;
  const lScale = labOver ? labTotal : (labBudget>0?labBudget:(labTotal||1));
  const lSegs = [
    {label:"Annual", val:labAnnual, color:"#6E8C3E"},
    {label:"Perennial", val:labPerennial, color:"#B5762F"},
    {label:"Livestock", val:labLivestock, color:"#8C4A2A"},
  ].filter(x=>x.val>0.5);
  const lSpare = labBudget - labTotal;
  let lBar = lSegs.map(x=>`<div style="width:${x.val/lScale*100}%;background:${x.color}" title="${x.label}: ${Math.round(x.val)} h"></div>`).join("");
  if(!labOver && lSpare>0.5) lBar += `<div style="width:${lSpare/lScale*100}%;background:${HATCH}" title="Spare: ${Math.round(lSpare)} h"></div>`;
  const lLeg = lSegs.map(x=>`<span class="bz-leg"><i style="background:${x.color}"></i>${x.label} <b>${Math.round(x.val)}h</b></span>`).join("")
    + (!labOver && lSpare>0.5 ? `<span class="bz-leg"><i style="background:${HATCH};border-color:var(--groove)"></i>Spare <b>${Math.round(lSpare)}h</b></span>` : "")
    + (labOver ? `<span class="bz-leg" style="color:var(--iron-dk)"><b>+${Math.round(labTotal-labBudget)}h over</b></span>` : "");

  // Land segments (reuse landUseBreakdown)
  const b = landUseBreakdown(s, p);
  const lnDenom = Math.max(b.total, b.usedSum)>0?Math.max(b.total, b.usedSum):1;
  const lnSegs = [
    {label:"Annual beds", val:b.annual, color:LAND_SEG_COLORS.annual},
    {label:"Perennial", val:b.perennial, color:LAND_SEG_COLORS.perennial},
    {label:"Pasture", val:b.pasture, color:LAND_SEG_COLORS.pasture},
    {label:s.irrigationDam?"Dam":"Pond", val:b.pond, color:LAND_SEG_COLORS.pond},
    {label:"Vacant", val:b.vacant, color:LAND_SEG_COLORS.vacant, hatch:true},
  ].filter(x=>x.val>0.00005);
  const lnBar = lnSegs.map((x,i)=>`<div title="${x.label}: ${fmtHa(x.val)}" style="width:${x.val/lnDenom*100}%;background:${x.hatch?HATCH:x.color};${i>0?'border-left:1px solid rgba(61,46,28,.22)':''}"></div>`).join("");
  const lnLeg = lnSegs.map(x=>`<span class="bz-leg"><i style="background:${x.hatch?HATCH:x.color};${x.hatch?'border-color:var(--groove)':''}"></i>${x.label} <b>${b.total>0?Math.round(x.val/b.total*100):0}%</b></span>`).join("");
  const lnOver = b.usedSum > b.total + 0.0001;

  return `<div class="bz-strip">
    <div class="bz-row">
      <div class="bz-head">Labour<br><b>${Math.round(labTotal)} / ${Math.round(labBudget)}h</b></div>
      <div class="bz-bar">${lBar||'<div style="width:100%;background:'+HATCH+'"></div>'}</div>
      <div class="bz-legs">${lLeg}</div>
    </div>
    <div class="bz-row">
      <div class="bz-head">Land<br><b>${fmtHa(b.usedSum)} / ${fmtHa(b.total)}</b></div>
      <div class="bz-bar">${lnBar||'<div style="width:100%;background:'+HATCH+'"></div>'}</div>
      <div class="bz-legs">${lnLeg}${lnOver?'<span class="bz-leg" style="color:var(--iron-dk)"><b>over budget</b></span>':''}</div>
    </div>
  </div>`;
}
// Aromatic herbs — kept in DB and crop selection, but excluded from auto plan
// (you only need tiny amounts, no point allocating land or labour to them)
// ── Aquatic habitat helpers (data-driven; replaces the old hardcoded Sets) ───
// Each crop/animal's habitat comes from its `habitats` field in crops.json:
//   absent / no "aquatic"  -> land-only
//   ["aquatic"]            -> pure aquatic (surface water only)
//   ["aquatic","land"]     -> "both": grows on land OR in water
function cropHabitat(c){
  const h = c && c.habitats;
  if(!Array.isArray(h) || !h.includes("aquatic")) return "land";
  return h.includes("land") ? "both" : "aquatic";
}
// Livestock are only ever pure-aquatic or land (never "both").
function isAquaticLivestock(ls){ return cropHabitat(ls) === "aquatic"; }
// ── ADG red-meat ceiling ─────────────────────────────────────────────────────
// The Australian Dietary Guidelines cap LEAN RED MEAT at ~7 serves/person/week
// (≈1 serve/person/day) — beef, lamb, veal, pork, goat, kangaroo. Poultry, fish and
// eggs are NOT subject to this ceiling. We classify red meat as a Meat-group animal
// whose category is Ruminant or Omnivore (pig); Poultry & Aquaculture are exempt.
const RED_MEAT_CATEGORIES = new Set(["Ruminant", "Omnivore"]);
function isRedMeatLivestock(ls){
  return !!ls && ls.food_group === "Meat" && RED_MEAT_CATEGORIES.has(ls.category);
}
const RED_MEAT_SERVES_PER_PERSON_DAY = 1.0;  // ADG: ~7/week ≈ 1/day
// AQUATIC_CROPS set retired — aquatic eligibility now comes from cropHabitat() (crops.json `habitats`).
const HERB_EXCLUSIONS = new Set([
  "Basil","Chives","Coriander (Fresh)","Dill","Lemongrass","Mint","Parsley","Parsley (Curly)","Rosemary"
]);

// Food-group overrides are retired: crops.json now carries the authoritative 13-group
// taxonomy (e.g. Sweet Potato (Orange)→Red/Orange Veg, Chestnut→Nuts & Seeds,
// Olive (Table)→Other Vegetables). effectiveFoodGroup trusts the data directly.
function effectiveFoodGroup(crop){
  return crop.food_group;
}

// ── Suitability — simple boolean: CLIZ + TEXTR must match ──────────────
// Temperature suitability — hard gate alongside cliz/soil/rainfall in isSuitable.
// Reads the active location's monthly temps (set from CLIMATE_DB by selectTown).
// Returns true when temps are missing ("Other") so temperature never over-excludes.
// frost_hardy perennials (deciduous / winter-dormant / cold-hardy evergreens) skip the
// active-tissue frost-kill test — they overwinter below their ktmp; growing-season warmth
// (tmin) still gates them out of places too cold to fruit.
function tempSuitable(crop){
  const tmaxA = state.climateTmax, tminA = state.climateTmin, extA = state.climateTminext;
  if(!tmaxA || !tminA || !extA) return true;              // no temp data -> don't gate
  const ktmp = crop.ktmp, ctmin = crop.tmin, ctmax = crop.tmax;
  const meanT = tmaxA.map((tx,i) => (tx + tminA[i]) / 2); // monthly mean temp
  if(crop.perennial){
    if(!crop.frost_hardy && ktmp != null && Math.min(...extA) < ktmp) return false; // frost-killed -> EXCLUDE
    if(ctmin != null && Math.max(...meanT) < ctmin) return false; // never warm enough
    if(ctmax != null && Math.min(...meanT) > ctmax) return false; // never cool enough
    return true;
  } else {                                                 // annual: needs >=1 viable month
    for(let i=0;i<12;i++){
      const frostOk = (ktmp == null) || (extA[i] >= ktmp);
      const warmOk  = (ctmin == null || meanT[i] >= ctmin) && (ctmax == null || meanT[i] <= ctmax);
      if(frostOk && warmOk) return true;
    }
    return false;
  }
}

function isSuitable(crop){
  const userZone = state.climateZone;
  const userTex  = state.soilTexture;
  // Both fields required — crops with no CLIZ or no TEXTR data are excluded
  const cropZones = crop.cliz || [];
  if(!cropZones.length) return false;
  if(!cropZones.includes(userZone)) return false;
  const cropTex = crop.text_tol || [];
  if(!cropTex.length) return false;
  if(userTex === "wide"){
    // user has variable soil — accept any crop with texture data
  } else {
    if(!cropTex.includes(userTex) && !cropTex.includes("wide")) return false;
  }
  // Rainfall suitability check
  const rain = state.annualRainfall || 0;
  const rMin = crop.rain_min || 0;
  const rMax = crop.rain_max || 99999;
  if(canIrrigate(state)){
    // With irrigation: deficits can be supplemented; only penalise excess rain
    // (waterlogging / disease from too much rainfall can't be irrigated away)
    if(rain > rMax * 1.25) return false;
  } else {
    if(rain < rMin || rain > rMax) return false;
  }
  // Temperature suitability (frost-kill / absolute warm-cool range)
  if(!tempSuitable(crop)) return false;
  return true;
}

function plantCount(crop, allocHa){
  const w = crop.w_max;
  if(!w || w <= 0) return {label:"—", note:""};
  const areaSqm = allocHa * 10000;
  // Use w_max as centre-to-centre spacing; plant footprint = w × w
  // For broadcast/drill-sown crops (grains, small seeds, onion spring) show row metres instead
  if(BROADCAST_CROPS.has(crop.name)){
    // Express as row metres (rows 30cm apart for fine grain, 50cm for large)
    const rowSpacing = w <= 0.3 ? 0.3 : 0.5;
    const rowMetres = Math.round(areaSqm / rowSpacing);
    return{label: rowMetres.toLocaleString()+" m of rows", note:`${rowSpacing*100}cm row spacing`};
  }
  // Individual plant count
  const spacing = w; // centre-to-centre = mature spread width
  // For perennial crops always show at least 1 plant (they are individually planted and never zero)
  const rawCount = Math.round(areaSqm / (spacing * spacing));
  const plants = crop.perennial ? Math.max(1, rawCount) : rawCount;
  const plural = plants === 1;
  // Label by perennial layer for perennials (canopy/trees/plants); by width for annuals.
  let typeLabel;
  if(crop.perennial){
    const layer = cropLayer(crop);
    if(layer === "canopy")      typeLabel = plural ? "large tree" : "large trees";
    else if(layer === "trees")  typeLabel = plural ? "tree" : "trees";
    else                        typeLabel = "plants/shrubs";
  } else {
    typeLabel = "plants";
    if(w >= 5) typeLabel = "trees";
    else if(w >= 2) typeLabel = "trees/shrubs";
    else if(w >= 1) typeLabel = "plants/shrubs";
  }
  const spacingLabel = spacing >= 1 ? spacing.toFixed(1)+"m" : Math.round(spacing*100)+"cm";
  return{label: plants.toLocaleString()+" "+typeLabel, note:spacingLabel+" spacing"};
}

// ── Step renderers ─────────────────────────────────────────
// ── Vertical layering (food-forest stacking) ─────────────────────────────
// Layers can co-locate on the same ground — total perennial footprint is the
// MAX area across layers, not the sum.
function cropLayer(crop){
  const h = (crop && crop.h_max) || 0;
  if(h >= 25) return "canopy";    // ≥25m — overstory nut/tropical trees
  if(h >= 4)  return "trees";     // 4–24m — typical orchard fruit trees
  return "plants";                 // <4m — shrubs, vines, annuals
}
const LAYER_LABELS = {canopy:"Canopy (≥25m)", trees:"Trees (4–24m)", plants:"Shrubs (<4m)"};
const LAYER_COLORS = {canopy:"#3D5226", trees:"#5C7A3A", plants:"#8FAF60"};

// ── Planning objectives (3 toggles, on/off) ─────────────────────────────
const OBJECTIVES = [
  {key:"balanced",       label:"Balanced",         desc:"Seasonal variety, climate suitability. Stops at sufficiency."},
  {key:"minimiseLabour", label:"Minimise labour",  desc:"Maximises serves per labour-hour. Fewer crops, each dominant. Accepts more land."},
  {key:"maximiseYield",  label:"Maximise yield",   desc:"Fills all available land and labour. Pushes well past sufficiency."},
  {key:"minimiseSpace",  label:"Minimise space",   desc:"Maximises serves per m\u00b2. Fewest crops, densely allocated. Accepts more labour."},
  {key:"minimiseWater",  label:"Minimise irrigation", desc:"Maximises serves per litre of irrigation. Favours rain-fed and water-thrifty crops."},

];

function getObjMode(){
  // Returns the active objective key, or "balanced" if none active
  return Object.keys(state.objectives).find(k => state.objectives[k] === "on") || "balanced";
}

function renderObjGrid(){
  const active = getObjMode();
  return OBJECTIVES.map(o => {
    const isActive = o.key === active;
    return `<button class="obj-card ${isActive?'obj-active':''}" onclick="setObjective('${o.key}')">
      <div class="obj-label">${o.label}</div>
      <div class="obj-desc">${o.desc}</div>
    </button>`;
  }).join("");
}

function setObjective(key){
  // Radio behaviour: clicking active → balanced; clicking another → select it
  OBJECTIVES.forEach(o => { state.objectives[o.key] = "off"; });
  if(key !== "balanced") state.objectives[key] = "on";
  state.plan = null;
  renderApp();
}

function cycleObjective(key){ setObjective(key); } // backwards compat

function toggleExpandedCrop(name){
  state.expandedCrop = (state.expandedCrop === name) ? null : name;
  renderApp();
}

// Event delegation — attach once to the crop list container
document.addEventListener("click", function(e){
  const row = e.target.closest("[data-crop-expand]");
  if(row && !e.target.closest(".ncl-cb")){
    toggleExpandedCrop(row.dataset.cropExpand);
  }
  const cb = e.target.closest("[data-crop-toggle]");
  if(cb && e.target.tagName === "INPUT"){
    // handled by onchange inline
  }
});

function nutPillsHtml(nut){
  if(!nut) return "";
  const show = [["kcal","kcal"],["protein","protein"],["fat","fat"],["fiber","fibre"],
    ["vitC","vit C"],["ca","Ca"],["fe","Fe"],["vitA","vit A"],["vitD","vit D"],["b12","B12"]];
  return show.filter(([k]) => nut[k]!=null && nut[k]>0)
    .map(([k,l]) => `<span class="db-nut-pill">${l}: ${nut[k]}</span>`).join("");
}

function sortVisibleCrops(list){
  const s = state.cropSelSort || {col:"suit",dir:"desc"};
  const isMech = state.labourSystem === "mech";
  const arr = list.slice();
  if(s.col === "suit"){
    arr.sort((a,b)=>{ const sa=isSuitable(a)?1:0, sb=isSuitable(b)?1:0; return sb!==sa ? sb-sa : a.name.localeCompare(b.name); });
    return arr;
  }
  const val = c => s.col==="name" ? c.name.toLowerCase()
    : s.col==="yield" ? subsistYield(c,state.fertility,state.confidence)
    : s.col==="labour" ? cropLabour(c,isMech) : c.name.toLowerCase();
  arr.sort((a,b)=>{ const av=val(a), bv=val(b); const r = (typeof av==="string") ? av.localeCompare(bv) : av-bv; return s.dir==="desc" ? -r : r; });
  return arr;
}
function setCropSort(col){
  const s = state.cropSelSort || {col:"suit",dir:"desc"};
  if(s.col===col) s.dir = s.dir==="asc" ? "desc" : "asc";
  else { s.col = col; s.dir = col==="name" ? "asc" : "desc"; }
  state.cropSelSort = s;
  renderCropTable();
}

function buildCropList(crops){
  const MK = MONTHS, ML = MONTH_INITIALS;
  const isMech = state.labourSystem === "mech";
  const s = state.cropSelSort || {col:"suit",dir:"desc"};
  const arr = col => s.col===col ? (s.dir==="asc" ? " ▲" : " ▼") : "";
  const allChk = crops.length>0 && crops.every(c => state.checkedCrops.has(c.name));

  const head = `<thead><tr>
    <th class="rownum">#</th>
    <th class="center" style="width:30px"><input type="checkbox" ${allChk?"checked":""} title="Check / uncheck all visible crops" onclick="checkAll(this.checked)"/></th>
    <th class="sortable" onclick="setCropSort('name')">Common name${arr("name")}</th>
    <th>Species</th>
    <th>Group</th>
    <th class="num sortable" onclick="setCropSort('yield')">Yield <span class="th-unit">t·ha⁻¹</span>${arr("yield")}</th>
    <th class="num sortable" onclick="setCropSort('labour')">Labour <span class="th-unit">h·ha⁻¹</span>${arr("labour")}</th>
    <th class="center">Harvest</th>
    <th>Suitability</th>
    <th class="center">Type</th>
  </tr></thead>`;

  const body = crops.map((c,i) => {
    const checked = state.checkedCrops.has(c.name);
    const suit    = isSuitable(c);
    const fg      = effectiveFoodGroup(c);
    const latin   = c.latin || CROP_LATIN[c.name] || "";
    const safeTog = escJs(c.name);
    const yld     = subsistYield(c,state.fertility,state.confidence);
    const yldStr  = yld>0 ? yld.toFixed(1) : "—";
    const lab     = cropLabour(c,isMech);
    let swColor, swLabel;
    if(!suit){ swColor="#B5762F"; swLabel="Outside zone"; }
    else { if(cropPriorityTier(c)===2){ swColor="#5C7A3A"; swLabel="Ideal"; } else { swColor="#8FAF60"; swLabel="Suitable"; } }
    const dots = MK.map((m,k)=>{ const v=c.months?.[m]; const cls=v==="P"?"p":v==="S"?"s":""; return `<div class="db-card-m ${cls}" title="${ML[k]}"></div>`; }).join("");
    return `<tr class="${checked?"":"unchecked"}">
      <td class="rownum">${i+1}</td>
      <td class="center sel-cb"><input type="checkbox" ${checked?"checked":""} onchange="toggleCrop('${safeTog}');renderCropTable()" title="Include in farm plan"/></td>
      <td><span class="crop-sel-name" style="font-weight:700">${c.name}</span></td>
      <td class="sci-latin">${latin||"—"}</td>
      <td>${tag(fg)}</td>
      <td class="num">${yldStr}</td>
      <td class="num">${lab}</td>
      <td class="center"><div class="harv-bar">${dots}</div></td>
      <td class="suit-cell"><span class="suit-sw" style="background:${swColor}"></span>${swLabel}</td>
      <td class="center">${c.perennial?'<b class="type-p" title="Perennial">P</b>':'<span class="type-a" title="Annual">A</span>'}</td>
    </tr>`;
  }).join("");

  const empty = `<tr><td colspan="10" style="padding:16px;color:var(--text-mid)">No crops match this filter.</td></tr>`;
  return `<div style="overflow-x:auto"><table class="sel-table sci-cropgrid">${head}<tbody>${body||empty}</tbody></table></div>`;
}


function cropBase(){
  const m = state.minSuit || (state.showSuitableOnly===false ? "all" : "suitable");
  if(m==="ideal") return CROP_DATA.filter(c => cropPriorityTier(c)===2);
  if(m==="suitable") return CROP_DATA.filter(c => isSuitable(c));
  return CROP_DATA;
}
function setMinSuit(v){ state.minSuit=v; state.showSuitableOnly=(v!=="all"); state.plan=null; renderApp(); }

function renderCropTable(){
  ensureCheckedCrops();
  const base = cropBase();
  const allNames = base.map(c => c.name);
  const checkedCount = [...state.checkedCrops].filter(n => allNames.includes(n)).length;
  let visible = base;
  if(state.cropFilter !== "all" && state.cropFilter !== "__livestock__"){
    if(state.cropFilter === "Perennial") visible = base.filter(c => c.perennial);
    else if(state.cropFilter==="__cool__") visible=base.filter(c=>!c.perennial && getCropSeason(c)!=="warm");
    else if(state.cropFilter==="__warm__") visible=base.filter(c=>!c.perennial && getCropSeason(c)!=="cool");
    else visible = base.filter(c => effectiveFoodGroup(c) === state.cropFilter);
  }
  if(state.cropSearch && state.cropSearch.trim()){
    const q = state.cropSearch.toLowerCase().trim();
    visible = visible.filter(c =>
      c.name.toLowerCase().includes(q) ||
      (c.food_group||"").toLowerCase().includes(q) ||
      (c.cliz||[]).some(z => z.toLowerCase().includes(q))
    );
  }
  visible = sortVisibleCrops(visible);
  const pill = document.querySelector(".count-pill");
  if(pill) pill.textContent = checkedCount + " / " + base.length + " selected";
  const wrap = document.getElementById("cropListWrap");
  if(wrap) wrap.innerHTML = buildCropList(visible);
}


function setCropFilter(filter){
  state.cropFilter = filter;
  state.expandedCrop = null; // close any open card when switching filter
  renderApp();
}

function checkAll(check){
  ensureCheckedCrops();
  const base = cropBase();
  let visible = base;
  if(state.cropFilter !== "all"){
    if(state.cropFilter === "Perennial") visible = base.filter(c => c.perennial);
    else if(state.cropFilter==="__cool__") visible=base.filter(c=>!c.perennial && getCropSeason(c)!=="warm");
    else if(state.cropFilter==="__warm__") visible=base.filter(c=>!c.perennial && getCropSeason(c)!=="cool");
    else visible = base.filter(c => effectiveFoodGroup(c) === state.cropFilter);
  }
  if(state.cropSearch && state.cropSearch.trim()){
    const q = state.cropSearch.toLowerCase().trim();
    visible = visible.filter(c => c.name.toLowerCase().includes(q));
  }
  visible.forEach(c => {
    if(check) state.checkedCrops.add(c.name);
    else state.checkedCrops.delete(c.name);
  });
  state.plan = null;
  renderCropTable();
}

function toggleCrop(name){
  ensureCheckedCrops();
  if(state.checkedCrops.has(name)) state.checkedCrops.delete(name);
  else state.checkedCrops.add(name);
  state.plan = null;
  const base = cropBase();
  const checkedCount = [...state.checkedCrops].filter(n => base.some(c => c.name === n)).length;
  const pill = document.querySelector(".count-pill");
  if(pill) pill.textContent = checkedCount + " / " + base.length + " selected";
}

function renderStep1(){
  const totals = calcTotals(state.household);
  const members = state.household.map(m => {
    const a = ADG[m.type];
    return`<div class="member-row"><div style="flex:1;font-size:13px;font-weight:500">${a?.label||m.type}</div><button class="del-btn" onclick="removeMember(${m.id})">×</button></div>`;
  }).join("");
  const annual = state.hoursPerWeek * 52;
  const householdNRVs = state.household.length > 0 ? householdNRV(state.household) : {};
  const nrvOrder = ["kcal","protein","fat","fiber","ca","fe","mg","k","zn","vitA","vitC","vitE","b1","b2","b3","b6","folate"];
  // ── ADG dietary targets → horizontal bar graph (serves/day per food group) ──
  const fgList = FLOOR_KEYS.map(k => [FG_DISPLAY[k].label, k, FG_DISPLAY[k].color]);
  const adgMax = Math.max(1, ...fgList.map(([l,k]) => totals[k] || 0));
  // ── ADG dietary targets → donut of serve composition by the FIVE umbrella groups ──
  // Step 4 shows targets at the umbrella level (the five ADG groups the plan is built
  // around); sub-group detail lives on the Step 5 coverage rail instead.
  const adgSegs = umbrellaSum(totals)
    .map(u => ({ label:u.umb.label, val:u.total, color:u.umb.base }))
    .filter(s => s.val > 0.001);
  const adgTotal = adgSegs.reduce((s,d)=>s+d.val,0);
  const hcx=78,hcy=78,hRo=68,hRi=38; let hAng=-Math.PI/2;
  const adgSlices = adgTotal>0 ? adgSegs.map(d=>{
    const ang=(d.val/adgTotal)*Math.PI*2;
    const x1=hcx+hRo*Math.cos(hAng), y1=hcy+hRo*Math.sin(hAng);
    const x2=hcx+hRo*Math.cos(hAng+ang), y2=hcy+hRo*Math.sin(hAng+ang);
    const xi2=hcx+hRi*Math.cos(hAng+ang), yi2=hcy+hRi*Math.sin(hAng+ang);
    const xi1=hcx+hRi*Math.cos(hAng), yi1=hcy+hRi*Math.sin(hAng);
    const large=ang>Math.PI?1:0; hAng+=ang;
    return `<path d="M${x1.toFixed(1)} ${y1.toFixed(1)} A${hRo} ${hRo} 0 ${large} 1 ${x2.toFixed(1)} ${y2.toFixed(1)} L${xi2.toFixed(1)} ${yi2.toFixed(1)} A${hRi} ${hRi} 0 ${large} 0 ${xi1.toFixed(1)} ${yi1.toFixed(1)} Z" fill="${d.color}" stroke="var(--card)" stroke-width="1.5"/>`;
  }).join("") : `<circle cx="${hcx}" cy="${hcy}" r="${hRo}" fill="none" stroke="var(--border-dk)" stroke-width="1"/>`;
  const adgDonut = `<svg width="156" height="156" viewBox="0 0 156 156">${adgSlices}<text x="78" y="74" text-anchor="middle" font-size="20" font-weight="700" fill="var(--green-dk)" font-family="'Lucida Console',monospace">${adgTotal.toFixed(1)}</text><text x="78" y="92" text-anchor="middle" font-size="9" fill="var(--text-mid)">serves/day</text></svg>`;
  const adgLegend = adgSegs.map(d=>`<div class="donut-leg-row"><div class="donut-leg-swatch" style="background:${d.color}"></div><span>${d.label}</span><span class="donut-leg-pct">${d.val.toFixed(1)}</span></div>`).join("");
  // ── NRV → condensed two-column reference grid ──
  const nrvItems = state.household.length > 0 ? nrvOrder.filter(n => householdNRVs[n]).map(n => {
    const total = householdNRVs[n];
    const lbl = NUTRIENT_LABELS[n] || n;
    const unit = NUTRIENT_UNITS[n] || "";
    const val = total < 10 ? total.toFixed(1) : Math.round(total).toLocaleString();
    return `<div class="nrv-item"><span class="nrv-lbl">${lbl}</span><span class="nrv-val">${val}<span class="nrv-unit">${unit}</span></span></div>`;
  }).join("") : "";

  return`
    <div class="two-col" style="margin-bottom:14px;gap:14px">
      <div class="card" style="margin:0">
        <h2>Household members</h2>
        <p class="card-desc">Add each person. Targets are from the Australian Dietary Guidelines (2013).</p>
        ${members || '<p style="color:var(--text-mid);font-size:13px;padding:8px 0">No members added yet.</p>'}
        <hr/>
        <div class="field-row" style="margin-bottom:0">
          <select style="flex:1" onchange="state.newMemberType=this.value">${Object.entries(ADG).map(([k,v]) => `<option value="${k}" ${k===state.newMemberType?"selected":""}>${v.label}</option>`).join("")}</select>
          <button class="btn btn-sec" onclick="addMember()" style="white-space:nowrap">+ Add</button>
        </div>
      </div>
      <div class="card" style="margin:0">
        <h2>Annual labour budget</h2>
        <p class="card-desc">Total weekly farm hours across household members.</p>
        <div class="field-row">
          <span class="field-label">Hours per week</span>
          <input type="number" min="1" max="200" value="${state.hoursPerWeek}" style="width:90px" onchange="state.hoursPerWeek=Math.max(1,+this.value);state.plan=null;renderApp()"/>
          <span style="font-size:12px;color:var(--text-mid)">= <strong>${annual.toLocaleString()}</strong> hrs/year</span>
        </div>
        <div class="field-row">
          <span class="field-label">Labour system</span>
          <select onchange="state.labourSystem=this.value;state.plan=null">
            <option value="hand" ${state.labourSystem==="hand"?"selected":""}>Manual / smallholder (hand tools)</option>
            <option value="mech" ${state.labourSystem==="mech"?"selected":""}>Mechanised (tractor-assisted)</option>
          </select>
        </div>
        <div class="alert alert-info" style="font-size:11px">Manual systems use <strong>10–20× more labour per hectare</strong> than mechanised.</div>
      </div>
    </div>
    ${state.household.length > 0 ? `
    <div class="two-col" style="margin-top:0;gap:14px;align-items:start">
      <div class="card" style="margin:0">
        <h2>Household dietary targets</h2>
        <p class="card-desc">${state.household.length} member${state.household.length!==1?"s":""} · Combined ADG recommended daily serves</p>
        <div class="donut-wrap" style="margin-top:6px;gap:16px;justify-content:flex-start">
          ${adgDonut}
          <div class="donut-legend" style="min-width:150px">${adgLegend}</div>
        </div>
        ${(()=>{
          const lsDairy = calcLivestockAchieved().dairy || 0;
          if((totals.dairy||0) <= 0) return "";
          if(lsDairy >= (totals.dairy||0) - 0.05)
            return `<div class="alert alert-success" style="margin-top:10px"><strong>✓ Dairy covered by livestock</strong> — ${lsDairy.toFixed(1)} srv/day from goats meets the ${totals.dairy.toFixed(1)} srv/day target.</div>`;
          if(lsDairy > 0)
            return `<div class="alert alert-dairy" style="margin-top:10px"><strong>Note on dairy:</strong> ${totals.dairy.toFixed(1)} srv/day needed — livestock currently covers ${lsDairy.toFixed(1)} srv/day. Add more goats or source the rest externally.</div>`;
          return `<div class="alert alert-dairy" style="margin-top:10px"><strong>Note on dairy:</strong> ${totals.dairy.toFixed(1)} srv/day needed — not producible from crops. Add goats in Crop Selection or source externally.</div>`;
        })()}
      </div>
      <div class="card" style="margin:0">
        <h2>Nutrient reference values</h2>
        <p class="card-desc">Combined daily intake needed across all members — NHMRC NRV for the demographic mix.</p>
        <div class="nrv-grid">${nrvItems}</div>
      </div>
    </div>` : ""}
    <div class="nav-row"><div></div><button class="btn btn-lg" onclick="goStep(1)" ${state.household.length===0?"disabled":""}>Farm details →</button></div>`;
}
function renderStep2(){
  const zoneOpts = ZONES.map(z => `<option value="${z.id}" ${state.climateZone===z.id?"selected":""}>${z.code} — ${z.label}</option>`).join("");
  const TOWN_STATE_ORDER = ["WA","SA","NT","QLD","NSW","ACT","VIC","TAS"];
  const townOpts = TOWN_STATE_ORDER.map(st => {
    const inSt = TOWNS.filter(t => t.st === st);
    if(!inSt.length) return "";
    return `<optgroup label="${st}">` + inSt.map(t => `<option value="${t.n}" ${state.town===t.n?"selected":""}>${t.n}</option>`).join("") + `</optgroup>`;
  }).join("") + `<option value="Other" ${state.town==="Other"?"selected":""}>Other / enter coordinates…</option>`;
  const TEXTURES = [
    {id:"light",  label:"Light",   desc:"Sandy, loamy sand"},
    {id:"medium", label:"Medium",  desc:"Loam, silt loam"},
    {id:"heavy",  label:"Heavy",   desc:"Clay, clay loam"},
    {id:"organic",label:"Organic", desc:"Peat, muck, very high OM"},
    {id:"wide",   label:"Variable",desc:"Mixed across the property, or unsure"},
  ];
  const texOpts = TEXTURES.map(t => `<option value="${t.id}" ${state.soilTexture===t.id?"selected":""}>${t.label} — ${t.desc}</option>`).join("");
  const activeZone = ZONES.find(z => z.id===state.climateZone);

  return`
    <div class="two-col" style="gap:14px;align-items:start;margin-bottom:0">

    <div class="card" style="margin:0">
      <h2>Site conditions</h2>
      <p class="card-desc">Climate zone, soil type, and water availability. Determines which crops are suitable.</p>
      <div style="margin-bottom:12px">
        <label>Location (nearest town)</label>
        <select onchange="selectTown(this.value)" style="width:100%">${townOpts}</select>
        ${state.town==="Other" ? `
        <div style="display:flex;gap:8px;margin-top:6px">
          <input type="number" step="0.01" placeholder="lat (e.g. -31.95)" value="${state.lat}" onchange="state.lat=+this.value;state.plan=null;renderApp()" style="width:50%"/>
          <input type="number" step="0.01" placeholder="lon (e.g. 115.86)" value="${state.lon}" onchange="state.lon=+this.value;state.plan=null;renderApp()" style="width:50%"/>
        </div>` : `<div style="font-size:11px;color:var(--text-mid);margin-top:3px">Pins ${state.lat}, ${state.lon} for climate data · sets the zone &amp; rainfall below (both editable)</div>`}
      </div>
      <div style="margin-bottom:12px">
        <label>Climate</label>
        <div style="font-size:11px;color:var(--text-mid)">${state.climateEto ? state.climateLabel + " normal &mdash; drives the irrigation &amp; dam estimates and temperature suitability." : "Bundled Perth normal (a custom location has no baked climate)."}</div>
      </div>
      <div style="margin-bottom:12px">
        <label>Climate zone (Köppen)</label>
        <select onchange="state.climateZone=this.value;state.checkedCrops=null;state.plan=null;renderApp()" style="width:100%">${zoneOpts}</select>
        ${activeZone?`<div style="font-size:11px;color:var(--text-mid);margin-top:3px">${activeZone.sub}</div>`:""}
      </div>
      <div style="margin-bottom:12px">
        <label>Soil texture</label>
        <select onchange="state.soilTexture=this.value;state.checkedCrops=null;state.plan=null;renderApp()" style="width:100%">${texOpts}</select>
      </div>
      <div style="margin-bottom:12px">
        <label>Annual rainfall (mm)</label>
        <input type="number" min="0" max="5000" step="50" value="${state.annualRainfall}" oninput="state.annualRainfall=+this.value;state.checkedCrops=null;state.plan=null;renderApp()" style="width:100px"/>
      </div>
      <div style="margin-bottom:12px">
        <label>Scheme / bore water</label>
        <select onchange="state.waterSource=this.value;state.checkedCrops=null;state.plan=null;renderApp()" style="width:100%">
          <option value="unlimited" ${state.waterSource==="unlimited"?"selected":""}>Yes — unlimited (mains / bore)</option>
          <option value="limited" ${state.waterSource==="limited"?"selected":""}>Yes — limited (minimise irrigation)</option>
          <option value="rainfed" ${state.waterSource==="rainfed"?"selected":""}>No — rainfed (+ optional dam)</option>
        </select>
        ${state.waterSource==="rainfed"
          ? (state.irrigationDam
              ? '<div style="font-size:11px;color:var(--green-dk);margin-top:3px">✓ Rainfed — crops irrigated from the dam you size below; rainfall constraints softened.</div>'
              : '<div style="font-size:11px;color:var(--text-mid);margin-top:3px">Strict rainfed: crops must survive on rainfall alone. Turn on the dam below to irrigate from stored rain.</div>')
          : (state.waterSource==="limited"
              ? '<div style="font-size:11px;color:var(--green-dk);margin-top:3px">✓ Irrigation active, limited — the Balanced planner steers toward water-thrifty crops.</div>'
              : '<div style="font-size:11px;color:var(--green-dk);margin-top:3px">✓ Irrigation active — minimum rainfall constraints softened.</div>')}
      </div>
      <div style="margin-bottom:12px">
        <label>Soil fertility</label>
        <select onchange="state.fertility=this.value;state.plan=null" style="width:100%">
          <option value="low"    ${state.fertility==="low"   ?"selected":""}>Low — poor / depleted</option>
          <option value="medium" ${state.fertility==="medium"?"selected":""}>Medium — average</option>
          <option value="high"   ${state.fertility==="high"  ?"selected":""}>High — rich / improved</option>
        </select>
      </div>
      <div>
        <label>Yield confidence — ${state.confidence}%</label>
        <input type="range" min="20" max="100" step="5" value="${state.confidence}" oninput="state.confidence=+this.value;state.plan=null;this.previousElementSibling.textContent='Yield confidence — '+this.value+'%'" style="width:100%"/>
        <div style="font-size:11px;color:var(--text-mid);margin-top:2px">60% recommended for first-year plans.</div>
      </div>
    </div>

    <div class="card" style="margin:0">
      <h2>Land availability</h2>
      <p class="card-desc">How much land you have in each category. Controls how the algorithm allocates crops and livestock.</p>
      <div style="padding:9px 11px;background:var(--bg2);border:1px solid var(--border-lt);margin-bottom:12px">
        <label style="display:flex;align-items:flex-start;gap:8px;cursor:pointer;font-weight:normal">
          <input type="checkbox" ${state.landFixed!==false?"checked":""} style="margin-top:2px;flex-shrink:0"
            onchange="state.landFixed=this.checked;state.plan=null;renderApp()"/>
          <span style="flex:1;min-width:0">
            <strong style="font-size:12px">Fixed land allocation</strong>
            <span class="card-desc" style="display:block;margin-top:2px;text-transform:none;letter-spacing:normal">When ticked, the algorithm keeps crops within the area types below. When unticked, it draws freely from the combined total.</span>
          </span>
        </label>
      </div>
      <div style="margin-bottom:12px">
        <label>Annual crop area (ha)</label>
        <input type="number" min="0" step="0.05" value="${state.annualHa}" onchange="state.annualHa=+this.value;state.plan=null" style="width:100%"/>
        <div style="font-size:11px;color:var(--text-mid);margin-top:2px">Vegetables, grains, legumes</div>
      </div>
      <div style="margin-bottom:12px">
        <label>Perennial / orchard area (ha)</label>
        <input type="number" min="0" step="0.05" value="${state.perennialHa}" onchange="state.perennialHa=+this.value;state.plan=null" style="width:100%"/>
        <div style="font-size:11px;color:var(--text-mid);margin-top:2px">Trees, shrubs, food forest layers</div>
      </div>
      <div style="margin-bottom:12px">
        <label>Pasture area (ha)</label>
        <input type="number" min="0" step="0.05" value="${state.pastureHa||0}" onchange="state.pastureHa=+this.value;state.plan=null;renderApp()" style="width:100%"/>
        <div style="font-size:11px;color:var(--text-mid);margin-top:2px">Grazing — poultry, ruminants, pigs, bees</div>
      </div>
      <div style="margin-bottom:12px">
        <label style="display:flex;align-items:center;gap:8px;cursor:pointer">
          <input type="checkbox" ${state.irrigationDam?'checked':''} onchange="state.irrigationDam=this.checked;state.plan=null;renderApp()" style="width:auto;margin:0"/>
          Self-supplied irrigation (size a dam)
        </label>
        <div style="font-size:11px;color:var(--text-mid);margin-top:2px">Work out the irrigation water the plan needs across the year and size a storage dam; its surface also grows fish &amp; aquatic crops.</div>
      </div>
      ${state.irrigationDam ? `
      <div style="margin-bottom:12px">
        <label>Dam depth (m)</label>
        <input type="number" min="0.5" step="0.5" value="${state.damDepth||3}" onchange="state.damDepth=+this.value;state.plan=null;renderApp()" style="width:100%"/>
        <div style="font-size:11px;color:var(--text-mid);margin-top:2px">Average usable depth — converts storage volume to surface footprint</div>
      </div>` : `
      <div style="margin-bottom:12px">
        <label>Surface water area (ha)</label>
        <input type="number" min="0" step="0.01" value="${state.surfaceWaterHa||0}" onchange="state.surfaceWaterHa=+this.value;state.plan=null;renderApp()" style="width:100%"/>
        <div style="font-size:11px;color:var(--text-mid);margin-top:2px">Pond / dam / tank — fish and aquatic crops</div>
      </div>`}
    </div>

    </div>
    <div class="nav-row"><button class="btn btn-sec" onclick="goStep(0)">← Household</button><button class="btn btn-lg" onclick="goStep(2)">Crop selection →</button></div>`;
}
function renderLivestockSelectionPanel(){
  const checkedSet = state.checkedLivestock || new Set();
  let rows = "";
  LIVESTOCK_DATA.forEach(ls => {
    const checked = checkedSet.has(ls.name);
    const safeJs = escJs(ls.name);
    const outStr = (function(){
      const fg = ls.food_group === "Dairy" ? "dairy" : ls.food_group === "Discretionary" ? "discretionary" : fgToKey(ls.food_group) || "other";
      return (ls.edible_part || ls.name) + " (" + fg + ")";
    })();
    const labourLabel = ls.labour_hrs_per_animal + " hrs/" + ls.unit_label.split('/')[0] + "/yr";
    const spaceLabel = ls.space_m2_per_animal < 10
      ? ls.space_m2_per_animal + " m\u00b2/animal"
      : (ls.space_m2_per_animal/10000).toFixed(2) + " ha/animal";
    rows += '<tr class="' + (checked ? "" : "unchecked") + '">'
      + '<td class="center sel-cb"><input type="checkbox" ' + (checked ? "checked" : "") + ' onchange="toggleLivestock(\'' + safeJs + '\',this.checked)" title="Tick to make this species a candidate for the farm plan algorithm"/></td>'
      + '<td><strong style="font-size:12px">' + ls.name + '</strong>'
      + '<div style="font-size:10px;color:var(--text-mid);margin-top:2px">' + ls.notes.split('.')[0] + '.</div></td>'
      + '<td class="hide-sm" style="font-size:11px">' + ls.category + '</td>'
      + '<td class="hide-sm" style="font-size:11px;color:var(--text-mid)">' + outStr + '</td>'
      + '<td class="hide-sm" style="font-size:11px;color:var(--text-mid)">' + labourLabel + '</td>'
      + '<td class="hide-sm" style="font-size:11px;color:var(--text-mid)">' + spaceLabel + '</td>'
      + '</tr>';
  });
  return '<div class="card" style="border-left:6px solid #8B6914">'
    + '<h2>Livestock</h2>'
    + '<p class="card-desc">Tick species to make them <strong>candidates</strong> for the farm plan. The algorithm allocates livestock in parallel with crops, scored by serves per labour-hour. Fine-tune counts in the Adjust tab after planning. Set pasture / aquaculture area in Farm Settings.</p>'
    + '<div style="overflow-x:auto">'
    + '<table class="sel-table" style="min-width:480px">'
    + '<thead><tr>'
    + '<th class="center" style="width:36px">Include</th>'
    + '<th>Species</th>'
    + '<th class="hide-sm">Category</th>'
    + '<th class="hide-sm">Outputs</th>'
    + '<th class="hide-sm">Labour</th>'
    + '<th class="hide-sm">Space/animal</th>'
    + '</tr></thead>'
    + '<tbody>' + rows + '</tbody>'
    + '</table></div></div>';
}


function renderStep3(){
  ensureCheckedCrops();
  const base=cropBase();
  const allNames=base.map(c=>c.name);
  const checkedCount=[...state.checkedCrops].filter(n=>allNames.includes(n)).length;

  // Active filter chips
  const FG_STRINGS = Object.keys(FG_KEY); // crops.json food_group strings, in taxonomy order
  const filterGroups=["all", ...FG_STRINGS, "Perennial","__cool__","__warm__","__livestock__"];
  const filterLabels=Object.assign(
    {"all":"All","Perennial":"Perennial","__cool__":"Cool season","__warm__":"Warm season","__livestock__":"Livestock"},
    Object.fromEntries(FG_STRINGS.map(s => [s, FG_DISPLAY[FG_KEY[s]].label]))
  );

  // Filter and search
  let visible=base;
  if(state.cropFilter!=="all"){
    if(state.cropFilter==="Perennial") visible=base.filter(c=>c.perennial);
    else if(state.cropFilter==="__cool__") visible=base.filter(c=>!c.perennial && getCropSeason(c)!=="warm");
    else if(state.cropFilter==="__warm__") visible=base.filter(c=>!c.perennial && getCropSeason(c)!=="cool");
    else if(state.cropFilter==="__livestock__") visible=[];
    else visible=base.filter(c=>effectiveFoodGroup(c)===state.cropFilter);
  }
  if(state.cropSearch.trim()){
    const q=state.cropSearch.toLowerCase();
    visible=visible.filter(c=>c.name.toLowerCase().includes(q));
  }

  // Sort by current column (default: suitability then name)
  visible = sortVisibleCrops(visible);

  const rows=visible.map(crop=>{
    const checked=state.checkedCrops.has(crop.name);
    return`<tr class="${checked?"":"unchecked"}">
      <td class="center sel-cb"><input type="checkbox" ${checked?"checked":""} onchange="toggleCrop('${escJs(crop.name)}',this.checked)" title="Include in farm plan"/></td>
      <td><span class="crop-sel-name" style="font-weight:500;font-size:12px">${crop.name}</span></td>
      <td class="hide-sm">${tag(effectiveFoodGroup(crop))}</td>
      <td class="center hide-sm">${crop.perennial?'<span class="badge-perennial">Perennial</span>':'<span class="badge-annual">Annual</span>'}</td>
      <td class="center">${isSuitable(crop)?`<span class="suit-yes" title="Climate zone and soil texture match this crop">✓</span>`:`<span class="suit-no" title="Climate zone or soil texture does not match">✗</span>`}</td>
      <td class="hide-sm" style="font-size:11px;color:var(--text-mid)">${crop.storability||"—"}</td>
      <td class="hide-sm" style="min-width:96px">${monthBar(crop.months)}</td>
    </tr>`;
  }).join("");

  return`
    <div class="card">
      <h2>Crop selection</h2>
      <p class="card-desc">
        <strong>${CROP_DATA.filter(c=>isSuitable(c)).length}</strong> crops match your climate zone and soil texture.
        Check the crops you want considered in the farm plan. By default only suitable crops are shown — uncheck "Only show suitable" to see and select unsuitable ones too.
      </p>

      <!-- Toolbar -->
      <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:10px">
        <input id="cropSearchInput" class="search-box" type="text" placeholder="Search crops…" value="${state.cropSearch}" oninput="state.cropSearch=this.value;state.expandedCrop=null;state._focusField='cropSearchInput';clearTimeout(window.__cropSearchT);window.__cropSearchT=setTimeout(renderApp,160)" style="max-width:180px"/>
        <span class="count-pill">${checkedCount} / ${base.length} selected</span>
      </div>

      <!-- Query filter -->
      <div class="cropq-bar">
        <label class="cropq-lbl">Food group / filter</label>
        <select class="cropq-sel" onchange="setCropFilter(this.value)">
          <optgroup label="Food group">
            <option value="all" ${state.cropFilter==="all"?"selected":""}>All groups</option>
            ${FG_STRINGS.map(s=>`<option value="${s}" ${state.cropFilter===s?"selected":""}>${FG_DISPLAY[FG_KEY[s]].label}</option>`).join("")}
          </optgroup>
          <optgroup label="Season &amp; type">
            <option value="__warm__" ${state.cropFilter==="__warm__"?"selected":""}>Warm season</option>
            <option value="__cool__" ${state.cropFilter==="__cool__"?"selected":""}>Cool season</option>
            <option value="Perennial" ${state.cropFilter==="Perennial"?"selected":""}>Perennial</option>
          </optgroup>
          <optgroup label="Other">
            <option value="__livestock__" ${state.cropFilter==="__livestock__"?"selected":""}>Livestock</option>
          </optgroup>
        </select>
        <label class="cropq-lbl">Min. suitability</label>
        <select class="cropq-sel" onchange="setMinSuit(this.value)">
          <option value="all" ${(state.minSuit||(state.showSuitableOnly?'suitable':'all'))==='all'?'selected':''}>All crops</option>
          <option value="suitable" ${(state.minSuit||(state.showSuitableOnly?'suitable':'all'))==='suitable'?'selected':''}>Suitable only</option>
          <option value="ideal" ${(state.minSuit||(state.showSuitableOnly?'suitable':'all'))==='ideal'?'selected':''}>Ideal soil only</option>
        </select>
        <span class="cropq-hint">Sort by clicking the <strong>Common name</strong>, <strong>Yield</strong> or <strong>Labour</strong> column headers.</span>
      </div>

      <!-- Crop list / Livestock panel -->
      ${state.cropFilter==='__livestock__'
        ? renderLivestockSelectionPanel()
        : `<div id="cropListWrap">${buildCropList(visible)}</div>
          ${visible.length===0?'<div class="alert alert-warn" style="margin-top:8px">No crops match this filter.</div>':""}
        `}
    </div>

    <div class="nav-row">
      <button class="btn btn-sec" onclick="goStep(1)">← Farm details</button>
      <button class="btn btn-lg" onclick="goStep(5)" ${checkedCount===0?"disabled":""}>Generate farm plan →</button>
    </div>`;
}


// Sortable crop table view for the Farm Plan
function renderCropsTable(crops){
  const sort = state.tableSort || {col:"name",dir:"asc"};
  // Build rows with computed metrics
  const enriched = crops.map(s => {
    const adjY = subsistYield(s.crop, state.fertility, state.confidence);
    const kgYr = Math.round(s.allocHa * adjY * 1000);
    const pc = plantCount(s.crop, s.allocHa);
    // First harvest month: first "P" (primary) month, fallback to first "S" (shoulder)
    let firstIdx = 99, firstLabel = "—";
    for(let i = 0; i < MONTHS.length; i++){
      if(s.crop.months[MONTHS[i]] === "P"){ firstIdx = i+1; firstLabel = MONTHS[i]; break; }
    }
    if(firstIdx === 99){
      for(let i = 0; i < MONTHS.length; i++){
        if(s.crop.months[MONTHS[i]] === "S"){ firstIdx = i+1; firstLabel = MONTHS[i]; break; }
      }
    }
    const firstLabelCap = firstLabel === "—" ? "—" : firstLabel.charAt(0).toUpperCase() + firstLabel.slice(1);
    return {
      sel: s, adjY, kgYr, pc, firstIdx, firstLabelCap,
      name: s.crop.name,
      group: effectiveFoodGroup(s.crop),
      type: s.crop.perennial ? "Perennial" : "Annual",
      area: s.allocHa,
      yield: kgYr,
      serves: s.serves,
      months: firstIdx,
    };
  });
  // Sort
  const dir = sort.dir === "asc" ? 1 : -1;
  enriched.sort((a, b) => {
    const va = a[sort.col], vb = b[sort.col];
    if(typeof va === "number") return (va - vb) * dir;
    return String(va).localeCompare(String(vb)) * dir;
  });
  // Sort indicator
  const ind = (col) => sort.col === col ? (sort.dir === "asc" ? " ▲" : " ▼") : "";
  const th = (col, label) => `<th style="padding:8px;text-align:left;background:var(--oat);border-bottom:2px solid var(--border-dk);cursor:pointer;user-select:none;font-size:11px;text-transform:uppercase;color:var(--text)" onclick="sortCropsTable('${col}')">${label}${ind(col)}</th>`;

  return `<table style="width:100%;border-collapse:collapse;font-size:13px;margin-top:8px">
    <thead><tr>
      ${th("name","Crop")}
      ${th("group","Group")}
      ${th("type","Type")}
      ${th("area","Area")}
      ${th("yield","kg/yr")}
      ${th("serves","Serves/day")}
      ${th("months","First harvest")}
    </tr></thead>
    <tbody>
      ${enriched.map(r => `<tr style="border-bottom:1px solid var(--border)">
        <td style="padding:6px 8px"><strong>${r.name}</strong> <span style="color:var(--text-mid);font-size:11px">(${r.pc.label})</span></td>
        <td style="padding:6px 8px">${tag(r.group)}</td>
        <td style="padding:6px 8px;font-size:11px">${r.type}</td>
        <td style="padding:6px 8px;text-align:right">${fmtHa(r.area)}</td>
        <td style="padding:6px 8px;text-align:right;font-weight:600">${r.yield.toLocaleString()}</td>
        <td style="padding:6px 8px;text-align:right">${r.serves.toFixed(1)}</td>
        <td style="padding:6px 8px"><span style="display:inline-block;min-width:40px;text-align:center;font-weight:600">${r.firstLabelCap}</span> ${monthBar(r.sel.crop.months)}</td>
      </tr>`).join("")}
    </tbody>
  </table>`;
}

function sortCropsTable(col){
  const cur = state.tableSort || {col:"name",dir:"asc"};
  if(cur.col === col) state.tableSort = {col, dir: cur.dir === "asc" ? "desc" : "asc"};
  else state.tableSort = {col, dir: col === "name" || col === "group" || col === "type" || col === "months" ? "asc" : "desc"};
  renderApp();
}

function renderStep4(){
  // Generate plan if not cached. Use LP solver if nutrient-LP mode is active.
  if(!state.plan){
    state.plan = generatePlan(state);
    // Stage-6 step 1: once the nutrition plan exists, site its crops onto the real
    // per-facet areas (only when a Site Model is present). Never alters the plan's
    // crop quantities — placement is strictly downstream of allocation.
    if(state.plan && state.siteModel){
      state.plan.placement = placeCropsOnFacets(state.plan, state.siteModel, state);
    }
  }
  const p = state.plan;

  // Planning objectives panel
  const objPanel = `<div class="card" style="margin-bottom:14px">
    <h2 style="margin-bottom:10px">Planning objective</h2>
    <div class="obj-regen-wrap">
      <div class="obj-grid" style="flex:1">${renderObjGrid()}</div>
      <button style="min-width:110px;padding:0 16px;font-size:13px;font-weight:700;cursor:pointer;
        background:var(--green);color:var(--card);border:none;
        border-top:2px solid var(--green-lt);border-left:2px solid var(--green-lt);
        border-right:2px solid var(--green-dk);border-bottom:2px solid var(--green-dk);
        box-shadow:var(--px-shadow-sm);line-height:1.2;font-family:inherit;
        display:flex;align-items:center;justify-content:center;gap:8px"
        onclick="state.plan=null;renderApp()"><span style="text-align:left">Regenerate<br>plan</span><svg width="17" height="17" viewBox="0 0 16 16" style="flex:none"><path d="M13.3 8a5.3 5.3 0 1 1-1.5-3.7" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/><path d="M13.7 2.4v3.2h-3.2" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg></button>
    </div>
  </div>`;
  const planTab = state.planTab || "crops";
  const planSubtabs = `<div class="plan-subtabs">${[["crops","Crops & Livestock"],["overview","Overview"]].map(([id,lbl])=>`<div class="plan-subtab ${planTab===id?"active":""}" onclick="setPlanTab('${id}')">${lbl}</div>`).join("")}</div>`;

  // Plan summary
  const totals = calcTotals(state.household);
  const fmtAch = (k) => {
    const t = totals[k] || 0;
    // p.achieved already includes livestock serves (allocators credit them), so no extra fold-in.
    const a = (p.achieved[k] || 0);
    const pct = t > 0 ? Math.round(100 * a / t) : 0;
    const lbl = (FG_DISPLAY[k]||{}).label || k;
    return `<div class="adg-row">
      <span class="adg-lbl">${lbl}</span>
      <div class="adg-track"><div class="adg-fill" style="width:${Math.min(100,pct)}%;background:${FG_BAR[k]}"></div></div>
      <span class="adg-val">${t > 0 ? pct + "%" : "n/a"}</span>
    </div>`;
  };

  const dairyLsServes = (calcLivestockAchieved(p.lsSelected).dairy || 0);
  const dairyNet = (totals.dairy || 0) - dairyLsServes;
  const dairyAlert = totals.dairy > 0 ? (dairyNet > 0.05
    ? `<div class="alert alert-warn" style="margin-top:10px"><strong>Dairy gap:</strong> ${dairyNet.toFixed(1)} serves/day still needed. Livestock covers ${dairyLsServes.toFixed(1)} srv/day — add more goats or source externally.</div>`
    : `<div class="alert alert-success" style="margin-top:10px"><strong>✓ Dairy covered</strong> — livestock provides ${dairyLsServes.toFixed(1)} srv/day vs ${totals.dairy.toFixed(1)} target.</div>`)
    : "";

  const allAchieved = ['veg','fruit','starchy','protein','oils'].every(k => (p.achieved[k]||0) >= (totals[k]||0) - 0.1);
  const coverageAlert = allAchieved ?
    `<div class="alert alert-success"><strong>Good coverage</strong> across key food groups. Check the monthly chart for seasonal gaps.</div>` :
    `<div class="alert alert-warn"><strong>Coverage gap</strong> — some food groups are below 100% of household target.</div>`;

  // Crop list — group annual vs perennial
  const coolAnnuals = p.selected.filter(s => !s.crop.perennial && getCropSeason(s.crop) !== "warm");
  const warmAnnuals = p.selected.filter(s => !s.crop.perennial && getCropSeason(s.crop) !== "cool");
  const perennials = p.selected.filter(s => s.crop.perennial);
  const renderCropRow = (s) => {
    const adjY = subsistYield(s.crop, state.fertility, state.confidence);
    const kgYr = Math.round(s.allocHa * adjY * 1000);
    const pc = plantCount(s.crop, s.allocHa);
    return `<div class="crop-row" style="padding:8px 12px;border-bottom:1px solid var(--border);display:grid;grid-template-columns:160px 70px 70px 110px 90px 90px 1fr;gap:10px;align-items:center;font-size:13px">
      <div><strong>${s.crop.name}</strong></div>
      <div>${tag(effectiveFoodGroup(s.crop))}</div>
      <div class="area-badge" style="text-align:center">${fmtHa(s.allocHa)}</div>
      <div style="font-size:12px;color:var(--text)"><strong>${pc.label}</strong></div>
      <div class="yield-badge" style="text-align:center">${kgYr} kg/yr</div>
      <div style="color:var(--text-mid);font-size:12px">${s.serves.toFixed(1)} srv/day</div>
      <div>${monthBar(s.crop.months)}</div>
    </div>`;
  };

  return objPanel + `
    ${planSubtabs}
    <div class="plan-panes" data-active="${planTab}">
    <div class="plan-pane" data-pane="overview">
    <div class="card" style="margin-top:14px">
      <div class="plan-hero">
        <h2 style="font-style:italic">Your farm plan</h2>
        ${(()=>{
          const mode = getObjMode();
          const modeObj = OBJECTIVES.find(o => o.key === mode) || OBJECTIVES[0];
          const bg = "var(--clay)";
          const fg = "var(--text)";
          return `<div style="margin:6px 0 4px 0">
            <span style="display:inline-block;background:${bg};color:${fg};font-size:11px;font-weight:700;letter-spacing:0.5px;text-transform:uppercase;padding:3px 9px;border:1px solid var(--border-dk)">Mode: ${modeObj.label}</span>
            <span style="font-size:11px;color:#D6E1BD;margin-left:8px;font-style:italic">${modeObj.desc}</span>
          </div>`;
        })()}
        <div class="plan-meta">${(ZONES.find(z=>z.id===state.climateZone)||{label:state.climateZone}).label} · ${state.soilTexture} soil · ${state.annualRainfall} mm/yr · ${state.fertility} fertility · ${state.hoursPerWeek} hrs/week · ${state.confidence}% confidence · ${p.suitableCount} crops enabled</div>
      </div>
      ${(()=>{
        // Compute total plant count for crops measured in individuals (not metres of row)
        let totalPlants = 0;
        let totalRowM = 0;
        p.selected.forEach(s => {
          const pc = plantCount(s.crop, s.allocHa);
          const m = pc.label.match(/^([\d,]+)\s+(plants|trees|trees\/shrubs|plants\/shrubs)$/);
          const mRow = pc.label.match(/^([\d,]+)\s+m of rows$/);
          if(m) totalPlants += parseInt(m[1].replace(/,/g,""));
          if(mRow) totalRowM += parseInt(mRow[1].replace(/,/g,""));
        });
        const plantsLabel = totalPlants > 0 ? totalPlants.toLocaleString() : "—";
        const planBudBar = (used, max, color) => {
          const pct = max > 0 ? used / max * 100 : 0;
          const fillCls = pct > 100 ? "over" : pct > 80 ? "warn" : "";
          const fillColor = color ? `background:${color}` : "";
          return `<div class="adj-layer-bar"><div class="adj-layer-fill ${fillCls}" style="width:${Math.min(100,pct)}%;${fillColor}"></div></div>`;
        };
        const pLayerDefs = [
          {key:"canopy", label:"Canopy ≥25m", color: LAYER_COLORS.canopy},
          {key:"trees",  label:"Trees 4–24m",  color: LAYER_COLORS.trees},
          {key:"plants", label:"Shrubs  <4m",  color: LAYER_COLORS.plants},
        ];
        const pLayers = p.layers || {canopy:0, trees:0, plants:0};
        const pBud = state.perennialHa;
        const budgetBar = state.landFixed === false ? `<div style="background:var(--card2);border:1px solid var(--border-dk);padding:10px 12px;margin-top:0">
          <div class="adj-bud-section-hdr" style="margin-bottom:7px">Land allocation — fluid pool</div>
          ${landCompositionFigure(state, p)}
          ${(()=>{
            const pl = p.layers || {canopy:0, trees:0, plants:0};
            const footprint = Math.max(pl.canopy||0, pl.trees||0, pl.plants||0);
            if(footprint < 0.00005) return "";
            return `<div class="adj-bud-section" style="margin-top:11px">
              <div class="adj-bud-section-hdr">Perennial layers · ${fmtHa(footprint)} footprint (layers stack)</div>
              ${pLayerDefs.map(({key,label,color}) => {
                const used = pl[key]||0;
                return `<div class="adj-layer-row">
                  <span class="adj-layer-lbl" style="color:${color}">${label}</span>
                  <span class="adj-layer-val">${fmtHa(used)}</span>
                  ${planBudBar(used, footprint, color)}
                </div>`;
              }).join("")}
            </div>`;
          })()}
          <div class="adj-bud-section" style="margin-top:11px">
            <div class="adj-bud-section-hdr">Labour · ${(state.hoursPerWeek*52).toLocaleString()} hrs/yr budget</div>
            <div class="adj-layer-row">
              <span class="adj-layer-lbl">⏱ Used</span>
              <span class="adj-layer-val">${Math.round(p.usedLabour)}</span>
              ${planBudBar(p.usedLabour, state.hoursPerWeek*52, "#5C7A3A")}
            </div>
          </div>
        </div>` : `<div style="background:var(--card2);border:1px solid var(--border-dk);padding:8px 12px;margin-top:0">
          <div class="adj-bud-arearow" style="gap:12px 20px">
            <div class="adj-bud-section" style="flex-basis:100%">
              <div class="adj-bud-section-hdr">Labour · ${(state.hoursPerWeek*52).toLocaleString()} hrs/yr budget</div>
              <div class="adj-layer-row">
                <span class="adj-layer-lbl">⏱ Used</span>
                <span class="adj-layer-val">${Math.round(p.usedLabour)}</span>
                ${planBudBar(p.usedLabour, state.hoursPerWeek*52, "#5C7A3A")}
              </div>
            </div>
            <div class="adj-bud-section">
              <div class="adj-bud-section-hdr">Annual beds · ${fmtHa(state.annualHa)}/season</div>
              <div class="adj-layer-row">
                <span class="adj-layer-lbl">Cool</span>
                <span class="adj-layer-val">${fmtHa(p.usedCoolHa||0)}</span>
                ${planBudBar(p.usedCoolHa||0, state.annualHa, "#4A7C8A")}
              </div>
              <div class="adj-layer-row">
                <span class="adj-layer-lbl">Warm</span>
                <span class="adj-layer-val">${fmtHa(p.usedWarmHa||0)}</span>
                ${planBudBar(p.usedWarmHa||0, state.annualHa, "#8A6A2E")}
              </div>
            </div>
            <div class="adj-bud-section">
              <div class="adj-bud-section-hdr">Perennial · ${fmtHa(pBud)} (layers stack)</div>
              ${pLayerDefs.map(({key,label,color}) => {
                const used = pLayers[key]||0;
                return `<div class="adj-layer-row">
                  <span class="adj-layer-lbl" style="color:${color}">${label}</span>
                  <span class="adj-layer-val">${fmtHa(used)}</span>
                  ${planBudBar(used, pBud, color)}
                </div>`;
              }).join("")}
            </div>
            ${(state.pastureHa||0) > 0 ? `<div class="adj-bud-section" style="min-width:130px">
              <div class="adj-bud-section-hdr">Pasture / water</div>
              <div class="adj-layer-row">
                <span class="adj-layer-lbl">Livestock</span>
                <span class="adj-layer-val">${fmtHa(p.usedPastureHa||0)}</span>
                ${planBudBar(p.usedPastureHa||0, state.pastureHa, "#8C4A2A")}
              </div>
            </div>` : ""}
          </div>
        </div>`;
        return `
          <fieldset class="plan-stats plan-stats-bottom" style="margin-top:14px">
            <legend>Plan Statistics</legend>
            <div class="plan-readout plan-readout-wide">
              <div class="pr-row"><span class="pr-k">Crops in plan</span><span class="pr-dots"></span><span class="pr-v">${p.selected.length}</span></div>
              ${Object.values(state.livestock||{}).some(v=>v>0) ? `<div class="pr-row"><span class="pr-k">Livestock spp.</span><span class="pr-dots"></span><span class="pr-v">${LIVESTOCK_DATA.filter(l=>(state.livestock||{})[l.name]>0).length}</span></div>` : ""}
              <div class="pr-row"><span class="pr-k">Individual plants</span><span class="pr-dots"></span><span class="pr-v">${plantsLabel}</span></div>
              <div class="pr-row"><span class="pr-k">Effective ha used</span><span class="pr-dots"></span><span class="pr-v">${(p.usedAnnualHa+p.usedPerennialHa).toFixed(3)}<span class="u">ha</span></span></div>
              <div class="pr-row"><span class="pr-k">Labour</span><span class="pr-dots"></span><span class="pr-v">${(p.usedLabour/1000).toFixed(1)}k<span class="u">hr/yr</span></span></div>
            </div>
          </fieldset>
          <div class="sci-figrow" style="margin-top:14px">
            <fieldset class="sci-fig">
              <legend>Nutrition Coverage</legend>
              <div class="sci-fig-inner">
                <div class="adg-plot" style="--grid:25%;margin:0">
                  ${FLOOR_KEYS.map(fmtAch).join("")}
                  <div class="adg-axis"><span class="adg-axis-pad"></span><div class="adg-ticks"><span>0</span><span>25</span><span>50</span><span>75</span><span>100</span></div><span class="adg-axis-pad"></span></div>
                  <div class="adg-cap">% of daily ADG target serves</div>
                </div>
              </div>
              <p class="card-desc" style="margin-top:8px">Daily serves achieved as a share of household ADG targets, by food group.</p>
            </fieldset>
            <fieldset class="sci-fig">
              <legend>Nutrient Reference Values (NRV)</legend>
              <div class="sci-fig-inner">
                ${nrvFigure(state, p)}
              </div>
              <p class="card-desc" style="margin-top:8px">Annual nutrient production vs household NRV requirements. Bars cap at 100%; values show produced / needed per year.</p>
            </fieldset>
          </div>
          <fieldset class="sci-fig" style="margin-top:14px">
            <legend>Land Allocation</legend>
            <div class="sci-fig-inner">
              ${landCompositionFigure(state, p)}
            </div>
            <p class="card-desc" style="margin-top:8px">${state.landFixed===false?"Fluid pool — algorithm draws crops, livestock and aquaculture freely across the total holding.":"Fixed allocation — each land type is capped at its configured area."}</p>
          </fieldset>
          <fieldset class="sci-fig" style="margin-top:14px">
            <legend>Labour by Task</legend>
            <div class="sci-fig-inner">${labourTaskFigure(state, p)}</div>
            <p class="card-desc" style="margin-top:8px">Estimated annual hours split across the main farm tasks — tending annual beds, perennial plantings and animal care — against your ${(state.hoursPerWeek*52).toLocaleString()}-hour household labour budget.</p>
          </fieldset>
        `;
      })()}
      ${(p.p15NutsCovered||[]).length > 0 ? `<div class="alert alert-success" style="margin-top:8px">
        <strong>Nutrient optimisation (Phase 1.5):</strong> The planner added or topped up crops targeting
        <strong>${(p.p15NutsCovered||[]).join(", ")}</strong> — nutrients that were below 85% of household NRV
        after food-group sufficiency was met. Check the Nutrient analysis in the Adjust tab to see coverage.
      </div>` : (p.p15GapNamesAll||[]).length > 0 ? `<div class="alert alert-warn" style="margin-top:8px">
        <strong>Nutrient gaps remain:</strong> <strong>${(p.p15GapNamesAll||[]).join(", ")}</strong> are below 85% of NRV,
        but land and labour budgets were fully used by Phase 1. To address these gaps, increase your annual or perennial land area,
        or add livestock for nutrients like B12, iron, and zinc.
      </div>` : ""}
    </div>
    </div>
    <div class="plan-pane" data-pane="overview">

    <div class="plan-cov-cols" style="display:grid;grid-template-columns:1fr;gap:14px;align-items:start;margin-top:14px">
    <div class="card" style="margin:0">
      <h2>Monthly food availability</h2>
      <p class="card-desc">% of daily ADG target covered each month from fresh harvest. Storage extends actual availability beyond what's shown here for storable crops (grains, legumes, nuts, roots).</p>
      <div style="display:flex;gap:14px;font-size:11px;margin-bottom:8px;align-items:center">
        <span style="color:var(--text-mid)">Coverage:</span>
        <span style="background:var(--green);color:var(--card);padding:2px 8px;font-weight:600">≥80%</span>
        <span style="background:#E6D89B;color:var(--text);padding:2px 8px;font-weight:600">50–79%</span>
        <span style="background:#E8B59C;color:#5C2C14;padding:2px 8px;font-weight:600">&lt;50%</span>
      </div>
      <table style="width:100%;border-collapse:collapse;font-size:12px">
        <thead>
          <tr style="border-bottom:2px solid var(--border-dk)">
            <th style="text-align:left;padding:4px 8px;width:90px">Group</th>
            ${MONTHS.map(m=>`<th style="padding:4px;text-transform:uppercase;font-size:10px;width:55px">${m.charAt(0).toUpperCase()}</th>`).join("")}
          </tr>
        </thead>
        <tbody>
          ${FG_DISPLAY_ROWS.map(([lbl,key,cls])=>{
            const target = totals[key] || 0;
            if(target <= 0) return "";
            const cells = MONTHS.map(m=>{
              const coverage = p.monthCoverage?.[m]?.[key] || 0;
              const pct = target > 0 ? Math.round(100 * coverage / target) : 0;
              let bg, fg;
              if(pct >= 80){bg="var(--green)"; fg="var(--card)";}
              else if(pct >= 50){bg="#E6D89B"; fg="var(--text)";}
              else if(pct > 0){bg="#E8B59C"; fg="#5C2C14";}
              else {bg="var(--card2)"; fg="var(--text-lt)";}
              return `<td style="padding:6px 4px;text-align:center;background:${bg};color:${fg};font-weight:600;border:1px solid var(--card)">${pct||"·"}${pct?"%":""}</td>`;
            }).join("");
            return `<tr><td style="padding:4px 8px;font-size:12px"><span class="tag ${cls}">${lbl}</span></td>${cells}</tr>`;
          }).join("")}
        </tbody>
      </table>
      ${(()=>{
        const gaps = [];
        PLANT_FRESH_KEYS.forEach(key => {
          const target = totals[key] || 0;
          if(target <= 0) return;
          const lbl = (FG_DISPLAY[key]||{}).label || key;
          MONTHS.forEach(m => {
            const coverage = p.monthCoverage?.[m]?.[key] || 0;
            const pct = target > 0 ? coverage / target : 0;
            if(pct < 0.5) gaps.push({m: m.charAt(0).toUpperCase()+m.slice(1), grp: lbl, pct: Math.round(pct*100)});
          });
        });
        if(!gaps.length) return `<div class="alert alert-success" style="margin-top:10px"><strong>Year-round fresh supply</strong> — every month has at least 50% coverage for all fresh food groups.</div>`;
        const byGrp = {};
        gaps.forEach(g => { (byGrp[g.grp]||(byGrp[g.grp]=[])).push(`${g.m} (${g.pct}%)`); });
        const lines = Object.entries(byGrp).map(([grp, ms]) => `<strong>${grp}:</strong> ${ms.join(", ")}`).join("<br>");
        return `<div class="alert alert-warn" style="margin-top:10px"><strong>Fresh supply gaps detected</strong> — months below 50% of daily target:<br>${lines}<br><em>Storable crops can bridge these gaps, but consider preserving (canning, freezing, dehydrating) excess production from peak months.</em></div>`;
      })()}
    </div>
    </div>
    </div>
    <div class="plan-pane" data-pane="crops">

    ${(coolAnnuals.length || warmAnnuals.length) ? `<div class="card" style="margin-top:14px">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px">
        <h2>Annual crops (${coolAnnuals.length + warmAnnuals.length})</h2>
        <button class="btn btn-sec btn-sm" onclick="state.cropsTableView=!state.cropsTableView;renderApp()" style="font-size:11px">${state.cropsTableView?"⊟ List view":"⊞ Table view"}</button>
      </div>
      ${coolAnnuals.length ? `
        <div style="border-left:4px solid #4A7C8A;padding-left:10px;margin-bottom:14px">
          <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.4px;color:#2A5A6A;margin-bottom:6px">
            Cool season (May–Oct) &nbsp;·&nbsp; ${fmtHa(p.usedCoolHa||0)} / ${fmtHa(state.annualHa)}
          </div>
          ${state.cropsTableView ? renderCropsTable(coolAnnuals) : `
            <div style="padding:5px 10px;border-bottom:2px solid var(--border-dk);display:grid;grid-template-columns:160px 70px 70px 110px 90px 90px 1fr;gap:10px;font-size:10px;text-transform:uppercase;color:var(--text-mid);font-weight:700">
              <div>Crop</div><div>Group</div><div>Area</div><div>Plants</div><div>Yield</div><div>Serves</div><div>Harvest months</div>
            </div>
            ${coolAnnuals.map(renderCropRow).join("")}
          `}
        </div>` : ""}
      ${warmAnnuals.length ? `
        <div style="border-left:4px solid #8A6A2E;padding-left:10px">
          <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.4px;color:#6A4A1A;margin-bottom:6px">
            Warm season (Nov–Apr) &nbsp;·&nbsp; ${fmtHa(p.usedWarmHa||0)} / ${fmtHa(state.annualHa)}
          </div>
          ${state.cropsTableView ? renderCropsTable(warmAnnuals) : `
            <div style="padding:5px 10px;border-bottom:2px solid var(--border-dk);display:grid;grid-template-columns:160px 70px 70px 110px 90px 90px 1fr;gap:10px;font-size:10px;text-transform:uppercase;color:var(--text-mid);font-weight:700">
              <div>Crop</div><div>Group</div><div>Area</div><div>Plants</div><div>Yield</div><div>Serves</div><div>Harvest months</div>
            </div>
            ${warmAnnuals.map(renderCropRow).join("")}
          `}
        </div>` : ""}
    </div>` : ""}

    ${perennials.length ? `<div class="card" style="margin-top:14px">
      <h2>Perennial crops (${perennials.length})</h2>
      ${state.cropsTableView ? renderCropsTable(perennials) : `
        <div style="padding:6px 12px;border-bottom:2px solid var(--border-dk);display:grid;grid-template-columns:160px 70px 70px 110px 90px 90px 1fr;gap:10px;font-size:10px;text-transform:uppercase;color:var(--text-mid);font-weight:700">
          <div>Crop</div><div>Group</div><div>Area</div><div>Plants</div><div>Yield</div><div>Serves</div><div>Harvest months</div>
        </div>
        ${perennials.map(renderCropRow).join("")}
      `}
    </div>` : ""}

    ${(p.lsSelected||[]).length ? `<div class="card" style="margin-top:14px;border-left:6px solid #8B6914">
      <h2>Livestock (${p.lsSelected.length} species)</h2>
      <div style="padding:6px 12px;border-bottom:2px solid #C8AA6E;display:grid;grid-template-columns:180px 80px 100px 110px 90px 1fr;gap:10px;font-size:10px;text-transform:uppercase;color:var(--text-mid);font-weight:700">
        <div>Species</div><div>Count</div><div>Space</div><div>Labour</div><div>Serves/day</div><div>Outputs</div>
      </div>
      ${(p.lsSelected||[]).map(({ls, count}) => {
        const spaceM2 = ls.space_m2_per_animal * count;
        const spaceLbl = spaceM2 >= 10000 ? (spaceM2/10000).toFixed(2)+" ha" : Math.round(spaceM2)+" m\u00b2";
        const labourYr = Math.round((ls.labour_hrs_per_animal||0) * count);
        const outTags = (function(){
          const spd = lsServesPerDay(ls, count);
          const cls = lsGroupTagClass(ls.food_group, "tag");
          return `<span class="tag ${cls}" style="font-size:10px">${spd >= 1 ? spd.toFixed(1) : spd.toFixed(2)} srv/day ${ls.edible_part || ls.name}</span>`;
        })();
        const totalServes = lsServesPerDay(ls, count);
        return `<div class="crop-row" style="padding:8px 12px;border-bottom:1px solid var(--border);display:grid;grid-template-columns:180px 80px 100px 110px 90px 1fr;gap:10px;align-items:center;font-size:13px;background:#FFF8EC">
          <div><strong>${ls.name}</strong></div>
          <div>${count} ${ls.unit_label}</div>
          <div class="area-badge" style="text-align:center">${spaceLbl}</div>
          <div style="font-size:12px;color:var(--text-mid)">${labourYr} hrs/yr</div>
          <div style="color:var(--text-mid);font-size:12px">${totalServes.toFixed(1)}</div>
          <div style="display:flex;gap:4px;flex-wrap:wrap">${outTags}</div>
        </div>`;
      }).join("")}
      <div style="padding:8px 12px;font-size:11px;color:var(--text-mid);background:var(--card2)">
        Budgets — <strong>${fmtHa(p.usedPastureHa||0)}</strong> of ${fmtHa(state.pastureHa||0)} budget &nbsp;·&nbsp;
        ⏱ Labour: <strong>${Math.round((p.lsSelected||[]).reduce((s,{ls,count})=>s+(ls.labour_hrs_per_animal||0)*count,0))} hrs/yr</strong> &nbsp;·&nbsp;
        Year-round production — credited to nutrition targets continuously
      </div>
    </div>` : ""}
    </div>
    </div>

    <div class="nav-row">
      <button class="btn btn-sec" onclick="goStep(2)">← Edit crop selection</button>
      <button class="btn btn-lg" onclick="goStep(4)">Manual adjustment →</button>
    </div>`;
}
// ── Plan adjustment helpers ──────────────────────────────────────────────
// Inverse of plantCount: given a count, compute the area in hectares
function plantsToHa(crop, count){
  const w = crop.w_max;
  if(!w || w <= 0 || count <= 0) return 0;
  if(BROADCAST_CROPS.has(crop.name)){
    const rowSpacing = w <= 0.3 ? 0.3 : 0.5;
    return (count * rowSpacing) / 10000;
  }
  // Individual plants: square spacing
  return (count * w * w) / 10000;
}

// Returns the unit label that plantCount() would use for this crop
function plantUnit(crop){
  const w = crop.w_max;
  if(!w || w <= 0) return "—";
  if(BROADCAST_CROPS.has(crop.name)) return "m of rows";
  if(w >= 5) return "trees";
  if(w >= 2) return "trees/shrubs";
  if(w >= 1) return "plants/shrubs";
  return "plants";
}

// Get the plan with user adjustments applied — recomputes totals & monthly distribution
function getAdjustedPlan(){
  if(!state.plan) state.plan = generatePlan(state);
  const base = state.plan;
  const adj = state.planAdjustments || {};
  const isMech = state.labourSystem === "mech";
  const selected = [];

  // Original crops, possibly modified or removed
  base.selected.forEach(s => {
    const a = adj[s.crop.name];
    if(a && a.removed) return;
    const allocHa = (a && typeof a.ha === "number") ? a.ha : s.allocHa;
    const adjY = subsistYield(s.crop, state.fertility, state.confidence);
    const totalServesYr = allocHa * adjY * 1000000 / (s.crop.serve_g || 75);
    selected.push({...s, allocHa, serves: totalServesYr / 365});
  });

  // Newly added crops (in adj but not in base.selected)
  Object.entries(adj).forEach(([name, a]) => {
    if(a.removed || typeof a.ha !== "number") return;
    if(base.selected.find(s => s.crop.name === name)) return;
    const crop = CROP_DATA.find(c => c.name === name);
    if(!crop) return;
    const adjY = subsistYield(crop, state.fertility, state.confidence);
    const totalServesYr = a.ha * adjY * 1000000 / (crop.serve_g || 75);
    selected.push({crop, allocHa: a.ha, serves: totalServesYr / 365});
  });

  // Recompute totals & monthly coverage from selected
  let usedCoolHaAdj = 0, usedWarmHaAdj = 0, usedLabour = 0;
  let usedCanopy = 0, usedTrees = 0, usedPerennialPlants = 0;
  const achieved = zeroFG();
  const monthCoverage = {};
  MONTHS.forEach(m => { monthCoverage[m] = zeroFG(); });

  selected.forEach(s => {
    if(s.crop.perennial){
      const lay = cropLayer(s.crop);
      if(lay === "canopy") usedCanopy += s.allocHa;
      else if(lay === "trees") usedTrees += s.allocHa;
      else usedPerennialPlants += s.allocHa;
    } else {
      const adjSeason = getCropSeason(s.crop);
      if(adjSeason==="cool") usedCoolHaAdj += s.allocHa;
      else if(adjSeason==="warm") usedWarmHaAdj += s.allocHa;
      else { // dual — assign to whichever season currently has less used
        if(usedCoolHaAdj <= usedWarmHaAdj) usedCoolHaAdj += s.allocHa; else usedWarmHaAdj += s.allocHa;
      }
    }
    usedLabour += cropLabour(s.crop, isMech) * s.allocHa;

    const key = FG_KEY[effectiveFoodGroup(s.crop)];
    if(!key || achieved[key] === undefined) return;
    const adjY = subsistYield(s.crop, state.fertility, state.confidence);
    const totalServesYr = s.allocHa * adjY * 1000000 / (s.crop.serve_g || 75);
    achieved[key] += totalServesYr / 365;

    let harvestWeight = 0;
    MONTHS.forEach(m => {
      if(s.crop.months[m] === "P") harvestWeight += 1;
      else if(s.crop.months[m] === "S") harvestWeight += 0.5;
    });
    if(harvestWeight > 0){
      const perMonthBase = totalServesYr / harvestWeight / 30;
      MONTHS.forEach(m => {
        const v = s.crop.months[m];
        const w = v === "P" ? 1 : v === "S" ? 0.5 : 0;
        if(w > 0) monthCoverage[m][key] += perMonthBase * w;
      });
    }
  });

  const usedPerennialHa = Math.max(usedCanopy, usedTrees, usedPerennialPlants);

  // ── Apply livestock overrides (state.livestock) then credit nutrition ──────
  const lsOverrides = state.livestock || {};
  const effectiveLs = [...(base.lsSelected || [])].map(e => ({...e}));
  Object.entries(lsOverrides).forEach(([name, count]) => {
    const ex = effectiveLs.find(e => e.ls.name === name);
    if(ex) ex.count = count;
    else { const ls2 = LIVESTOCK_DATA.find(l => l.name === name); if(ls2 && count > 0) effectiveLs.push({ls: ls2, count}); }
  });
  const finalLs = effectiveLs.filter(e => e.count > 0);
  let usedPastureHa = 0;
  finalLs.forEach(({ls, count}) => {
    usedPastureHa += ls.space_m2_per_animal * count / 10000;
    usedLabour += (ls.labour_hrs_per_animal || 0) * count;
    const spd = lsServesPerDay(ls, count);
    const key2 = fgToKey(ls.food_group);
    if(key2 && achieved[key2] !== undefined){
      achieved[key2] += spd;
      MONTHS.forEach(m => { if(monthCoverage[m][key2] !== undefined) monthCoverage[m][key2] += spd; });
    }
  });

  // NOTE: usedCoolHaAdj / usedWarmHaAdj are computed from the full `selected`
  // list (base crops + new additions), so they already represent the complete
  // cool/warm usage. Do NOT add base.usedCoolHa here — that double-counts.
  return {
    ...base, selected, lsSelected: finalLs, achieved, monthCoverage,
    usedCoolHa: usedCoolHaAdj, usedWarmHa: usedWarmHaAdj,
    usedAnnualHa: usedCoolHaAdj + usedWarmHaAdj, usedPerennialHa,
    usedPerennialHaSum: usedCanopy + usedTrees + usedPerennialPlants,
    layers: {canopy: usedCanopy, trees: usedTrees, plants: usedPerennialPlants},
    usedLabour, usedPastureHa,
    isAdjusted: Object.keys(adj).length > 0 || Object.keys(lsOverrides).length > 0
  };
}

function editCropPlants(cropName, newCount){
  if(!state.planAdjustments) state.planAdjustments = {};
  if(!state.plan) state.plan = generatePlan(state);
  let crop = state.plan.selected.find(s => s.crop.name === cropName)?.crop;
  if(!crop) crop = CROP_DATA.find(c => c.name === cropName);
  if(!crop) return;
  const n = Math.max(0, parseFloat(newCount) || 0);
  const newHa = plantsToHa(crop, n);
  state.planAdjustments[cropName] = { ha: newHa, removed: false };
  renderApp();
}

function removeCropFromPlan(cropName){
  if(!state.planAdjustments) state.planAdjustments = {};
  state.planAdjustments[cropName] = { ...(state.planAdjustments[cropName]||{}), removed: true };
  renderApp();
  // Keep the add-search usable right after removing (restore focus + caret)
  const si = document.getElementById("adjustSearchInput");
  if(si){ si.focus(); const v = si.value; si.value = ""; si.value = v; }
}

function undoRemoveCrop(cropName){
  if(!state.planAdjustments || !state.planAdjustments[cropName]) return;
  state.planAdjustments[cropName].removed = false;
  renderApp();
}

function resetPlanAdjustments(){
  state.planAdjustments = {};
  renderApp();
}

function addCropFromSearch(name, specificHa){
  // Check if it's a livestock species
  const ls = LIVESTOCK_DATA.find(l => l.name === name);
  if(ls){
    if(!state.checkedLivestock) state.checkedLivestock = new Set();
    state.checkedLivestock.add(ls.name);
    // Set a direct override count so they appear immediately in the plan list
    if(!state.livestock) state.livestock = {};
    if(!(state.livestock[ls.name] > 0)) state.livestock[ls.name] = ls.min_count;
    state.plan = null;
    state.adjustSearch = "";
    renderApp();
    return;
  }
  const cropName = name;
  if(!state.planAdjustments) state.planAdjustments = {};
  const crop = CROP_DATA.find(c => c.name === cropName);
  if(!crop) return;
  // Use specificHa if provided (from suggestion), else default
  let defaultHa;
  if(typeof specificHa === "number" && specificHa > 0){
    defaultHa = specificHa;
  } else if(crop.perennial){
    defaultHa = Math.max(plantsToHa(crop, 1), 0.001);
  } else {
    defaultHa = 0.005;
  }
  state.planAdjustments[cropName] = { ha: defaultHa, removed: false };
  state.adjustSearch = "";
  renderApp();
}

function setAdjustSearch(val){
  state.adjustSearch = val;
  // Only re-render the suggestion list in-place (keeps the input focused)
  const target = document.getElementById("adjustSearchResult");
  if(target) target.innerHTML = renderAdjustSearchResult();
}

function renderAdjustSearchResult(){
  const q = (state.adjustSearch || "").trim().toLowerCase();
  if(!q) return '';
  const adj = state.planAdjustments || {};
  if(!state.plan) state.plan = generatePlan(state);
  const inPlanNames = new Set(state.plan.selected.map(s => s.crop.name));
  Object.entries(adj).forEach(([n,a]) => { if(!a.removed && typeof a.ha === "number") inPlanNames.add(n); });

  // Livestock: show species not yet allocated in the current plan
  const planLsNames = new Set((state.plan?.lsSelected || []).map(e => e.ls.name));
  const lsMatches = LIVESTOCK_DATA.filter(ls => {
    if(!ls.name.toLowerCase().includes(q)) return false;
    if(planLsNames.has(ls.name)) return false; // already in plan section below
    return true;
  });

  // Crop matches
  const matches = CROP_DATA.filter(c => {
    if(!c.name.toLowerCase().includes(q)) return false;
    if(inPlanNames.has(c.name) && !(adj[c.name]?.removed)) return false;
    return true;
  }).slice(0, 6);

  if(!matches.length && !lsMatches.length) return '<div style="color:var(--text-mid);font-size:11px;padding:6px 0">No crops or livestock matching that name.</div>';
  // Livestock results (prepended)
  const lsResultsHTML = lsMatches.map(ls => {
    const safe = escJs(ls.name);
    const outSummary = lsDisplayOutputs(ls).map(o => o.label).join(" + ");
    return `<div style="padding:6px 10px;background:#FFF8EC;border:2px solid #C8AA6E;font-size:11px;margin-bottom:4px;display:flex;align-items:center;gap:8px;flex-wrap:wrap">
      <strong>${ls.name}</strong> <span class="tag" style="background:#EDE3CB;color:#7A5C00">Livestock</span>
      <span style="color:var(--text-mid)">${outSummary} · min ${ls.min_count} ${ls.unit_label} · ${ls.space_m2_per_animal} m²/animal</span>
      <button class="btn btn-sec" style="font-size:11px;padding:3px 9px;margin-left:auto" onclick="addCropFromSearch('${safe}')">+ Add</button>
    </div>`;
  }).join("");

  const cropResultsHTML = matches.map(c => {
    const adjY = subsistYield(c, state.fertility, state.confidence);
    const fg = effectiveFoodGroup(c);
    const harvestMonths = MONTHS.filter(m => c.months[m] === "P" || c.months[m] === "S")
      .map(m => m.charAt(0).toUpperCase() + m.slice(1, 3));
    const harvestStr = harvestMonths.length === 12 ? "Year-round" : harvestMonths.join(", ");
    const suitable = isSuitable(c);
    const suitBadge = suitable ? '' : '<span class="tag" style="background:#F5E6CC;color:#7A4A00" title="Outside your climate/soil zone — can still be added">! Outside zone</span>';
    const bg = suitable ? 'var(--green-xlt)' : 'var(--card2)';
    const border = suitable ? 'var(--green-lt)' : 'var(--border)';
    return `<div style="padding:6px 10px;background:${bg};border:2px solid ${border};font-size:11px;margin-bottom:4px;display:flex;align-items:center;gap:8px;flex-wrap:wrap">
      <strong>${c.name}</strong> ${tag(fg)} ${c.perennial?'<span class="tag" style="background:#EDE3CB">Perennial</span>':'<span class="tag" style="background:#E4EED4">Annual</span>'} ${suitBadge}
      <span style="color:var(--text-mid)">${adjY.toFixed(1)} t/ha · ${harvestStr}</span>
      <button class="btn btn-sec" style="font-size:11px;padding:3px 9px;margin-left:auto" onclick="addCropFromSearch('${escJs(c.name)}')">+ Add</button>
    </div>`;
  }).join("");

  return lsResultsHTML + cropResultsHTML;
}


// ── Annual consumption simulation (fresh + stored) ────────────────────────
function simulateAnnualConsumption(plan, household, fertility, confidence){
  const targets = calcTotals(household);
  const cropMonthly = {};   // {cropName: [12 daily-serve values]}
  const cropMeta = {};      // {cropName: {storable, harvestMonths, totalServesYr, group}}

  plan.selected.forEach(s => {
    const c = s.crop;
    const adjY = subsistYield(c, fertility, confidence);
    const annualKg = s.allocHa * adjY * 1000;
    const totalServesYr = annualKg * 1000 / (c.serve_g || 75);

    let harvestWeight = 0;
    MONTHS.forEach(m => {
      if(c.months[m] === "P") harvestWeight += 1;
      else if(c.months[m] === "S") harvestWeight += 0.5;
    });
    const monthly = MONTHS.map(()=>0);

    if(harvestWeight > 0){
      // Every crop: in-season daily rate across its supply window (harvest months + real
      // cool-store bridge from cropSupplyMonths). Long-storing staples cover all 12 months
      // and so read as smooth year-round supply; short-store crops concentrate near harvest.
      const sup = cropSupplyMonths(c);
      const supplyMonths = sup.coveredCount > 0 ? sup.coveredCount : harvestWeight;
      const inSeasonRate = totalServesYr / (supplyMonths * 30);
      MONTHS.forEach((m, i) => { if(sup.months[i] > 0) monthly[i] = inSeasonRate * sup.months[i]; });
    }

    cropMonthly[c.name] = monthly;
    cropMeta[c.name] = {totalServesYr, group: effectiveFoodGroup(c)};
  });

  // Aggregate by food group, separating fresh-harvest vs stored contributions
  const groupMonthly = {};
  FG_KEYS.forEach(k => groupMonthly[k] = MONTHS.map(()=>({fresh:0, stored:0})));
  
  plan.selected.forEach(s => {
    const key = FG_KEY[effectiveFoodGroup(s.crop)];
    if(!key || !groupMonthly[key]) return;
    const meta = cropMeta[s.crop.name];
    cropMonthly[s.crop.name].forEach((v, i) => {
      const isHarvestMonth = s.crop.months[MONTHS[i]] === "P" || s.crop.months[MONTHS[i]] === "S";
      if(!isHarvestMonth){
        // Off-harvest supply comes from storage (annual-average storables, or fresh bridge)
        groupMonthly[key][i].stored += v;
      } else {
        groupMonthly[key][i].fresh += v;
      }
    });
  });

  // Calculate consumption (capped at need)
  const consumption = {};
  Object.entries(groupMonthly).forEach(([key, monthly]) => {
    const need = targets[key] || 0;
    consumption[key] = monthly.map(({fresh, stored}) => {
      const supply = fresh + stored;
      const consumed = Math.min(supply, need);
      // Apportion consumption between fresh and stored proportionally
      const freshConsumed = supply > 0 ? consumed * (fresh/supply) : 0;
      const storedConsumed = consumed - freshConsumed;
      return {
        fresh, stored, supply, need, consumed,
        freshConsumed, storedConsumed,
        surplus: Math.max(0, supply - need),
        deficit: Math.max(0, need - supply),
        coverage: need > 0 ? supply / need : 0
      };
    });
  });

  // Annual totals per group
  const annualByGroup = {};
  Object.entries(consumption).forEach(([key, monthly]) => {
    let totalConsumed = 0;
    monthly.forEach((m, i) => {
      const days = [31,28,31,30,31,30,31,31,30,31,30,31][i];
      totalConsumed += m.consumed * days;
    });
    annualByGroup[key] = totalConsumed;
  });

  // Crop contribution to annual diet (by total serves consumed)
  const cropAnnualContribution = {};
  plan.selected.forEach(s => {
    const monthly = cropMonthly[s.crop.name];
    let total = 0;
    monthly.forEach((v, i) => {
      const days = [31,28,31,30,31,30,31,31,30,31,30,31][i];
      total += v * days;
    });
    cropAnnualContribution[s.crop.name] = total;
  });

  return {cropMonthly, cropMeta, groupMonthly, consumption, targets, annualByGroup, cropAnnualContribution};
}

function renderStep5(){
  if(!state.plan) state.plan = generatePlan(state);
  const p = getAdjustedPlan();
  const totals = calcTotals(state.household);
  const isAdj = p.isAdjusted;
  const adj = state.planAdjustments || {};

  // ── Budget bars ──
  const budBar = (used, max, color) => {
    const pct = max > 0 ? used / max * 100 : 0;
    const fillCls = pct > 100 ? "over" : pct > 80 ? "warn" : "";
    const fillColor = color ? `background:${color}` : "";
    const overTag = pct > 100 ? `<span class="adj-over-tag">+${(pct-100).toFixed(0)}%</span>` : "";
    return `<div class="adj-layer-bar"><div class="adj-layer-fill ${fillCls}" style="width:${Math.min(100,pct)}%;${fillColor}"></div></div>${overTag}`;
  };

  // Layer data for perennial
  const layers = p.layers || {canopy:0, trees:0, plants:0};
  const pBudget = state.perennialHa;
  const layerDefs = [
    {key:"canopy", label:"Canopy ≥25m", color: LAYER_COLORS.canopy},
    {key:"trees",  label:"Trees 4–24m",  color: LAYER_COLORS.trees},
    {key:"plants", label:"Plants  <4m",  color: LAYER_COLORS.plants},
  ];

  const stickyBudgets = `
    <div class="adj-sticky">
      ${compactBudgetStrip(state, p)}
      <div style="display:flex;align-items:center;gap:7px;padding:4px 0 0 0">
        <span style="font-size:11px;color:var(--green-dk);font-weight:700;white-space:nowrap;flex-shrink:0">＋ add to plan</span>
        <input id="adjustSearchInput" placeholder="Search crops &amp; livestock to add…" value="${state.adjustSearch||""}" oninput="setAdjustSearch(this.value)"
          style="flex:1;padding:3px 8px;border:1px solid;border-color:var(--dark) var(--hl) var(--hl) var(--dark);background:var(--field);font-size:12px;font-family:inherit;box-shadow:inset 1px 1px 0 var(--shadow)"/>
      </div>
    </div>`;

  // ── Crops list (left column) ──
  const coolAnnuals = p.selected.filter(s => !s.crop.perennial && getCropSeason(s.crop) !== "warm");
  const warmAnnuals = p.selected.filter(s => !s.crop.perennial && getCropSeason(s.crop) !== "cool");
  const perennials = p.selected.filter(s => s.crop.perennial);
  // Include removed crops in display so user can undo
  const removedCrops = [];
  Object.entries(adj).forEach(([name, a]) => {
    if(a.removed){
      const orig = state.plan.selected.find(s => s.crop.name === name);
      if(orig) removedCrops.push(orig);
    }
  });

  const renderEditRow = (s, removed) => {
    const crop = s.crop;
    const adjY = subsistYield(crop, state.fertility, state.confidence);
    const kgYr = Math.round(s.allocHa * adjY * 1000);
    const pc = plantCount(crop, s.allocHa);
    const unit = plantUnit(crop);
    // Extract numeric count from label like "175 plants" or "3,386 m of rows"
    const m = pc.label.match(/^([\d,]+)/);
    const count = m ? m[1].replace(/,/g,"") : 0;
    const isEdited = !!(adj[crop.name] && typeof adj[crop.name].ha === "number" && !adj[crop.name].removed);
    const harvest = MONTHS.map(mo => `<span class="adj-mcell ${crop.months[mo]==='P'?'p':crop.months[mo]==='S'?'s':''}"></span>`).join("");
    const safeName = escJs(crop.name);
    if(removed){
      return `<div class="adj-crop-edit removed">
        <div>
          <div class="adj-crop-name">${crop.name} ${tag(effectiveFoodGroup(crop))}</div>
          <div class="adj-crop-detail">Removed — click ↻ to restore</div>
        </div>
        <div class="adj-kg-badge">—</div>
        <div class="adj-count-wrap"><input class="adj-count-input" value="0" disabled/><div class="adj-count-unit">${unit}</div></div>
        <button class="adj-btn-rm undo" title="Restore" onclick="undoRemoveCrop('${safeName}')">↻</button>
      </div>`;
    }
    return `<div class="adj-crop-edit">
      <div>
        <div class="adj-crop-name">${crop.name} ${tag(effectiveFoodGroup(crop))}</div>
        <div class="adj-crop-detail"><span class="adj-mbar">${harvest}</span> · ${fmtHa(s.allocHa)}${crop.perennial && crop.establishment_years ? ` · ${crop.establishment_years}yr to produce`:""}${crop.byproducts && crop.byproducts.length ? ` · <span title="Also yields: ${crop.byproducts.map(b=>b.edible_part).join(', ')}" style="color:var(--green-dk);cursor:help">+${crop.byproducts.map(b=>b.edible_part).join(', ')}</span>` : ""}</div>
      </div>
      <div class="adj-kg-badge">${kgYr.toLocaleString()} kg/yr</div>
      <div class="adj-count-wrap">
        <input class="adj-count-input ${isEdited?'changed':''}" value="${count}" onchange="editCropPlants('${safeName}', this.value)"/>
        <div class="adj-count-unit">${unit}</div>
      </div>
      <button class="adj-btn-rm" title="Remove" onclick="removeCropFromPlan('${safeName}')">×</button>
    </div>`;
  };

  // ── Livestock rows for the plan list ─────────────────────────────────────
  const lsPlanEntries = p.lsSelected || [];

  function renderLivestockRow({ls, count}) {
    const safeJs = escJs(ls.name);
    const outTags = (function(){
      const spd = lsServesPerDay(ls, count);
      const spdLbl = spd >= 1 ? spd.toFixed(1) : spd.toFixed(2);
      const cls = lsGroupTagClass(ls.food_group, "ls");
      return `<span class="ls-output-tag ${cls}" style="font-size:10px">${spdLbl} srv/day ${ls.edible_part || ls.name}</span>`;
    })();
    const spaceM2 = ls.space_m2_per_animal * count;
    const spaceLbl = spaceM2 >= 10000 ? (spaceM2/10000).toFixed(2)+" ha" : Math.round(spaceM2)+" m\u00b2";
    return `<div class="adj-crop-edit" style="background:var(--card2);border-left:3px solid #8B6914">
      <div style="flex:1">
        <div class="adj-crop-name">${ls.name}</div>
        <div class="adj-crop-detail" style="display:flex;flex-wrap:wrap;gap:4px;margin-top:3px">${outTags}<span class="ls-space-pill">\uD83D\uDCCF ${spaceLbl}</span></div>
      </div>
      <div class="adj-count-wrap">
        <input class="adj-count-input" type="number" min="0" value="${count}" style="width:54px" onchange="editLivestockCount('${safeJs}',this.value)"/>
        <div class="adj-count-unit">${ls.unit_label}</div>
      </div>
      <button class="adj-btn-rm" title="Remove" onclick="removeLivestockFromPlan('${safeJs}')">×</button>
    </div>`;
  }

  const lsTotalSpace = calcLivestockSpaceHa();
  const lsPastureOk = lsTotalSpace <= (state.pastureHa||0) + 0.0001;

  const cropsSectionsHTML = `
      ${(coolAnnuals.length || warmAnnuals.length) ? `
        ${coolAnnuals.length ? `
          <div class="adj-section-label" style="background:#E8F0F3;color:#2A5A6A;border-color:#7AABB8">COOL SEASON (${coolAnnuals.length}) · May–Oct · ${fmtHa(p.usedCoolHa||0)} / ${fmtHa(state.annualHa)}</div>
          <div class="adj-col-head"><div>Crop</div><div>Yield</div><div>Count</div><div></div></div>
          ${coolAnnuals.map(s => renderEditRow(s, false)).join("")}
        ` : ""}
        ${warmAnnuals.length ? `
          <div class="adj-section-label" style="background:#F3EEE0;color:#6A4A1A;border-color:#C8AA6E;margin-top:6px">WARM SEASON (${warmAnnuals.length}) · Nov–Apr · ${fmtHa(p.usedWarmHa||0)} / ${fmtHa(state.annualHa)}</div>
          <div class="adj-col-head"><div>Crop</div><div>Yield</div><div>Count</div><div></div></div>
          ${warmAnnuals.map(s => renderEditRow(s, false)).join("")}
        ` : ""}
      ` : ""}      ${perennials.length ? `
        <div class="adj-section-label">PERENNIAL CROPS (${perennials.length})</div>
        ${perennials.map(s => renderEditRow(s, false)).join("")}
      `:""}
      ${lsPlanEntries.length ? `
        <div class="adj-section-label" style="background:#EDE3CB;color:#7A5C00;border-color:#C8AA6E">LIVESTOCK (${lsPlanEntries.length} species)</div>
        ${lsPlanEntries.map(entry => renderLivestockRow(entry)).join("")}
        ${lsTotalSpace > 0 ? `<div style="font-size:10px;color:${lsPastureOk?'var(--green-dk)':'var(--iron)'};padding:4px 8px;margin-top:2px">\uD83D\uDCCF Total pasture/water: ${fmtHa(lsTotalSpace)} / ${fmtHa(state.pastureHa||0)} budget${!lsPastureOk?' \u26A0 over budget':''}</div>` : ""}
      `:""}
      ${removedCrops.length ? `
        <div class="adj-section-label" style="background:#F0DDD8">REMOVED (${removedCrops.length})</div>
        ${removedCrops.map(s => renderEditRow(s, true)).join("")}
      `:""}`;

  // (livestock shown in crops-in-plan section above)

  // ── Suggested supplements (bottom of left column) ──
  const sugg = suggestNutrientSupplements(p, state);
  let supplementsHTML = "";
  if(sugg.suggestions.length){
    const rows = sugg.suggestions.map(s => {
      const pc = plantCount(s.crop, s.suggestedHa);
      const safe = escJs(s.crop.name);
      const reasonsLine = s.reasons.slice(0, 3).join(", ");
      return `<div class="adj-suggest-row">
        <div style="flex:1;min-width:0">
          <strong>${s.crop.name}</strong> ${tag(effectiveFoodGroup(s.crop))} · ${pc.label} · +${Math.round(s.labour)} hrs/yr
          <div style="font-size:10px;color:var(--text-mid);margin-top:2px">Adds ${reasonsLine}</div>
        </div>
        <button class="btn btn-sec" style="font-size:11px;padding:3px 9px;white-space:nowrap" onclick="addCropFromSearch('${safe}', ${s.suggestedHa})">+ Add</button>
      </div>`;
    }).join("");
    supplementsHTML = `<div class="adj-card" style="border-left:6px solid var(--clay)">
      <h2>Suggested supplements <span class="adj-card-live">(based on current gaps)</span></h2>
      <p class="desc">Crops that would best fill: <strong>${sugg.gapNames.join(", ")}</strong>. Percentages show each crop's contribution as a share of your household's total daily requirement for that nutrient.</p>
      ${rows}
    </div>`;
  } else if(sugg.reason === "no_gaps"){
    supplementsHTML = `<div class="adj-card" style="border-left:6px solid var(--green)">
      <h2>Suggested supplements</h2>
      <p class="desc" style="color:var(--green-dk)"><strong>✓ Nutritionally complete</strong> — every tracked nutrient meets or exceeds household reference values.</p>
    </div>`;
  } else if(sugg.reason === "no_space"){
    supplementsHTML = `<div class="adj-card" style="border-left:6px solid var(--clay)">
      <h2>Suggested supplements</h2>
      <p class="desc"><strong>Nutrient gaps remain in ${sugg.gapNames.join(", ")}</strong>, but land and labour budgets are fully used. Increase your annual or perennial area on Step 1 to grow more.</p>
    </div>`;
  }

  // ── Daily target coverage (rail) — ONE stacked bar per umbrella group ────────
  // Each bar's segments are the contributing sub-groups (shades of the umbrella hue),
  // widths proportional to each sub-group's achieved serves vs the umbrella target.
  // The umbrella total % and (in adjust mode) its delta sit at the right.
  const cgRows = umbrellaSum(totals).map(({umb, total: target}) => {
    if(target <= 0) return "";
    // achieved per member sub-group
    const memAch = umb.members.map(m => ({ ...m, ach: p.achieved[m.key] || 0 }));
    const actual = memAch.reduce((s,m) => s + m.ach, 0);
    const baseActual = umb.members.reduce((s,m) => s + (state.plan.achieved[m.key] || 0), 0);
    const pct = Math.round(actual / target * 100);
    const deltaPct = Math.round((actual - baseActual) / target * 100);
    let deltaStr = "";
    if(isAdj && Math.abs(deltaPct) >= 1){
      const cls2 = deltaPct > 0 ? "cg-delta-up" : "cg-delta-down";
      const arrow = deltaPct > 0 ? "↑" : "↓";
      deltaStr = ` <span class="${cls2}">${arrow}${Math.abs(deltaPct)}</span>`;
    }
    const valCls = pct >= 100 ? "ok" : "under";
    // Build stacked segments. Each width = ach/target as % of the track (track = 100% target).
    // Segments are capped collectively at 100% width so the bar can't overflow the track;
    // the umbrella total % to the right still shows true coverage (incl. any overshoot).
    let cumPct = 0;
    const segs = memAch.filter(m => m.ach > 0.0001).map(m => {
      let wPct = m.ach / target * 100;
      if(cumPct + wPct > 100) wPct = Math.max(0, 100 - cumPct);
      cumPct += wPct;
      if(wPct <= 0) return "";
      const title = `${m.label}: ${m.ach.toFixed(1)} srv/day`;
      return `<div class="cg-seg" style="width:${wPct}%;background:${m.shade}" title="${title}"></div>`;
    }).join("");
    return `<div class="cg-row">
      <span class="cg-lbl">${umb.label}</span>
      <div class="cg-track cg-track-stack">${segs}<div class="cg-100"></div></div>
      <span class="cg-val ${valCls}">${pct}%${deltaStr}</span>
    </div>`;
  }).filter(r=>r).join("");
  // Sub-group legend — only the umbrellas that actually split (Veg, Protein, Starches
  // has one label but keep for clarity if >1). Shows which shade is which sub-group.
  const cgSubLegend = (function(){
    const items = [];
    umbrellaSum(totals).forEach(({umb, total}) => {
      if(total <= 0 || umb.members.length < 2) return;
      umb.members.forEach(m => {
        if((totals[m.key]||0) <= 0 && (p.achieved[m.key]||0) <= 0) return;
        items.push(`<span class="cg-leg-item"><span class="cg-leg-sw" style="background:${m.shade}"></span>${m.label}</span>`);
      });
    });
    return items.length ? `<div class="cg-sublegend">${items.join("")}</div>` : "";
  })();

  // ── Nutrient analysis (right column) ──
  const yieldNut = nutritionalYield(p, state.fertility, state.confidence);
  const baseYieldNut = isAdj ? nutritionalYield(state.plan, state.fertility, state.confidence) : yieldNut;
  const dailyNRV = householdNRV(state.household);
  const annualNRV = {};
  Object.entries(dailyNRV).forEach(([k,v]) => annualNRV[k] = v * 365);
  const order = ["kcal","protein","fat","fiber","ca","fe","mg","k","zn","vitA","vitC","vitE","b1","b2","b3","b6","folate"];
  const nrvList = [];
  const nutRows = order.map(n => {
    const produced = yieldNut[n] || 0;
    const baseProduced = baseYieldNut[n] || 0;
    const needed = annualNRV[n] || 0;
    if(!needed) return "";
    const pct = Math.round(produced/needed*100);
    const cap = Math.min(100, pct);
    const cls = pct >= 100 ? "" : pct >= 70 ? "warn" : "bad";
    const barColor = pct >= 100 ? "var(--green)" : pct >= 70 ? "var(--clay)" : "var(--iron)";
    const label = NUTRIENT_LABELS[n] || n;
    const unit = NUTRIENT_UNITS[n] || "";
    nrvList.push({label, pct});
    let badge;
    if(pct >= 100) badge = `<span class="adj-delta-good">✓ Met</span>`;
    else badge = `<span style="color:${pct>=70?"var(--clay)":"var(--iron)"}">${pct}%</span>`;
    const fmtN = v => v < 1000 ? v.toFixed(0) : v >= 1e6 ? (v/1e6).toFixed(1)+"M" : v >= 1e4 ? Math.round(v/1000)+"k" : Math.round(v).toLocaleString();
    return `<div class="adj-nut-row">
      <div class="adj-nut-name">${label}</div>
      <div class="adj-nut-info">${fmtN(produced)} / ${fmtN(needed)} ${unit}</div>
      <div class="adj-nut-bar"><div class="adj-nut-fill" style="width:${cap}%;background:${barColor}"></div></div>
      <div class="adj-nut-pct">${badge}</div>
    </div>`;
  }).filter(r=>r).join("");
  const nrvMet = nrvList.filter(x=>x.pct>=100).length;
  const nrvTotal = nrvList.length;
  const nrvGaps = nrvList.filter(x=>x.pct<100).sort((a,b)=>a.pct-b.pct);
  const nrvChips = nrvGaps.slice(0,8).map(g=>`<span class="nrv-chip ${g.pct<60?'sev':''}">${g.label} <b>${g.pct}%</b></span>`).join("");

  // ── Monthly food availability (right column) ──
  const monthCells = MONTHS.map(m => m.charAt(0).toUpperCase());
  const monthRows = FLOOR_KEYS.map(k => [FG_DISPLAY[k].short, k, FG_DISPLAY[k].tag]).map(([lbl, key, cls]) => {
    const target = totals[key] || 0;
    if(target <= 0) return "";
    const cells = MONTHS.map(m => {
      const cov = p.monthCoverage[m]?.[key] || 0;
      const pct = target > 0 ? Math.round(100*cov/target) : 0;
      let covCls;
      if(pct > 100) covCls = "adj-cov-glut";
      else if(pct >= 80) covCls = "adj-cov-good";
      else if(pct >= 50) covCls = "adj-cov-mid";
      else covCls = "adj-cov-bad";
      return `<td class="${covCls}">${pct||"·"}</td>`;
    }).join("");
    return `<tr><td style="text-align:left;padding-left:4px"><span class="tag ${cls}">${lbl}</span></td>${cells}</tr>`;
  }).filter(r=>r).join("");

  // ── Final assembly (Direction A — Instrument Rail) ──
  return `
    <div class="adj-intro">
      <h2>Adjust your plan</h2>
      <p>Edit plant counts or remove crops on the left — the instrument rail tracks coverage, nutrients and supply in real time. You may exceed budgets; warnings appear but nothing is forced.${isAdj?` <strong style="color:var(--green-dk)">· ${Object.keys(adj).length} active edit${Object.keys(adj).length!==1?"s":""}.</strong>`:""}</p>
    </div>
    <div class="adj-stuck-sentinel"></div>
    <div class="adj-pinned">
      ${stickyBudgets}
    </div>
    <div class="adj-cols-rail">
      <div>
        <div class="adj-hero">
          <div class="adj-hero-head">
            <h2>Crops in plan</h2><span class="cnt">(${p.selected.length})</span>
          </div>
          <div class="adj-hero-body">
            <div id="adjustSearchResult">${renderAdjustSearchResult()}</div>
            ${cropsSectionsHTML}
          </div>
        </div>
        ${supplementsHTML}
      </div>
      <div class="adj-rail">
        <div class="vp">
          <h3>Daily target coverage <span class="live">live</span></h3>
          <div class="vp-body">
            ${cgRows}
            ${cgSubLegend}
            <div style="font-size:9px;color:var(--text-mid);margin-top:6px">% of household ADG serves/day · marker = 100% target</div>
          </div>
        </div>
        <div class="vp">
          <h3>Nutrient status <span class="live">NHMRC NRV</span></h3>
          <div class="vp-body">
            <div class="nrv-head">
              <div class="nrv-big">${nrvMet}<span class="tot">/${nrvTotal}</span></div>
              <div class="nrv-sub">reference values met<br>by annual production</div>
            </div>
            ${nrvGaps.length ? `<div class="nrv-caption">Largest gaps</div><div class="nrv-chips">${nrvChips}</div>` : `<div style="font-size:11px;color:var(--green-dk);font-weight:700">✓ All tracked NRVs met</div>`}
            <details>
              <summary>Full nutrient breakdown (${nrvTotal})</summary>
              <div style="margin-top:8px">${nutRows}</div>
              <div class="vp-note">ADG food-group serves were calibrated for a typical diet that includes fortified bread (folate, thiamin, iodine), iodised salt and some animal foods. A self-provisioning farm lacks those, so meeting every NRV often needs more produce variety than the ADG implies — especially iron, folate, calcium, zinc &amp; B-vitamins.</div>
            </details>
          </div>
        </div>
        <div class="vp">
          <h3>Supply calendar <span class="live">live</span></h3>
          <div class="vp-body">
            <div style="display:flex;gap:5px;font-size:9px;margin-bottom:6px;align-items:center;flex-wrap:wrap">
              <span class="adj-cov-good" style="padding:1.5px 5px;font-weight:600">≥80%</span>
              <span class="adj-cov-mid" style="padding:1.5px 5px;font-weight:600">50–79%</span>
              <span class="adj-cov-bad" style="padding:1.5px 5px;font-weight:600">&lt;50%</span>
              <span class="adj-cov-glut" style="padding:1.5px 5px;font-weight:600">&gt;100%</span>
            </div>
            <table class="adj-month-grid">
              <thead><tr><th style="text-align:left;padding-left:4px">Grp</th>${monthCells.map(c=>`<th>${c}</th>`).join("")}</tr></thead>
              <tbody>${monthRows}</tbody>
            </table>
            <div style="font-size:9px;color:var(--text-mid);margin-top:6px">Cells show % of each month's target met.</div>
          </div>
        </div>
      </div>
    </div>
    <div class="nav-row" style="margin-top:14px">
      <button class="btn btn-sec" onclick="goStep(3)">← Farm Plan</button>
      <button class="btn btn-sec" onclick="resetPlanAdjustments()" ${!isAdj?'disabled style="opacity:0.5"':''}>↺ Reset to auto-plan</button>
      <button class="btn" onclick="window.print()">Print / save PDF</button>
    </div>`;
}


// ─────────────────────────────────────────────────────────────────────────────
// IRRIGATION DEMAND ENGINE
// Per-crop monthly water demand via FAO-56 Kc curve-walk × reference ET − rainfall.
// Reusable per-crop function so demand can also run at selection time for a future
// "minimise irrigation" objective. Per-location climate is supplied from CLIMATE_DB;
// PERTH_ETO/PERTH_RAIN below are only the fallback for a custom 'Other' location.
// ─────────────────────────────────────────────────────────────────────────────

// Jan..Dec, mm. SILO DataDrill (grid -31.95, 115.85), FAO-56 short-crop ETo (et_short_crop)
// and daily_rain, aggregated to a 2005-2024 monthly normal. Fallback for a custom
// location only; named towns use their own CLIMATE_DB entry.
const PERTH_ETO  = [208, 172, 151, 100, 71, 52, 53, 69, 93, 133, 167, 202];
const PERTH_RAIN = [14, 17, 18, 39, 78, 113, 136, 112, 72, 36, 24, 11];

// Per-location climate now comes from CLIMATE_DB (built once via climate_builder.html);
// the shipped app does no live SILO fetch. PERTH_ETO/PERTH_RAIN remain the
// fallback for a custom 'Other' location with no baked climate.

// Perennial Kc categories with a year-round canopy → flat Kc. Everything else is
// treated as winter-dormant/deciduous. (aquatic_wetbed crops are excluded upstream.)
const EVERGREEN_CATS = new Set(["citrus", "tropical_evergreen", "evergreen_sclerophyll",
  "nut_evergreen", "banana", "palm", "pineapple"]);

// 12-month Kc curve (Jan..Dec) for one crop, from its kc object:
//   evergreen perennial → flat at Kc-mid all year (ET seasonality drives demand)
//   deciduous perennial → 4-stage curve over the Sep–Apr canopy season, 0 in winter
//   annual              → 4-stage curve over [planting → end of harvest];
//                         planted May (cool-season) or Oct (warm-season)
function monthlyKc(crop){
  const out = new Array(12).fill(0);
  const kc = crop.kc;
  if(!kc) return out;
  const ini = kc.ini, mid = kc.mid, end = kc.end, cat = kc.cat;
  const st = (Array.isArray(kc.stages) && kc.stages.length >= 4) ? kc.stages : [0.2, 0.3, 0.3, 0.2];
  // Kc at fractional position f (0..1) along the growing season (FAO trapezoid).
  const kcAt = (f) => {
    const a = st[0], b = st[1], c = st[2], d = st[3];
    if(f < a)         return ini;
    if(f < a + b)     return ini + (mid - ini) * (f - a) / (b || 1e-9);
    if(f < a + b + c) return mid;
    return mid + (end - mid) * Math.min(1, (f - (a + b + c)) / (d || 1e-9));
  };

  if(crop.perennial){
    if(EVERGREEN_CATS.has(cat)){ out.fill(mid); return out; }
    const start = 8, L = 8;                          // Sep (index 8), 8-month canopy season
    for(let k = 0; k < L; k++) out[(start + k) % 12] = kcAt((k + 0.5) / L);
    return out;
  }

  // annual: fixed seasonal planting month (Oct for warm-season crops, May for cool-season),
  // with the Kc trapezoid spread from planting to the last harvest month. (gmin/gmax growing-
  // season figures were trialled for back-dating but found unreliable, so reverted to this.)
  const plant = (getCropSeason(crop) === "warm") ? 9 : 4;   // Oct=9 warm, May=4 cool
  const harvest = [];
  MONTHS.forEach((m, i) => { const v = (crop.months || {})[m]; if(v === "P" || v === "S") harvest.push(i); });
  let L;
  if(harvest.length){
    let maxFwd = 0;
    harvest.forEach(h => { const fwd = (h - plant + 12) % 12; if(fwd > maxFwd) maxFwd = fwd; });
    L = maxFwd + 1;                                  // planting month → last harvest month
  } else {
    L = Math.max(3, Math.round((crop.gmax || crop.gmin || 120) / 30));
  }
  L = Math.min(L, 12);
  for(let k = 0; k < L; k++) out[(plant + k) % 12] = kcAt((k + 0.5) / L);
  return out;
}

// Litres of irrigation per month (Jan..Dec) for one crop over areaHa.
// irrigation = max(0, ETc − rain); effective rain = min(rain, ETc). 1mm·ha = 10,000 L.
function cropMonthlyIrrigation(crop, areaHa, eto, rain){
  eto = eto || (typeof state !== "undefined" && state.climateEto) || PERTH_ETO; rain = rain || (typeof state !== "undefined" && state.climateRain) || PERTH_RAIN;
  const kcA = monthlyKc(crop);
  const out = new Array(12);
  for(let m = 0; m < 12; m++){
    const etc = kcA[m] * eto[m];
    out[m] = Math.max(0, etc - rain[m]) * areaHa * 10000;
  }
  return out;
}

// Property monthly irrigation curve + per-crop annual totals.
// Includes land perennials + all annuals; excludes aquatic/"both" (pond-grown) and Kc-less crops.
function propertyIrrigationCurve(plan, eto, rain){
  eto = eto || (typeof state !== "undefined" && state.climateEto) || PERTH_ETO; rain = rain || (typeof state !== "undefined" && state.climateRain) || PERTH_RAIN;
  const monthly = new Array(12).fill(0);
  const perCrop = [];
  (plan.selected || []).forEach(({crop, allocHa}) => {
    if(cropHabitat(crop) !== "land") return;
    if(!crop.kc) return;
    const lit = cropMonthlyIrrigation(crop, allocHa, eto, rain);
    let annual = 0;
    for(let m = 0; m < 12; m++){ monthly[m] += lit[m]; annual += lit[m]; }
    if(annual > 0) perCrop.push({ name: crop.name, annualL: annual });
  });
  perCrop.sort((a, b) => b.annualL - a.annualL);
  return { monthly, perCrop, annualTotal: monthly.reduce((s, v) => s + v, 0) };
}

// Reservoir storage from a monthly demand series (Rippl mass-curve): the largest
// cumulative draw-down across any run of demand months, resetting at refill (zero-demand)
// months. NOT the naive sum — that would over-size a bimodal-dry-season climate.
function maxCumulativeDeficit(monthly){
  const eps = 1; // litres ≈ 0
  if(monthly.every(v => v > eps)) return monthly.reduce((s, v) => s + v, 0); // never refills
  let max = 0, run = 0;
  for(let i = 0; i < 24; i++){            // doubled to handle the dry season wrapping the year
    const v = monthly[i % 12];
    if(v <= eps) run = 0; else { run += v; if(run > max) max = run; }
  }
  return max;
}

// Size the dam: storage from the deficit, surface = max(storage surface, aquatic surface).
function sizeDam(plan, eto, rain){
  const irr = propertyIrrigationCurve(plan, eto, rain);
  const storageL = maxCumulativeDeficit(irr.monthly);
  const depth = Math.max(0.5, (typeof state !== "undefined" && state.damDepth) || 3);
  const irrSurfaceM2 = storageL / 1000 / depth;          // volume(m³) / depth
  // Surface the chosen aquatic crops/livestock actually use; the allocator already tracks
  // this in usedSurfaceWaterHa, honouring "both → land default, spill to water". Fall back to
  // a pure-aquatic re-derivation only if an adjusted plan didn't carry the field.
  let aquaticHa = plan.usedSurfaceWaterHa;
  if(aquaticHa == null){
    aquaticHa = 0;
    (plan.selected || []).forEach(({crop, allocHa}) => { if(cropHabitat(crop) === "aquatic") aquaticHa += allocHa; });
    (plan.lsSelected || []).forEach(({ls, count}) => { if(isAquaticLivestock(ls)) aquaticHa += (ls.space_m2_per_animal || 0) * count / 10000; });
  }
  const aquaticM2 = aquaticHa * 10000;
  const surfaceM2 = Math.max(irrSurfaceM2, aquaticM2);
  return {
    storageL, depth, irrSurfaceM2, aquaticM2, surfaceM2,
    volumeL: surfaceM2 * depth * 1000,                   // actual capacity at that surface
    footprintHa: surfaceM2 / 10000,
    bind: irrSurfaceM2 >= aquaticM2 ? "irrigation storage" : "aquatic surface",
    monthly: irr.monthly
  };
}

// Per-month water balance for the plan's land crops: crop ET demand split into the
// part met by effective rain and the irrigation shortfall (demand = effRain + irrigation).
function propertyWaterBalance(plan, eto, rain){
  eto  = eto  || (typeof state !== "undefined" && state.climateEto)  || PERTH_ETO;
  rain = rain || (typeof state !== "undefined" && state.climateRain) || PERTH_RAIN;
  const demand = new Array(12).fill(0), effRain = new Array(12).fill(0), irrig = new Array(12).fill(0);
  const perCrop = [];
  (plan.selected || []).forEach(({crop, allocHa}) => {
    if(cropHabitat(crop) !== "land") return;
    if(!crop.kc) return;
    const kcA = monthlyKc(crop);
    let annualIrr = 0;
    for(let m = 0; m < 12; m++){
      const etc = kcA[m] * eto[m];                 // crop ET, mm
      const eff = Math.min(rain[m], etc);          // rain that offsets watering, mm
      const irr = Math.max(0, etc - rain[m]);      // shortfall to irrigate, mm
      const f   = allocHa * 10000;                 // mm·ha -> L
      demand[m]  += etc * f;
      effRain[m] += eff * f;
      irrig[m]   += irr * f;
      annualIrr  += irr * f;
    }
    if(annualIrr > 0) perCrop.push({ name: crop.name, annualL: annualIrr });
  });
  perCrop.sort((a, b) => b.annualL - a.annualL);
  const storageL = maxCumulativeDeficit(irrig);
  const damLevel = damLevelSeries(irrig, storageL);
  const sum = a => a.reduce((s, v) => s + v, 0);
  return { demand, effRain, irrig, perCrop, damLevel, storageL,
           annualDemand: sum(demand), annualEffRain: sum(effRain), annualIrrig: sum(irrig) };
}

// Dam level (L) across Jan..Dec for a monthly irrigation-draw series, matching the Rippl
// storage figure: the reservoir sits full (= storage) through refill months and draws down
// through each dry run; its lowest point touches 0 when sized exactly to `storage`. Computed
// over a doubled year so a dry season that wraps Dec->Jan is captured.
function damLevelSeries(irrig, storageL){
  const eps = 1;
  const level = new Array(12).fill(storageL);
  if(irrig.every(v => v > eps)){
    // No wet month to refill: the dam is filled once and drawn down across the whole year.
    let cum = 0;
    for(let m = 0; m < 12; m++){ level[m] = Math.max(0, storageL - cum); cum += irrig[m]; }
    return level;
  }
  let run = 0;
  for(let i = 0; i < 24; i++){
    const v = irrig[i % 12];
    if(v <= eps) run = 0; else run += v;
    if(i >= 12) level[i % 12] = Math.max(0, storageL - run);
  }
  return level;
}

// Standalone monthly-litres chart + per-crop annual water-use card (Summary view).
function renderIrrigationPreview(p){
  const wb = propertyWaterBalance(p);
  if(wb.annualDemand <= 0){
    return `<div class="adj-card"><h2>Water balance (preview)</h2>
      <p class="desc">No land-grown crops with water demand in the current plan.</p></div>`;
  }
  const niceCeil = (v) => {
    if(v <= 0) return 1;
    const mag = Math.pow(10, Math.floor(Math.log10(v))), n = v / mag;
    return (n <= 1 ? 1 : n <= 2 ? 2 : n <= 2.5 ? 2.5 : n <= 5 ? 5 : 10) * mag;
  };
  const peakDemandL = Math.max.apply(null, wb.demand);
  const axisKL = niceCeil(peakDemandL / 1000), scaleMax = axisKL * 1000;        // left axis: kL/month
  const rAxisKL = niceCeil((wb.storageL / 1000) || 1), rScaleMax = rAxisKL * 1000; // right axis: kL stored
  const W = 560, H = 232, PL = 48, PR = 50, PT = 14, PB = 28;
  const iW = W - PL - PR, iH = H - PT - PB, gap = iW / 12, bw = gap * 0.62;

  const grid = [0, 0.25, 0.5, 0.75, 1].map(f => {
    const y = PT + iH - f * iH, lbl = (axisKL * f).toFixed(axisKL >= 10 ? 0 : 1);
    return `<line x1="${PL}" y1="${y.toFixed(1)}" x2="${W - PR}" y2="${y.toFixed(1)}" stroke="var(--border)" stroke-width="1"/>`
      + `<text x="${PL - 6}" y="${(y + 3).toFixed(1)}" text-anchor="end" font-size="9" fill="var(--text-mid)">${lbl}</text>`;
  }).join("");
  const rAxis = [0, 0.5, 1].map(f => {
    const y = PT + iH - f * iH, lbl = (rAxisKL * f).toFixed(rAxisKL >= 10 ? 0 : 1);
    return `<text x="${W - PR + 6}" y="${(y + 3).toFixed(1)}" text-anchor="start" font-size="9" fill="#B5762F">${lbl}</text>`;
  }).join("");

  // Stacked bar per month: rain-met (green) at the base, irrigation shortfall (blue) on top.
  // Full bar height = crop ET demand; the blue cap = the deficit storage must cover.
  const bars = wb.demand.map((D, i) => {
    const x = PL + i * gap + (gap - bw) / 2;
    const hRain = scaleMax > 0 ? (wb.effRain[i] / scaleMax) * iH : 0;
    const hIrr  = scaleMax > 0 ? (wb.irrig[i]   / scaleMax) * iH : 0;
    const yRain = PT + iH - hRain, yIrr = yRain - hIrr;
    return `<rect x="${x.toFixed(1)}" y="${yRain.toFixed(1)}" width="${bw.toFixed(1)}" height="${Math.max(0, hRain).toFixed(1)}" fill="#5C7A3A"/>`
      + `<rect x="${x.toFixed(1)}" y="${yIrr.toFixed(1)}" width="${bw.toFixed(1)}" height="${Math.max(0, hIrr).toFixed(1)}" fill="#3E7C9A"/>`
      + `<text x="${(x + bw / 2).toFixed(1)}" y="${(PT + iH + 14).toFixed(1)}" text-anchor="middle" font-size="10" fill="var(--text-mid)">${MONTHS[i].charAt(0).toUpperCase()}</text>`;
  }).join("");

  // Dam-level line (right axis): full through winter, drawing down to empty across the dry season.
  const pts = wb.damLevel.map((L, i) => {
    const cx = PL + i * gap + gap / 2;
    const cy = PT + iH - (rScaleMax > 0 ? (L / rScaleMax) * iH : 0);
    return `${cx.toFixed(1)},${cy.toFixed(1)}`;
  });
  const dots = wb.damLevel.map((L, i) => {
    const cx = PL + i * gap + gap / 2, cy = PT + iH - (rScaleMax > 0 ? (L / rScaleMax) * iH : 0);
    return `<circle cx="${cx.toFixed(1)}" cy="${cy.toFixed(1)}" r="2.1" fill="#C4823A"/>`;
  }).join("");
  const linePath = `<polyline points="${pts.join(" ")}" fill="none" stroke="#C4823A" stroke-width="2"/>` + dots;

  const svg = `<svg width="100%" viewBox="0 0 ${W} ${H}" style="max-width:600px;display:block;margin:6px 0">`
    + `<text x="${PL - 6}" y="${PT - 3}" text-anchor="end" font-size="9" fill="var(--text-mid)">kL/mo</text>`
    + `<text x="${W - PR + 6}" y="${PT - 3}" text-anchor="start" font-size="9" fill="#B5762F">kL dam</text>`
    + grid + rAxis + bars + linePath + `</svg>`;

  const legend = `<div style="display:flex;gap:14px;flex-wrap:wrap;font-size:11px;margin:0 0 6px">`
    + `<span><span style="display:inline-block;width:10px;height:10px;background:#5C7A3A;border-radius:2px;vertical-align:middle"></span> Met by rain</span>`
    + `<span><span style="display:inline-block;width:10px;height:10px;background:#3E7C9A;border-radius:2px;vertical-align:middle"></span> Needs irrigation</span>`
    + `<span><span style="display:inline-block;width:14px;height:2px;background:#C4823A;vertical-align:middle"></span> Dam level (full → empty = storage)</span>`
    + `</div>`;

  const rainPct = wb.annualDemand > 0 ? Math.round(100 * wb.annualEffRain / wb.annualDemand) : 0;
  const rows = wb.perCrop.slice(0, 15).map(c =>
    `<div style="display:flex;justify-content:space-between;font-size:12px;padding:2px 0;border-bottom:1px solid var(--border)">`
    + `<span>${c.name}</span><span style="font-weight:700">${(c.annualL / 1000).toFixed(1)} kL/yr</span></div>`).join("");
  const moreN = wb.perCrop.length - 15;

  return `<div class="adj-card">
    <h2>Water balance (preview)</h2>
    <p class="desc">Monthly crop water demand (ET) for land-grown crops, split into the part rain covers and the part you irrigate. The dam-level line carries winter water into summer; the depth it draws down to empty is the storage the dam must hold. Effective rain on the cropped area only (aquatic crops draw from the pond and are excluded). Climate: ${state.climateLabel || "bundled Perth normal"}.</p>
    ${legend}
    ${svg}
    <div style="font-size:12px;margin-top:4px">Crop demand ≈ <strong>${(wb.annualDemand / 1000).toFixed(0)} kL/yr</strong>; rain covers <strong>${(wb.annualEffRain / 1000).toFixed(0)} kL</strong> (${rainPct}%), leaving <strong>${(wb.annualIrrig / 1000).toFixed(0)} kL</strong> to irrigate. Peak storage to carry the dry season ≈ <strong>${(wb.storageL / 1000).toFixed(0)} kL</strong> — the irrigation dam size.</div>
    <h3 style="margin:12px 0 4px;font-size:13px">Annual irrigation by crop</h3>
    ${rows}${moreN > 0 ? `<div style="font-size:11px;color:var(--text-mid);padding-top:4px">+ ${moreN} more crop${moreN > 1 ? "s" : ""}</div>` : ""}
    <p class="desc" style="margin-top:8px">Caveat: omits irrigation efficiency, dam-surface evaporation, and catchment fill; climate figures are SILO 2005-2024 normals for the selected location.</p>
  </div>`;
}

// Irrigation-dam summary card (only when the toggle is on).
function renderDamSection(p){
  if(!(typeof state !== "undefined" && state.irrigationDam)) return "";
  const dam = sizeDam(p);
  const fmtVol = (L) => L >= 1e6 ? `${(L/1e6).toFixed(2)} ML` : `${(L/1000).toFixed(0)} kL`;
  const aquaCrops = (p.selected || []).filter(s => cropHabitat(s.crop) === "aquatic").map(s => s.crop.name)
    .concat((p.lsSelected || []).filter(x => isAquaticLivestock(x.ls)).map(x => x.ls.name));
  const cropLandHa = (p.usedAnnualHa || 0) + (p.usedPerennialHa || 0) + (p.usedPastureHa || 0);
  return `<div class="adj-card">
    <h2>Irrigation dam</h2>
    <p class="desc">A dam sized to store the irrigation water above and grow fish &amp; aquatic crops on its surface. Storage is the maximum cumulative dry-season deficit; footprint assumes ${dam.depth} m average depth.</p>
    <div style="display:flex;flex-wrap:wrap;gap:22px;margin:10px 0">
      <div><div style="color:var(--text-mid);font-size:11px">Storage needed</div><strong style="font-size:17px">${fmtVol(dam.storageL)}</strong></div>
      <div><div style="color:var(--text-mid);font-size:11px">Dam capacity</div><strong style="font-size:17px">${fmtVol(dam.volumeL)}</strong></div>
      <div><div style="color:var(--text-mid);font-size:11px">Surface footprint</div><strong style="font-size:17px">${Math.round(dam.surfaceM2).toLocaleString()} m²</strong><div style="font-size:11px;color:var(--text-mid)">${dam.footprintHa.toFixed(3)} ha</div></div>
      <div><div style="color:var(--text-mid);font-size:11px">Depth</div><strong style="font-size:17px">${dam.depth} m</strong></div>
    </div>
    <div style="font-size:12px">Sized by <strong>${dam.bind}</strong>${dam.bind === "aquatic surface" ? " — the aquatic crops need more surface than the irrigation storage does, so the dam holds more than the irrigation requirement." : "."}</div>
    ${aquaCrops.length ? `<div style="font-size:12px;margin-top:6px">Grown on the water surface: ${aquaCrops.join(", ")}.</div>` : `<div style="font-size:12px;margin-top:6px;color:var(--text-mid)">No aquatic crops in this plan — the dam is purely irrigation storage.</div>`}
    <div style="font-size:12px;margin-top:6px">The dam adds <strong>${dam.footprintHa.toFixed(3)} ha</strong> of surface, on top of your ${cropLandHa.toFixed(2)} ha of cropped land.</div>
    <p class="desc" style="margin-top:8px">Caveat: assumes winter rain refills the dam (no catchment fillability check) and omits irrigation-efficiency losses and dam-surface evaporation — all of which push the true dam somewhat larger.</p>
  </div>`;
}

function renderStep6(){
  // Generate plan if missing
  if(!state.plan) state.plan = generatePlan(state);
  // Use adjusted plan if user has manual edits
  const p = (state.planAdjustments && Object.keys(state.planAdjustments).length) ? getAdjustedPlan() : state.plan;
  const sim = simulateAnnualConsumption(p, state.household, state.fertility, state.confidence);
  const targets = sim.targets;
  
  // ── Annual self-sufficiency stats ──
  const groups = FLOOR_KEYS.slice();
  const groupLabels = (function(){const o={};FG_KEYS.forEach(k=>o[k]=FG_DISPLAY[k].label);return o;})();
  const monthDays = [31,28,31,30,31,30,31,31,30,31,30,31];
  
  let monthsAllMet = 0, monthsPartialMet = 0;
  for(let i = 0; i < 12; i++){
    let allMet = true, anyMet = false;
    groups.forEach(k => {
      const target = targets[k] || 0;
      if(target <= 0) return;
      const supply = sim.consumption[k][i].supply;
      if(supply >= target * 0.8) anyMet = true;
      else allMet = false;
    });
    if(allMet) monthsAllMet++;
    else if(anyMet) monthsPartialMet++;
  }
  
  const totalConsumed = groups.reduce((sum, k) => sum + (sim.annualByGroup[k] || 0), 0);
  const totalNeeded = groups.reduce((sum, k) => sum + (targets[k] || 0) * 365, 0);
  const overallPct = totalNeeded > 0 ? Math.round(100 * totalConsumed / totalNeeded) : 0;
  
  // ── Donut chart: annual diet composition by food group ──
  const groupColors = (function(){const o={};FG_KEYS.forEach(k=>o[k]=FG_DISPLAY[k].color);return o;})();
  const donutData = groups.filter(k => sim.annualByGroup[k] > 0).map(k => ({
    key: k,
    label: groupLabels[k],
    value: sim.annualByGroup[k],
    color: groupColors[k]
  }));
  const donutTotal = donutData.reduce((s, d) => s + d.value, 0);
  
  // SVG donut chart
  const cx = 110, cy = 110, rOuter = 95, rInner = 55;
  let cumAngle = -Math.PI / 2;
  const donutSlices = donutData.map(d => {
    const angle = (d.value / donutTotal) * Math.PI * 2;
    const x1 = cx + rOuter * Math.cos(cumAngle);
    const y1 = cy + rOuter * Math.sin(cumAngle);
    const x2 = cx + rOuter * Math.cos(cumAngle + angle);
    const y2 = cy + rOuter * Math.sin(cumAngle + angle);
    const x3 = cx + rInner * Math.cos(cumAngle + angle);
    const y3 = cy + rInner * Math.sin(cumAngle + angle);
    const x4 = cx + rInner * Math.cos(cumAngle);
    const y4 = cy + rInner * Math.sin(cumAngle);
    const largeArc = angle > Math.PI ? 1 : 0;
    const path = `M ${x1} ${y1} A ${rOuter} ${rOuter} 0 ${largeArc} 1 ${x2} ${y2} L ${x3} ${y3} A ${rInner} ${rInner} 0 ${largeArc} 0 ${x4} ${y4} Z`;
    cumAngle += angle;
    return `<path d="${path}" fill="${d.color}" stroke="var(--card)" stroke-width="2"/>`;
  }).join("");
  
  const donutSvg = `<svg class="donut-svg" width="220" height="220" viewBox="0 0 220 220">
    ${donutSlices}
    <text x="110" y="105" text-anchor="middle" font-family="Inter,sans-serif" font-size="32" font-weight="700" fill="var(--green-dk)">${overallPct}%</text>
    <text x="110" y="125" text-anchor="middle" font-family="Inter,sans-serif" font-size="11" fill="var(--text-mid)">self-sufficient</text>
  </svg>`;
  
  const donutLegend = donutData.map(d => `<div class="donut-leg-row">
    <div class="donut-leg-swatch" style="background:${d.color}"></div>
    <span>${d.label}</span>
    <span class="donut-leg-pct">${Math.round(100*d.value/donutTotal)}%</span>
  </div>`).join("");
  
  // ── Monthly stacked bars ──
  // Find max total daily serves across all months to set scale
  let maxTotalDaily = 0;
  MONTHS.forEach((m, i) => {
    let total = 0;
    groups.forEach(k => { total += sim.consumption[k][i].supply; });
    if(total > maxTotalDaily) maxTotalDaily = total;
  });
  const targetTotal = groups.reduce((s, k) => s + (targets[k] || 0), 0);
  const chartMax = Math.max(maxTotalDaily, targetTotal * 1.2);
  
  const monthBars = MONTHS.map((m, i) => {
    let totalSupply = 0;
    groups.forEach(k => { totalSupply += sim.consumption[k][i].supply; });
    const pctOfTarget = targetTotal > 0 ? Math.round(100 * totalSupply / targetTotal) : 0;
    
    // Build stack segments (each food group split into fresh and stored)
    const segs = groups.map(k => {
      const cell = sim.consumption[k][i];
      const fresh = cell.fresh;
      const stored = cell.stored;
      const segs2 = [];
      if(fresh > 0){
        segs2.push(`<div class="mb-seg mb-seg-${k}" style="height:${(fresh/chartMax)*100}%" title="${groupLabels[k]} fresh: ${fresh.toFixed(1)} srv/day"></div>`);
      }
      if(stored > 0){
        segs2.push(`<div class="mb-seg mb-seg-${k} stored" style="height:${(stored/chartMax)*100}%" title="${groupLabels[k]} from storage: ${stored.toFixed(1)} srv/day"></div>`);
      }
      return segs2.join("");
    }).join("");
    
    const cls = pctOfTarget >= 100 ? "good" : pctOfTarget >= 70 ? "warn" : "bad";
    const targetLineTop = ((chartMax - targetTotal) / chartMax) * 100;
    
    const isActive = state.selectedMonth === m;
    return `<div class="mb-col ${isActive?'mb-active':''}" onclick="showMonthDetail('${m}')" title="Click to see ${m} harvest detail">
      <div class="mb-pct ${cls}">${pctOfTarget}%</div>
      <div class="mb-stack">
        <div class="mb-target-line" style="bottom:${(targetTotal/chartMax)*100}%" title="Daily target: ${targetTotal.toFixed(1)} srv/day"></div>
        ${segs}
      </div>
      <div class="mb-label">${isActive ? '▾' : m.charAt(0).toUpperCase()}</div>
    </div>`;
  }).join("");
  
  // ── Crop storage flow table — top contributors by annual consumption ──
  const topCrops = Object.entries(sim.cropAnnualContribution)
    .sort((a,b) => b[1] - a[1])
    .slice(0, 12)
    .map(([name, contribution]) => {
      const crop = p.selected.find(s => s.crop.name === name)?.crop;
      if(!crop) return null;
      const meta = sim.cropMeta[name];
      const monthly = sim.cropMonthly[name];
      const monthCells = MONTHS.map((m, i) => {
        const isHarvest = crop.months[m] === "P" || crop.months[m] === "S";
        const hasSupply = monthly[i] > 0.001;
        if(isHarvest) return `<span class="crop-flow-cell cf-harvest" title="${m}: fresh harvest ${monthly[i].toFixed(2)} srv/day"></span>`;
        if(hasSupply) return `<span class="crop-flow-cell cf-stored" title="${m}: from storage ${monthly[i].toFixed(2)} srv/day"></span>`;
        return `<span class="crop-flow-cell cf-none" title="${m}: unavailable"></span>`;
      }).join("");
      return `<tr>
        <td><strong>${name}</strong> ${tag(meta.group)}</td>
        <td style="font-size:10px;color:var(--text-mid)">${(()=>{const mo=crop.cool_store_months;if(mo==null)return "—";if(mo>=12)return "Long storage";if(mo>=2)return "Medium storage";if(mo>=0.5)return "Short storage";return "Fresh only";})()}</td>
        <td>${monthCells}</td>
        <td style="text-align:right;font-weight:600">${Math.round(contribution).toLocaleString()} srv/yr</td>
      </tr>`;
    }).filter(r=>r).join("");
  
  // ── Final assembly ──
  return `
    <div class="sum-hero">
      <h2>Annual diet summary</h2>
      <p>Month-by-month food availability with fresh harvest and stored surplus simulated across the year.</p>
      <div class="sum-hero-stats">
        <div class="sum-stat">
          <div class="sum-stat-val">${overallPct}%</div>
          <div class="sum-stat-lbl">Annual self-sufficiency</div>
        </div>
        <div class="sum-stat">
          <div class="sum-stat-val">${monthsAllMet}</div>
          <div class="sum-stat-lbl">Months all targets met</div>
        </div>
        <div class="sum-stat">
          <div class="sum-stat-val">${monthsPartialMet}</div>
          <div class="sum-stat-lbl">Months partial</div>
        </div>
        <div class="sum-stat">
          <div class="sum-stat-val">${12 - monthsAllMet - monthsPartialMet}</div>
          <div class="sum-stat-lbl">Months with deficits</div>
        </div>
      </div>
    </div>
    
    <div class="sum-cols">
      <div class="adj-card">
        <h2>Annual diet composition</h2>
        <p class="desc">Proportion of total annual food intake (serves) by food group, with storage contributions included.</p>
        <div class="donut-wrap">
          ${donutSvg}
          <div class="donut-legend">${donutLegend}</div>
        </div>
        <div style="font-size:11px;color:var(--text-mid);margin-top:8px;line-height:1.5">
          Dairy (${(targets.dairy||0).toFixed(1)} srv/day target) is not crop-producible and excluded — source externally.
        </div>
      </div>
      
      <div class="adj-card">
        <h2>Storage model</h2>
        <p class="desc">How the simulation handles each crop's availability across the year:</p>
        <div style="font-size:12px;line-height:1.7">
          <div><strong style="color:var(--green-dk)">Long Storage / Year-round Proc.</strong> — grain, nuts, dried legumes, root cellar crops. Annual harvest spread evenly across all 12 months.</div>
          <div style="margin-top:6px"><strong style="color:var(--clay)">Short Storage</strong> — apples, potatoes, pumpkins. Fresh during harvest, bridging 1–2 months after at 60%/30% of peak supply.</div>
          <div style="margin-top:6px"><strong style="color:var(--iron)">Fresh only</strong> — leafy greens, soft fruit. Available only in harvest months.</div>
        </div>
      </div>
    </div>
    
    <div class="adj-card">
      <h2>Monthly consumption flow</h2>
      <p class="desc">Daily serves available each month, stacked by food group. Click any month for a harvest breakdown. Solid = fresh. Hatched = from storage.</p>
      <div class="month-bars">
        <div class="mb-row-label">Daily<br>serves</div>
        ${monthBars}
      </div>
      ${(()=>{
        const sel = state.selectedMonth;
        if(!sel) return '';
        const mi = MONTHS.indexOf(sel);
        const monthName = sel.charAt(0).toUpperCase() + sel.slice(1);
        const totalSupply = groups.reduce((s,k) => s + sim.consumption[k][mi].supply, 0);
        const pct = targetTotal > 0 ? Math.round(100*totalSupply/targetTotal) : 0;
        const pctCls = pct >= 100 ? 'var(--green)' : pct >= 70 ? 'var(--clay)' : 'var(--iron)';

        // Build per-group harvest/storage crop lists
        const groupSections = groups.map(k => {
          const cell = sim.consumption[k][mi];
          if(cell.supply < 0.01) return '';
          const label = groupLabels[k];
          const color = groupColors[k];

          // Crops contributing to this food group this month
          const contributing = p.selected
            .filter(({crop}) => {
              // Use FG_KEY — the single authoritative food-group→key mapping
              const cKey = FG_KEY[effectiveFoodGroup(crop)];
              return cKey === k && (sim.cropMonthly[crop.name]?.[mi]||0) > 0.005;
            })
            .map(({crop}) => ({
              name: crop.name,
              isFresh: crop.months[sel] === 'P' || crop.months[sel] === 'S',
              srv: sim.cropMonthly[crop.name]?.[mi] || 0
            }))
            .sort((a,b) => b.srv - a.srv)
            .slice(0,8);

          if(!contributing.length) return '';
          const rows = contributing.map(c =>
            `<div class="mb-detail-crop">
              <span class="mb-detail-badge ${c.isFresh?'mb-fresh-badge':'mb-stored-badge'}">${c.isFresh?'FRESH':'STORED'}</span>
              <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${c.name}</span>
              <span class="mb-detail-srv">${c.srv >= 1 ? c.srv.toFixed(1) : c.srv.toFixed(2)} srv/day</span>
            </div>`
          ).join('');

          return `<div class="mb-detail-group" style="border-left-color:${color}">
            <div class="mb-detail-group-name">${label}</div>
            ${rows}
            <div style="font-size:10px;color:var(--text-mid);margin-top:5px;font-weight:600">Total: ${cell.supply.toFixed(1)} / ${(targets[k]||0).toFixed(1)} srv/day</div>
          </div>`;
        }).join('');

        // Livestock contributions (year-round) — dedicated section, all selected species
        const lsRows = (p.lsSelected||[])
          .map(({ls,count}) => {
            const daily = lsServesPerDay(ls, count);
            if(daily < 0.01) return '';
            return `<div class="mb-detail-crop">
            <span class="mb-detail-badge mb-ls-badge">LIVESTOCK</span>
            <span style="flex:1">${ls.name}</span>
            <span class="mb-detail-srv">${daily.toFixed(1)} srv/day</span>
          </div>`;
          }).join('');

        return `<div class="mb-detail" style="margin-top:12px;padding:12px;background:var(--card2);border:2px solid var(--green-lt)">
          <div class="mb-detail-header">
            <span class="mb-detail-month">${monthName} — harvest &amp; storage detail</span>
            <span class="mb-detail-pct" style="background:${pctCls};color:var(--card)">${pct}% of daily target</span>
          </div>
          <div class="mb-detail-groups">${groupSections||'<div style="color:var(--text-mid);font-size:12px">No crop supply this month.</div>'}</div>
          ${lsRows ? `<div style="margin-top:4px"><div class="mb-detail-group-name" style="margin-bottom:6px">LIVESTOCK (year-round)</div>${lsRows}</div>` : ''}
          <div style="text-align:right;margin-top:8px">
            <button class="btn btn-sec" style="font-size:11px;padding:4px 12px" onclick="showMonthDetail('${sel}')">Close ✕</button>
          </div>
        </div>`;
      })()}
      <div class="diet-legend">
        ${groups.filter(k => (targets[k]||0) > 0).map(k => `<div class="diet-leg-item">
          <div class="diet-leg-sq" style="background:${groupColors[k]}"></div>
          <span>${groupLabels[k]} (fresh)</span>
        </div>
        <div class="diet-leg-item">
          <div class="diet-leg-sq stored" style="background:${groupColors[k]}"></div>
          <span>${groupLabels[k]} (stored)</span>
        </div>`).join("")}
        <div class="diet-leg-item" style="margin-left:auto">
          <div style="width:12px;height:2px;background:var(--iron)"></div>
          <span>Daily target (${targetTotal.toFixed(1)} srv)</span>
        </div>
      </div>
    </div>
    
    <div class="adj-card">
      <h2>Top contributing crops</h2>
      <p class="desc">Top 12 crops by annual consumption volume, showing when each is fresh vs drawn from storage.</p>
      <table class="crop-flow-table">
        <thead>
          <tr>
            <th style="text-align:left">Crop</th>
            <th style="text-align:left">Storage</th>
            <th>${MONTHS.map(m=>`<span style="display:inline-block;width:18px;text-align:center;font-size:9px">${m.charAt(0).toUpperCase()}</span>`).join("")}</th>
            <th style="text-align:right">Annual</th>
          </tr>
        </thead>
        <tbody>${topCrops}</tbody>
      </table>
      <div style="display:flex;gap:14px;font-size:11px;margin-top:8px;color:var(--text-mid)">
        <span><span class="crop-flow-cell cf-harvest"></span> Fresh harvest</span>
        <span><span class="crop-flow-cell cf-stored"></span> From storage</span>
        <span><span class="crop-flow-cell cf-none"></span> Unavailable</span>
      </div>
    </div>
    
    ${renderIrrigationPreview(p)}

    ${renderDamSection(p)}

    ${(()=>{
      // ── Species Schedule table ──────────────────────────────────────────────
      const MNS = MONTH_NAMES, MKS = MONTHS;
      const soilKey3 = (state.soilTexture||"medium").toLowerCase().replace(/ .*/,"");
      const rain3 = state.annualRainfall||750;
      if(!p.selected||!p.selected.length) return "";
      const rows = p.selected.map((s,idx)=>{
        const c = s.crop;
        const latin = CROP_LATIN[c.name]||"—";
        const plantType = getCropPlantType(c);
        const space = c.h_max>0 ? c.h_max+"m H × "+(c.w_max||"?")+"m W" : "—";
        const fg = effectiveFoodGroup(c);
        const fgTag = FG_SHORT[fg]||fg;
        const storage = c.storability||"—";
        const hm = MKS.filter(m=>(c.months||{})[m]==="P");
        const hStart = hm.length ? MNS[MKS.indexOf(hm[0])] : "—";
        const hEnd   = hm.length>1 ? MNS[MKS.indexOf(hm[hm.length-1])] : hStart;
        const prep = getPrep(c);
        const soil3 = getSoilSuitability(c,soilKey3);
        const sc = soil3==="Ideal"?"#2A5C20":soil3==="Suitable"?"#5C7A3A":"#8C4A2A";
        const irr = getIrrigationNeeded(c,rain3);
        const ic = irr==="Essential"?"#8C4A2A":irr==="Likely"?"#C4823A":"#5C7A3A";
        const dr = getDroughtTolerance(c);
        const pc3 = plantCount(c,s.allocHa);
        const qty = pc3.label||fmtHa(s.allocHa);
        const bg = idx%2===0?"#F5F0E4":"#EFE9D8";
        const td = "padding:4px 5px;border-right:1px solid #C8B99A;";
        return "<tr style='background:"+bg+";font-size:9.5px'>"
          +"<td style='"+td+"font-weight:600;white-space:nowrap'>"+c.name+"</td>"
          +"<td style='"+td+"font-style:italic;color:#7A6A54;font-size:9px'>"+latin+"</td>"
          +"<td style='"+td+"white-space:nowrap'>"+plantType+"</td>"
          +"<td style='"+td+"text-align:right;white-space:nowrap'>"+qty+"</td>"
          +"<td style='"+td+"white-space:nowrap'>"+space+"</td>"
          +"<td style='"+td+"'>"+fgTag+"</td>"
          +"<td style='"+td+"white-space:nowrap'>"+storage+"</td>"
          +"<td style='"+td+"white-space:nowrap'>"+hStart+"</td>"
          +"<td style='"+td+"white-space:nowrap'>"+hEnd+"</td>"
          +"<td style='"+td+"font-size:9px'>"+prep+"</td>"
          +"<td style='"+td+"color:"+sc+";font-weight:600;white-space:nowrap'>"+soil3+"</td>"
          +"<td style='"+td+"color:"+ic+";font-weight:600;white-space:nowrap'>"+irr+"</td>"
          +"<td style='padding:4px 5px;font-size:9px;white-space:nowrap'>"+dr+"</td>"
          +"</tr>";
      }).join("");
      const th = "padding:5px;text-align:left;font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:0.04em;color:#7A6A54;border-right:1px solid #C8B99A;border-bottom:2px solid #A89878;white-space:nowrap;background:#EFE9D8";
      return "<div class='card' style='margin-top:14px;overflow-x:auto;page-break-before:always' id='speciesSchedule'>"
        +"<div style='display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;flex-wrap:wrap;gap:8px'>"
        +"<h2 style='margin-bottom:0'>Species Schedule</h2>"
        +"<span style='font-size:11px;color:var(--text-mid);font-style:italic'>All crops in this plan · Soil: "
        +state.soilTexture+" · Rainfall: "+rain3+"mm/yr · Print landscape for full reference</span></div>"
        +"<table style='width:100%;border-collapse:collapse;font-size:10px;font-family:Inter,sans-serif'>"
        +"<thead><tr>"
        +"<th style='"+th+"'>Common name</th>"
        +"<th style='"+th+"'>Scientific name</th>"
        +"<th style='"+th+"'>Crop type</th>"
        +"<th style='"+th+"'>Quantity</th>"
        +"<th style='"+th+"'>Space H×W</th>"
        +"<th style='"+th+"'>Food group</th>"
        +"<th style='"+th+"'>Storage</th>"
        +"<th style='"+th+"'>Harvest start</th>"
        +"<th style='"+th+"'>Harvest end</th>"
        +"<th style='"+th+"'>Preparation required</th>"
        +"<th style='"+th+"'>Soil suitability</th>"
        +"<th style='"+th+"'>Irrigation</th>"
        +"<th style='padding:5px;text-align:left;font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:0.04em;color:#7A6A54;border-bottom:2px solid #A89878;white-space:nowrap;background:#EFE9D8'>Drought tolerance</th>"
        +"</tr></thead><tbody>"+rows+"</tbody></table></div>"
        +"<style>@media print{@page{size:A3 landscape;margin:10mm}}</style>";
    })()}
    <div class="nav-row" style="margin-top:14px">
      <button class="btn btn-sec" onclick="goStep(4)">← Manual adjustment</button>
      <button class="btn btn-sec" onclick="(()=>{
        if(!state.plan){alert('Generate a plan first.');return;}
        const code = serializeSuccessionExport();
        const el = document.createElement('textarea');
        el.value = code; document.body.appendChild(el); el.select();
        try{navigator.clipboard.writeText(code).catch(()=>document.execCommand('copy'));}
        catch(e){document.execCommand('copy');}
        document.body.removeChild(el);
        alert('Succession export copied to clipboard! Paste it into the Succession Planner.');
      })()">Export for Succession Planner</button>
      <button class="btn" onclick="window.print()">Print / save PDF</button>
    </div>`;
}

// ── Step 7: Site Analysis panel (renders inside #app; map lives in #sp-panel) ──
function renderSpatialStep(){
  const sm=state.siteModel;
  if(!sm){
    return `<div style="padding:32px 24px">
      <h2 style="margin:0 0 12px">Site Analysis</h2>
      <p style="color:var(--text-mid)">Draw your farm boundary on the map, run terrain analysis and stage-4 design, then click <b>Apply Site Model to Planner</b>.</p>
      <p style="color:var(--text-mid);font-size:12px">Without a site model the planner uses the annual/perennial area budgets you entered on Farm Details.</p>
    </div>`;
  }
  const totalZoneHa=sm.zones.reduce((t,z)=>t+z.area_ha,0);
  const totalDamYield=sm.water.dams.reduce((t,d)=>t+(d.yield_kL||0),0);
  const pl = (state.plan && state.plan.placement) ? state.plan.placement : null;
  const fByName = {}; if(pl) pl.facets.forEach(f => fByName[f.name] = f);
  const zoneRows=sm.zones.map(z=>{
    const f = fByName[z.name];
    const crops = (z.assigned && z.assigned.length)
      ? z.assigned.map(a=>`${a.name} <span style="color:var(--text-mid)">(${a.ha} ha${a.layer&&a.layer!=='annual'?' · '+a.layer:''})</span>`).join(", ")
      : `<span style="color:var(--text-mid)">${pl ? "—" : "generate the farm plan first"}</span>`;
    return `<tr>
      <td>${z.name}</td>
      <td>${z.area_ha.toFixed(2)} ha</td>
      <td>${f ? f.usedHa.toFixed(2)+" ha" : "—"}</td>
      <td style="font-size:11px">${crops}</td>
    </tr>`;
  }).join("");
  const overflow = (pl && pl.unplaced.length)
    ? `<div class="lidcard" style="border-left:3px solid var(--bad,#cc5b48);margin-bottom:12px"><b>${pl.unplacedHa.toFixed(2)} ha did not fit any suitable facet</b><br><span style="font-size:11px;color:var(--text-mid)">${pl.unplaced.map(u=>`${u.name} (${u.ha} ha — ${u.reason})`).join("; ")}</span></div>`
    : "";
  const damRows=sm.water.dams.length?sm.water.dams.map((d,k)=>`
    <tr><td>${d.type} ${k+1}</td><td>${d.catchment_ha.toFixed(2)} ha</td><td>${Math.round(d.yield_kL).toLocaleString()} kL/yr</td></tr>`).join("")
    :`<tr><td colspan="3" style="color:var(--text-mid)">No dams identified</td></tr>`;
  return `<div style="padding:24px">
    <h2 style="margin:0 0 4px">Site Analysis — Active</h2>
    <p style="color:var(--text-mid);margin:0 0 16px">The nutrition plan is computed first; its crops are then <b>placed</b> onto the real per-facet areas below. Facets no longer constrain the plan — placement is downstream of allocation.</p>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:16px">
      <div class="lidcard"><b>Total mapped area</b><br>${sm.area_ha.toFixed(2)} ha</div>
      <div class="lidcard"><b>Facet coverage</b><br>${totalZoneHa.toFixed(2)} ha across ${sm.zones.length} facets</div>
      <div class="lidcard"><b>Swaleable area</b><br>${sm.water.swaleableArea_ha.toFixed(2)} ha</div>
      <div class="lidcard"><b>Dam yield</b><br>${Math.round(totalDamYield).toLocaleString()} kL/yr total</div>
    </div>
    ${overflow}
    <h3 style="margin:0 0 6px;font-size:13px">Facets &amp; placed crops</h3>
    <table style="width:100%;font-size:12px;border-collapse:collapse;margin-bottom:16px">
      <thead><tr style="background:var(--head-bg,#e8e1cd)"><th style="text-align:left;padding:4px">Facet</th><th>Area</th><th>Used</th><th style="text-align:left">Crops placed</th></tr></thead>
      <tbody>${zoneRows}</tbody>
    </table>
    <h3 style="margin:0 0 6px;font-size:13px">Water infrastructure</h3>
    <table style="width:100%;font-size:12px;border-collapse:collapse;margin-bottom:20px">
      <thead><tr style="background:var(--head-bg,#e8e1cd)"><th style="text-align:left;padding:4px">Dam</th><th>Catchment</th><th>Yield</th></tr></thead>
      <tbody>${damRows}</tbody>
    </table>
    <button class="btn" onclick="state.siteModel=null;state.plan=null;renderApp()">Clear Site Model (revert to single-area mode)</button>
  </div>`;
}

const STEPS=["Household","Farm Details","Crop Selection","Farm Plan","Manual adjustment","Summary"];

function addMember(){
  state.household.push({id: idSeq++, type: state.newMemberType});
  state.plan = null;
  renderApp();
}

function removeMember(id){
  state.household = state.household.filter(m => m.id !== id);
  state.plan = null;
  renderApp();
}

function canGoTo(n){
  if(n===6)return true; // Database always accessible
  if(n===7)return true; // Site Analysis always accessible
  if(n<=state.step)return true;
  if(n===1)return state.household.length>0 && state.hoursPerWeek>0;
  if(n===2)return !!state.climateZone && !!state.soilTexture && state.annualHa>0;
  if(n===3){ensureCheckedCrops();return state.checkedCrops.size>0;}
  if(n===4){ensureCheckedCrops();return state.checkedCrops.size>0;}
  if(n===5){ensureCheckedCrops();return state.checkedCrops.size>0;}
  return false;
}


function dbSetView(v){ state.dbView=v; renderApp(); }
function dbSetSort(s){ state.dbSort = state.dbSort===s ? s+"_desc" : s; renderApp(); }
function dbSetFilter(f){ state.dbFilter=f; renderApp(); }
function dbToggleLS(){ state.dbShowLivestock=!state.dbShowLivestock; renderApp(); }

function renderStepDB(){
  const q = (state.dbSearch||"").trim().toLowerCase();
  const MON_LBL = MONTH_INITIALS;  // module-level MONTHS used directly

  // ── Filter & sort crops ──────────────────────────────────────────────────
  let crops = [...CROP_DATA];
  if(q) crops = crops.filter(c =>
    c.name.toLowerCase().includes(q) ||
    (c.food_group||"").toLowerCase().includes(q) ||
    (c.edible_part||"").toLowerCase().includes(q) ||
    (c.cliz||[]).some(z => z.toLowerCase().includes(q))
  );
  if(state.dbFilter === "perennial")      crops = crops.filter(c => c.perennial);
  else if(state.dbFilter === "annual")    crops = crops.filter(c => !c.perennial);
  else if(state.dbFilter && state.dbFilter !== "all")
    crops = crops.filter(c => fgToKey(c.food_group) === state.dbFilter);

  const sortKey = state.dbSort||"name";
  const desc = sortKey.endsWith("_desc");
  const sk = sortKey.replace("_desc","");
  crops.sort((a,b) => {
    let av = sk==="name" ? a.name : sk==="yield" ? (a.yield_high||0) : sk==="labour" ? (a.labour_hand||0) : a.name;
    let bv = sk==="name" ? b.name : sk==="yield" ? (b.yield_high||0) : sk==="labour" ? (b.labour_hand||0) : b.name;
    if(typeof av === "string") return desc ? bv.localeCompare(av) : av.localeCompare(bv);
    return desc ? bv - av : av - bv;
  });

  const totalFiltered = crops.length;
  const view = state.dbView || "compact";

  // ── Toolbar ───────────────────────────────────────────────────────────────
  const filterSel = `<select class="cropq-sel" onchange="dbSetFilter(this.value)" style="min-width:140px">
    <option value="all" ${(state.dbFilter||"all")==="all"?"selected":""}>All crops</option>
    ${FLOOR_KEYS.concat(["herbs","discretionary"]).map(k=>`<option value="${k}" ${state.dbFilter===k?"selected":""}>${FG_DISPLAY[k].label}</option>`).join("")}
    <option value="perennial" ${state.dbFilter==="perennial"?"selected":""}>Perennial</option>
    <option value="annual" ${state.dbFilter==="annual"?"selected":""}>Annual</option>
  </select>`;

  const viewBtns = [["compact","≡ Compact"],["detailed","⊟ Detailed"]].map(([v,lbl]) =>
    `<button class="db-view-btn ${view===v?'active':''}" onclick="dbSetView('${v}')">${lbl}</button>`
  ).join("");

  const sortBtns = [["name","A–Z"],["yield","Yield ↕"],["labour","Labour ↕"]].map(([k,lbl]) =>
    `<button class="db-view-btn ${(state.dbSort||"name").replace("_desc","")==k?'active':''}" onclick="dbSetSort('${k}')">${lbl}</button>`
  ).join("");

  // ── Nutrition key pills helper ─────────────────────────────────────────────
  function nutPills(nut){
    if(!nut) return "";
    const show = [["kcal","kcal"],["protein","pro"],["fiber","fib"],["vitC","vit C"],["ca","Ca"],["fe","Fe"],["vitA","vit A"],["vitD","vit D"],["b12","B12"]];
    return show.filter(([k])=>nut[k]!=null && nut[k]>0)
      .map(([k,l])=>`<span class="db-nut-pill">${l}: ${nut[k]}</span>`).join("");
  }

  function monthDots(months){
    return MONTHS.map((m,i)=>{
      const v = months[m]; const cls = v==="P"?"p":v==="S"?"s":"";
      return `<div class="db-card-m ${cls}" title="${MON_LBL[i]}: ${v||'—'}"></div>`;
    }).join("");
  }

  // ── COMPACT view ─────────────────────────────────────────────────────────
  let body = "";
  if(view === "compact"){
    const hdr = `<div class="db-compact-row db-compact-hdr">
      <div onclick="dbSetSort('name')" style="cursor:pointer">Name ${(state.dbSort||"name")==="name"?"▴":(state.dbSort||"")==="name_desc"?"▾":""}</div>
      <div>Food group</div>
      <div onclick="dbSetSort('yield')" style="cursor:pointer">Yield ${(state.dbSort||"")==="yield"?"▴":state.dbSort==="yield_desc"?"▾":""}</div>
      <div onclick="dbSetSort('labour')" style="cursor:pointer">Labour</div>
      <div>Zones / Harvest</div>
      <div>Soils</div>
    </div>`;
    const rows = crops.map(c => {
      const yieldStr = `${c.yield_low||"?"}–${c.yield_high||"?"} t/ha`;
      const harv = MONTHS.filter(m => c.months?.[m]==="P"||c.months?.[m]==="S")
        .map(m=>m.charAt(0).toUpperCase()+m.slice(1,3)).join(", ") || "—";
      const zones = (c.cliz||[]).slice(0,4).join(" ");
      const soils = (c.text_tol||[]).join(" · ") || "—";
      return `<div class="db-compact-row">
        <div><strong>${c.name}</strong> ${c.perennial?'<span style="font-size:9px;color:#8B6914">·</span>':''}</div>
        <div style="color:var(--text-mid)">${(FG_SHORT[c.food_group]||c.food_group)||"—"}</div>
        <div style="font-weight:600;color:var(--green-dk)">${yieldStr}</div>
        <div style="color:var(--text-mid)">${c.labour_hand||"?"}h/ha</div>
        <div style="font-size:10px;color:var(--text-mid)">${zones} · ${harv}</div>
        <div style="font-size:10px;color:var(--text-mid)">${soils}</div>
      </div>`;
    }).join("");
    body = `<div class="db-compact">${hdr}${rows}</div>`;
  }

  // ── DETAILED view ─────────────────────────────────────────────────────────
  else {
    const ths = ["Name","Edible","Food group","Yield low","Yield high","Labour (h)","Zones","Soils","Temp min","Temp max","Rain min","pH min","pH max","Perennial","Storage"].map(h =>
      `<th>${h}</th>`).join("");
    const rows = crops.map(c => `<tr>
      <td><strong>${c.name}</strong></td>
      <td>${c.edible_part||"—"}</td>
      <td style="font-size:10px">${c.food_group||"—"}</td>
      <td style="text-align:right">${c.yield_low||"—"}</td>
      <td style="text-align:right">${c.yield_high||"—"}</td>
      <td style="text-align:right">${c.labour_hand||"—"}</td>
      <td style="font-size:10px">${(c.cliz||[]).join(" ")||"—"}</td>
      <td style="font-size:10px">${(c.text_tol||[]).join(" · ")||"—"}</td>
      <td style="text-align:right">${c.temp_opt_min||"—"}</td>
      <td style="text-align:right">${c.temp_opt_max||"—"}</td>
      <td style="text-align:right">${c.rain_min||"—"}</td>
      <td style="text-align:right">${c.ph_min||"—"}</td>
      <td style="text-align:right">${c.ph_max||"—"}</td>
      <td>${c.perennial?"Yes":"No"}</td>
      <td style="font-size:10px">${c.storability||"—"}</td>
    </tr>`).join("");
    body = `<div style="overflow-x:auto"><table class="db-table"><thead><tr>${ths}</tr></thead><tbody>${rows}</tbody></table></div>`;
  }

  // ── Livestock cards (collapsible) ─────────────────────────────────────────
  const lsSection = `<div class="adj-card" style="margin-top:14px;border-left:4px solid #8B6914">
    <div style="display:flex;align-items:center;gap:10px">
      <h2 style="margin:0">Livestock (${LIVESTOCK_DATA.length} species)</h2>
      <button class="db-view-btn ${state.dbShowLivestock?'active':''}" onclick="dbToggleLS()">${state.dbShowLivestock?'Hide':'Show'}</button>
    </div>
    ${state.dbShowLivestock ? `<div class="db-cards" style="margin-top:12px">${LIVESTOCK_DATA.map(ls => {
      const outTags = lsDisplayOutputs(ls).map(out => {
        const nutStr = out.nut ? [["kcal","kcal"],["protein","pro"],["fe","Fe"],["ca","Ca"],["vitD","vit D"],["b12","B12"]]
          .filter(([k])=>out.nut[k]!=null&&out.nut[k]>0).map(([k,l])=>`<span class="db-nut-pill">${l}: ${out.nut[k]}</span>`).join("") : "";
        return `<div style="margin-top:6px;padding:6px 8px;background:var(--card2);font-size:11px">
          <strong>${out.label}</strong> <span class="tag" style="font-size:9px">${out.food_group || "byproduct (fat)"}</span><br>
          <span style="color:var(--text-mid)">${(out.qty_per_animal_yr||0).toLocaleString()} ${out.unit}/animal/yr${out.serve_g ? " · serve "+out.serve_g+"g" : ""}</span><br>
          <div style="margin-top:3px">${nutStr}</div>
        </div>`;
      }).join("");
      return `<div class="db-card db-ls-card">
        <div class="db-card-name">${ls.name}</div>
        <div class="db-card-meta">
          <strong>Category:</strong> ${ls.category}<br>
          <strong>Space:</strong> ${ls.space_m2_per_animal} m²/animal<br>
          <strong>Labour:</strong> ${ls.labour_hrs_per_animal} hrs/animal/yr<br>
          <strong>Min count:</strong> ${ls.min_count} ${ls.unit_label}<br>
          <span style="color:var(--text-mid);font-size:10px">${ls.notes}</span>
        </div>
        ${outTags}
      </div>`;
    }).join("")}</div>` : ""}
  </div>`;

  return `
    <div class="adj-intro">
      <h2>Species database</h2>
      <p>Browse all ${CROP_DATA.length} crops and ${LIVESTOCK_DATA.length} livestock species. Switch views, filter by food group, or sort to explore.</p>
    </div>

    <div class="card">
      <div class="db-toolbar">
        <input class="db-search" placeholder="Search name, food group, climate zone…" value="${state.dbSearch||""}" onkeydown="if(event.key==='Enter'){state.dbSearch=this.value;renderApp()}" onblur="state.dbSearch=this.value;renderApp()"/>
        <span class="db-count">${totalFiltered} / ${CROP_DATA.length} crops</span>
      </div>
      <div class="db-toolbar" style="margin-bottom:10px">
        <label class="cropq-lbl">Food group</label>${filterSel}
        <div style="display:flex;gap:4px;margin-left:auto;flex-wrap:wrap">${sortBtns} &nbsp; ${viewBtns}</div>
      </div>
      ${body}
    </div>

    ${lsSection}

    <div class="nav-row">
      <button class="btn btn-sec" onclick="goStep(5)">← Summary</button>
    </div>`;
}


// ── Save / Load plan state ────────────────────────────────────────────────
function serializeSuccessionExport(){
  // Builds an enhanced save that includes the computed plan allocations
  const p = (state.planAdjustments && Object.keys(state.planAdjustments).length)
    ? getAdjustedPlan() : (state.plan || getAdjustedPlan());
  const base = JSON.parse(decodeURIComponent(escape(atob(serializeState()))));
  base._type = "succession_export";
  base._v = 2;
  base.planSnapshot = (p && p.selected || []).map(({crop, allocHa}) => ({
    name:      crop.name,
    allocHa:   Math.round(allocHa * 10000) / 10000,
    perennial: !!crop.perennial,
    food_group: crop.food_group || "",
    yield_low:  crop.yield_low  || 0,
    yield_high: crop.yield_high || 0,
    h_max:     crop.h_max  || 0,
    w_max:     crop.w_max  || 0,
    labour_hand: crop.labour_hand || 0,
    adg_serve_g: crop.adg_serve_g || 150,
    storability: crop.storability || "",
    months:    crop.months || {},
    edible_part: crop.edible_part || "",
  }));
  base.lsSnapshot = (p && p.lsSelected || []).map(({ls, count}) => ({
    name: ls.name, count,
    labour_hrs_per_animal: ls.labour_hrs_per_animal || 0,
    food_group: ls.food_group || "",
    yield_per_animal_kg_yr: ls.yield_per_animal_kg_yr || 0,
    adg_serve_g: ls.adg_serve_g || 150,
    scalable: ["Chicken","Duck","Guinea Fowl","Quail","Fish","Yabby"].some(k => ls.name.includes(k)),
  }));
  // Full annual crop objects so the succession planner can run the same algorithm
  base.annualCrops = (CROP_DATA || []).filter(c =>
    !c.perennial &&
    isSuitable(c) &&
    state.checkedCrops && state.checkedCrops.has(c.name)
  );
  try { return btoa(unescape(encodeURIComponent(JSON.stringify(base)))); }
  catch(e){ return ""; }
}
function serializeState(){
  const s = state;
  const out = {
    v: 2,
    household: s.household,
    hoursPerWeek: s.hoursPerWeek,
    labourSystem: s.labourSystem,
    fertility: s.fertility,
    confidence: s.confidence,
    climateZone: s.climateZone,
    town: s.town, lat: s.lat, lon: s.lon,
    climateEto: s.climateEto, climateRain: s.climateRain, climateLabel: s.climateLabel,
    climateTmax: s.climateTmax, climateTmin: s.climateTmin, climateTminext: s.climateTminext,
    soilTexture: s.soilTexture,
    annualRainfall: s.annualRainfall,
    annualHa: s.annualHa,
    perennialHa: s.perennialHa,
    pastureHa:        s.pastureHa,
    surfaceWaterHa:   s.surfaceWaterHa   || 0,
    irrigationDam:    s.irrigationDam    || false,
    damDepth:         s.damDepth         || 3,
    landFixed:        s.landFixed        !== false,
    hasIrrigation:    s.hasIrrigation    || false,
    waterSource:      s.waterSource      || "rainfed",
    objectives: s.objectives,
    checkedCrops: [...(s.checkedCrops || new Set())],
    checkedLivestock: [...(s.checkedLivestock || new Set())],
    livestock: s.livestock || {},
    planAdjustments: s.planAdjustments || {},
    foodGroupMin: s.foodGroupMin || {},
    showSuitableOnly: s.showSuitableOnly,
    step: s.step,
  };
  try { return btoa(unescape(encodeURIComponent(JSON.stringify(out)))); }
  catch(e){ return ""; }
}

function deserializeState(str){
  try {
    const obj = JSON.parse(decodeURIComponent(escape(atob(str.trim()))));
    if(!obj || obj.v < 1) return "Invalid plan code.";
    Object.assign(state, {
      household:       obj.household        || state.household,
      hoursPerWeek:    obj.hoursPerWeek     ?? state.hoursPerWeek,
      labourSystem:    obj.labourSystem     || state.labourSystem,
      fertility:       obj.fertility        || state.fertility,
      confidence:      obj.confidence       ?? state.confidence,
      climateZone:     obj.climateZone      || state.climateZone,
      town:            obj.town             ?? state.town,
      lat:             obj.lat              ?? state.lat,
      lon:             obj.lon              ?? state.lon,
      climateEto:      obj.climateEto       ?? state.climateEto,
      climateRain:     obj.climateRain      ?? state.climateRain,
      climateLabel:    obj.climateLabel     ?? state.climateLabel,
      climateTmax:     obj.climateTmax      ?? state.climateTmax,
      climateTmin:     obj.climateTmin      ?? state.climateTmin,
      climateTminext:  obj.climateTminext   ?? state.climateTminext,
      soilTexture:     obj.soilTexture      || state.soilTexture,
      annualRainfall:  obj.annualRainfall   ?? state.annualRainfall,
      annualHa:        obj.annualHa         ?? state.annualHa,
      perennialHa:     obj.perennialHa      ?? state.perennialHa,
      pastureHa:        obj.pastureHa        ?? state.pastureHa,
      surfaceWaterHa:   obj.surfaceWaterHa   ?? state.surfaceWaterHa,
      irrigationDam:    obj.irrigationDam    ?? state.irrigationDam,
      damDepth:         obj.damDepth         ?? state.damDepth,
      landFixed:        obj.landFixed        ?? state.landFixed,
      hasIrrigation:    obj.hasIrrigation    ?? state.hasIrrigation,
      waterSource:      obj.waterSource      ?? (obj.hasIrrigation ? "unlimited" : "rainfed"),
      objectives:      obj.objectives       || state.objectives,
      livestock:       obj.livestock        || {},
      planAdjustments: obj.planAdjustments  || {},
      foodGroupMin:    obj.foodGroupMin      || {},
      showSuitableOnly: obj.showSuitableOnly ?? true,
      checkedCrops:    new Set(obj.checkedCrops    || []),
      checkedLivestock:new Set(obj.checkedLivestock || []),
      step:            obj.step             ?? 0,
      plan:            null, // regenerate
      saveMsg: "✓ Plan loaded successfully!",
    });
    return null; // no error
  } catch(e){ return "Could not read plan code. It may be from an older version."; }
}

function openSaveModal(){
  state.showSaveModal = true;
  state.saveMsg = "";
  renderApp();
  // Select the code text after render
  setTimeout(() => { const el = document.getElementById("slCode"); if(el) el.select(); }, 80);
}

function closeSaveModal(){ state.showSaveModal = false; renderApp(); }

function copyPlanCode(){
  const el = document.getElementById("slCode");
  if(!el) return;
  el.select();
  try {
    navigator.clipboard.writeText(el.value).then(() => {
      state.saveMsg = "✓ Copied to clipboard!";
      renderApp();
    }).catch(() => {
      document.execCommand("copy");
      state.saveMsg = "✓ Copied!";
      renderApp();
    });
  } catch(e){
    document.execCommand("copy");
    state.saveMsg = "✓ Copied (fallback)";
    renderApp();
  }
}

function loadPlanCode(){
  const el = document.getElementById("slLoadCode");
  if(!el || !el.value.trim()){ state.saveMsg = "Paste a plan code first."; renderApp(); return; }
  const err = deserializeState(el.value.trim());
  if(err){ state.saveMsg = err; renderApp(); return; }
  state.showSaveModal = false;
  renderApp();
}

function renderSaveModal(){
  if(!state.showSaveModal) return "";
  const code = serializeState();
  return `<div class="sl-overlay" onclick="if(event.target===this)closeSaveModal()">
    <div class="sl-modal">
      <h3>Save / Load Plan</h3>
      <p style="font-size:12px;color:var(--text-mid);margin-bottom:10px">Copy this code to save your plan. Paste it back to restore — on any device, any browser.</p>

      <label style="font-size:11px;font-weight:600;color:var(--text-mid)">YOUR PLAN CODE</label>
      <textarea id="slCode" class="sl-code" readonly>${code}</textarea>
      <div class="sl-row">
        <button class="btn btn-lg" style="font-size:12px;padding:6px 16px" onclick="copyPlanCode()">Copy to clipboard</button>
      </div>

      <div style="margin-top:16px;border-top:1px solid var(--border);padding-top:14px">
        <label style="font-size:11px;font-weight:600;color:var(--text-mid)">LOAD A SAVED PLAN</label>
        <textarea id="slLoadCode" class="sl-code" placeholder="Paste a plan code here…"></textarea>
        <div class="sl-row">
          <button class="btn btn-lg" style="font-size:12px;padding:6px 16px;background:var(--green-dk)" onclick="loadPlanCode()">Load plan</button>
          <button class="btn btn-sec" style="font-size:12px;padding:6px 16px" onclick="closeSaveModal()">Cancel</button>
        </div>
      </div>
      <div class="sl-msg">${state.saveMsg||""}</div>
    </div>
  </div>`;
}

// Auto-load from URL hash on startup
(function(){
  const hash = window.location.hash;
  if(hash && hash.startsWith("#plan=")){
    const code = decodeURIComponent(hash.slice(6));
    deserializeState(code);
  }
})();

function setPlanTab(t){ state.planTab = t; renderApp(); }

function goStep(n){
  if(!canGoTo(n))return;
  state.step=n;
  if(n===6) state.dbSearch="";
  if(n===7) setTimeout(()=>typeof initSpatialMap==="function"&&initSpatialMap(),50);
  try {
    const code = serializeState();
    history.replaceState(null,"","#plan="+encodeURIComponent(code));
  } catch(e){}
  renderApp();
  window.scrollTo({top:0,behavior:"smooth"});
}

function renderApp(){
  // Show/hide the static spatial panel (Leaflet map, outside #app to survive re-renders)
  const sp=document.getElementById("sp-panel");
  if(sp) sp.style.display=(state.step===7)?"block":"none";

  const panels=[renderStep1,renderStep2,renderStep3,renderStep4,renderStep5,renderStep6];
  const panelFn = (state.step===6) ? renderStepDB : (state.step===7) ? renderSpatialStep : (panels[state.step]||renderStep1);

  // ── tiny 16px toolbar glyphs (muted line-art, 2000s style) ──
  const IC = {
    open:'<svg width="16" height="16" viewBox="0 0 16 16"><path d="M1 4h5l1 2h8v8H1z" fill="#D8A93E" stroke="#7C4D18"/><path d="M2 7h12l-1 6H2z" fill="#EFC766" stroke="#7C4D18"/></svg>',
    save:'<svg width="16" height="16" viewBox="0 0 16 16"><path d="M2 2h10l2 2v10H2z" fill="#5C7A3A" stroke="#3A5224"/><rect x="5" y="2" width="6" height="4" fill="#E8E1CD"/><rect x="4" y="9" width="8" height="5" fill="#E8E1CD"/></svg>',
    calc:'<svg width="16" height="16" viewBox="0 0 16 16"><rect x="2" y="1" width="12" height="14" fill="#E8E1CD" stroke="#6E6450"/><rect x="4" y="3" width="8" height="3" fill="#5C7A3A"/><g fill="#6E6450"><rect x="4" y="8" width="2" height="2"/><rect x="7" y="8" width="2" height="2"/><rect x="10" y="8" width="2" height="2"/><rect x="4" y="11" width="2" height="2"/><rect x="7" y="11" width="2" height="2"/><rect x="10" y="11" width="2" height="2"/></g></svg>',
    grid:'<svg width="16" height="16" viewBox="0 0 16 16"><rect x="2" y="2" width="12" height="12" fill="#FDFBF4" stroke="#6E6450"/><path d="M2 6h12M2 10h12M6 2v12M10 2v12" stroke="#CFC6AC"/><rect x="2" y="2" width="12" height="4" fill="#5C7A3A" fill-opacity=".25"/></svg>',
    chart:'<svg width="16" height="16" viewBox="0 0 16 16"><path d="M2 2v12h12" fill="none" stroke="#6E6450"/><rect x="4" y="8" width="2" height="5" fill="#5C7A3A"/><rect x="7" y="5" width="2" height="8" fill="#B5762F"/><rect x="10" y="9" width="2" height="4" fill="#A98C38"/></svg>',
    print:'<svg width="16" height="16" viewBox="0 0 16 16"><rect x="3" y="6" width="10" height="6" fill="#A89C7E" stroke="#6E6450"/><rect x="4" y="2" width="8" height="4" fill="#E8E1CD" stroke="#6E6450"/><rect x="4" y="10" width="8" height="4" fill="#FDFBF4" stroke="#6E6450"/></svg>',
    help:'<svg width="16" height="16" viewBox="0 0 16 16"><circle cx="8" cy="8" r="6.5" fill="#5C7A3A" stroke="#3A5224"/><text x="8" y="12" text-anchor="middle" font-family="Tahoma" font-size="9" font-weight="700" fill="#F5F0E4">?</text></svg>',
  };

  // ── step tabs + database tab ──
  const tabs=STEPS.map((s,i)=>{
    const cls=`sci-tab ${i===state.step?"active":i<state.step?"done":""} ${!canGoTo(i)?"disabled":""}`;
    const onclk=canGoTo(i)?`onclick="goStep(${i})"`:"";
    const no=i<state.step?"✓":"0"+(i+1);
    return `<div class="${cls}" ${onclk}><span class="tab-no">${no}</span>${s}</div>`;
  }).join("");
  const dbTab=`<div class="sci-tab dbtab ${state.step===6?"active":""}" onclick="goStep(6)"><span class="tab-no">DB</span>Species Database</div>`;
  const mapTab=`<div class="sci-tab dbtab ${state.step===7?"active":""}" onclick="goStep(7)" title="Site analysis &amp; spatial zone mapping"><span class="tab-no">🗺</span>Site Analysis${state.siteModel?` <span style="color:#5c9a3a;font-size:10px">●</span>`:""}</div>`;

  // ── status-bar data ──
  let zoneLbl="—";
  try{ const z=ZONES.find(z=>z.id===state.climateZone); if(z) zoneLbl=z.code||z.label; }catch(e){}
  let nCrops=0;
  try{ ensureCheckedCrops(); nCrops=state.checkedCrops?state.checkedCrops.size:0; }catch(e){}
  const stepLbl = state.step===6 ? "Species Database" : state.step===7 ? "Site Analysis" : STEPS[state.step];

  document.getElementById("app").innerHTML=`
    ${renderSaveModal()}
    <div class="sci-window">
      <div class="sci-titlebar">
        <span class="sci-tb-ico">${IC.calc}</span>
        <span class="sci-tb-title">Family Farm Planner — Australian Homestead Edition</span>
      </div>
      <div class="sci-toolbar">
        <div class="sci-tbtn" title="Open / load plan…" onclick="openSaveModal()">${IC.open}</div>
        <div class="sci-tbtn" title="Save plan…" onclick="openSaveModal()">${IC.save}</div>
        <div class="sci-tb-sep"></div>
        <div class="sci-tbtn" title="Species database" onclick="goStep(6)">${IC.grid}</div>
        <div class="sci-tbtn" title="Site analysis (spatial zones)" onclick="goStep(7)" style="font-size:13px">🗺</div>
        <div class="sci-tbtn" title="Compute / view farm plan" onclick="${canGoTo(5)?"goStep(5)":"void 0"}">${IC.calc}</div>
        <div class="sci-tbtn" title="Summary &amp; charts" onclick="${canGoTo(5)?"goStep(5)":"void 0"}">${IC.chart}</div>
        <div class="sci-tb-sep"></div>
        <div class="sci-tbtn" title="Print / save PDF" onclick="window.print()">${IC.print}</div>
        <div class="sci-tbtn" title="About" onclick="alert('Family Farm Planner — Australian Homestead Edition')">${IC.help}</div>
        <span class="sci-tb-doc">Project: <b>Homestead_2026.ffp</b></span>
      </div>
      <div class="sci-tabs">${tabs}${dbTab}${mapTab}</div>
      <div class="sci-panel step-panel">${panelFn()}</div>
      <div class="sci-status">
        <span class="sci-sb grow">${stepLbl}</span>
        <span class="sci-sb"><i class="sb-dot"></i>Zone: <b>${zoneLbl}</b></span>
        <span class="sci-sb">Selected: <b>${nCrops}</b> crops</span>
        <span class="sci-sb">DB: <b>${CROP_DATA.length + LIVESTOCK_DATA.length}</b> records</span>
        <span class="sci-sb">ADG · BOM · EcoCrop</span>
      </div>
    </div>`;
  // restore focus to a search field after full re-render (auto-search as you type)
  if(state._focusField){
    const el=document.getElementById(state._focusField);
    if(el){ try{ el.focus(); const v=el.value; el.value=""; el.value=v; }catch(e){} }
  }
  // collapse the pinned budgets/add-crop gaps once the block sticks to the top
  try{
    const pinned=document.querySelector(".adj-pinned");
    const sentinel=document.querySelector(".adj-stuck-sentinel");
    if(window.__adjStuckOb){ window.__adjStuckOb.disconnect(); window.__adjStuckOb=null; }
    if(pinned && sentinel && "IntersectionObserver" in window){
      window.__adjStuckOb=new IntersectionObserver(([e])=>{
        pinned.classList.toggle("is-stuck", !e.isIntersecting && e.boundingClientRect.top <= 0);
      }, {threshold:[0,1]});
      window.__adjStuckOb.observe(sentinel);
    }
  }catch(e){}
}

(async function startApp(){
  const appEl = document.getElementById('app');
  if(appEl) appEl.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:60vh;flex-direction:column;gap:16px;color:var(--text-mid)"><div style="font-size:40px">🌱</div><div style="font-size:16px;font-weight:600">Loading crop database…</div></div>';
  try{
    const r = await fetch('crops.json');
    if(!r.ok) throw new Error('HTTP '+r.status);
    const allData = await r.json();
    LIVESTOCK_DATA = allData.filter(c => c.is_livestock === true);
    CROP_DATA = allData.filter(c => !c.is_livestock);
    ensureCheckedLivestock();
  }catch(e){
    if(appEl) appEl.innerHTML = '<div style="padding:40px;text-align:center"><p style="color:red;font-weight:600">Failed to load crop database.</p><p style="color:var(--text-mid)">Please refresh the page. If running locally, open via a web server or GitHub Pages.</p><p style="font-size:11px;color:var(--text-mid)">Error: '+e.message+'</p></div>';
    return;
  }
  renderApp();
})();

/* ── Theme defaults (data attributes consumed by the stylesheet) ── */
(function(){
  const r = document.documentElement;
  r.dataset.accent  = 'olive';
  r.dataset.density = 'dense';
  r.dataset.finish  = 'beveled';
})();
